window.__D("text/torat-chaim/c033",{"p":[[2300550615,"שנתגלה פנימי' החסד[י'] לישראל ופנימי' הדין לאויב בענין א' וכמו בי' מכות דמצרים שהי' נגוף ורפוא נגוף למצרים ורפוא לישראל<sup data-n=\"5026\">431</sup> כמ\"ש במ\"א וד\"ל (וכמו והפכתי אבלם לששון<sup data-n=\"5027\">432</sup> [שזהו] יום ט' באב שנחרב בהמ\"ק שהי' [בו] דין קשה רק מצד עוצם האהבה<sup data-n=\"5028\">433</sup> המסותרת בו<sup data-n=\"5029\">*434</sup> בתוכחת קשה דאב מצד עוצם אהבת נפשו לבנו, ובהגלות אהבה הפנימי' שהי' בלבוש הדין הקשה אין חסד גדול מזה ונעשה מן האבל יו\"ט, ולכך קללות שבתוכחה יהי' לע\"ל ברכות<sup data-n=\"5030\">434</sup> ביותר [מ]גוף הברכות כנ\"ל<sup data-n=\"5031\">435</sup> שזהו חסד שמלובש בגבו'. וכך בכל יסורים דגלות שמתגלה עוצם אה\"ר הפנימיות שהי' בזה וע\"כ בגלות זה האחרון א[מר] העם ההולכים בחשך רא\"ו אור גדו\"ל<sup data-n=\"5032\">436</sup> לפ\"ע ריבוי זמן החשך, וממילא יובן בהיפוכו בשלות האויב שמשלם לשונאיו כו' שהוא כמו גחלים אתה כו' ואשר שלט לר\"ע לו מפני שמתגלה ג\"כ בחי' הפנימי' דדין שבאה מצד השנאה בתכלית עד שהי' מכוסה ונעלם ברוב טוב כמו זמן רב כ\"כ השנאה<sup data-n=\"5033\">*437</sup> [שניכר מן רוב הטובה דוקא] כמו שרואים שכל שהשנאה גוברת יותר יותר יסבול ממנו להטיב לו כדי שינקום ממנו אח\"כ יותר כו' וזהו ה\"ן ה\"ן גבורותי\"ו<sup data-n=\"5034\">437</sup> כו' וכן אין כמוך באלמים<sup data-n=\"5035\">438</sup> גוים מרקדי' בהיכלו<sup data-n=\"5036\">439</sup> כו') (אך עדיין אין זה התכללו' במעשה א' כי הדין לזה והחסד לזה וכמו\"כ כשנהפך ונתגלה הפנימי' כו', משא\"כ כמו בנגוף ורפוא הי' המעשה א' שהוא עצמו נעשה דין לזה וחסד לזה<sup data-n=\"5037\">440</sup> כמו שנגמר מן רב הטובים דוקא כמו<sup data-n=\"5038\">441</sup> הרפואה כו', ואלו<sup data-n=\"5039\">442</sup> לפי שלא נתמלאה צור<sup data-n=\"5040\">443</sup> אלא מחורבנה של ירושלים הרי שמדין [ה]קשה דחורבן בהמ\"ק הוא שנמשך חסד ושלוה לצור כמ\"ש כשזה קם זה נופל<sup data-n=\"5041\">444</sup> כו', וכן להיפך בבנין בהמ\"ק וירושלים דלע\"ל <span data-k=\"pg\">1042</span> ּ יהי' דין קשה לע\"ש הרי נחשב כמעשה א' שנעשה הדין לזה וחסד לזה כו' (וכמו ימינך ה' דחסד לישראל תרעץ אויב<sup data-n=\"5042\">445</sup> כו' וכן והנצח זו בנין ירושלים<sup data-n=\"5043\">446</sup> מבחי' גבורה ודין בנצח שבגבו' לאוה\"ע נעשה החסד דבנין ירושלים וכה\"ג). אך עצם<sup data-n=\"5044\">447</sup> יסורים של אהבה לצדיק[י'] ומשלם לשונאיו בשלות הרשעים הן ב' מיני עשי' הפכים ולא נק' התכללות ממש רק שמתכללי' במעשה א' דוקא אך שנעשה דין קשה<sup data-n=\"5045\">448</sup> לזה וחסד לזה כענין נגוף ורפוא לזה כנ\"ל) (ועכ\"ז ענין החורבן והגלות",[["5026","431","<b>נגוף למצרים ורפוא לישראל</b>: זהר בא לו, א. ראה גם לעיל פ' בא פז, א ואילך."],["5027","432","<b>והפכתי אבלם לששון</b>: ירמי' לא, יב. ראה מאמר ד\"ה זה במאמרי אדה\"ז נביאים ע' ריד ובהנסמן לשם."],["5028","433","<b>שנחרב בהמ\"ק. . האהבה</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רל."],["5029","*434","<b>בו</b>: יא: כו'."],["5030","434","<b>קללות שבתוכחה יהי' לע\"ל ברכות</b>: ראה גם לקמן פ' פקודי תמח, ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380286\" data-slug=\"likkutei-torah\" data-id=\"4001380286\">לקו\"ת בחוקותי מט, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450400\" data-slug=\"or-hatorah-hb\" data-id=\"8316450400\">אוה\"ת תבוא ע' תתרצד</a> ואילך [והוא דרוש אדה\"ז משנת תקס\"ו]. מאמרי אדה\"ז אתהלך לאזניא ע' פא. שע\"ת פה, ב. מאמרי אדה\"א דברים ח\"ב ע' תרסב. וש\"נ. במדבר ח\"ד ע' א'שמו. וש\"נ."],["5031","435","<b>כנ\"ל</b>: ביא: כו'."],["5032","436","<b>העם ההולכים בחשך רא\"ו אור גדו\"ל</b>: ישעי' ט, א."],["5033","*437","<b>ברוב טוב כמו זמן רב כ\"כ השנאה</b>: או: השנאה ברוב טובה כזו זמן רב כ\"כ. ביא: ברוב טובה כזו זמן רב כ\"כ השנאה."],["5034","437","<b>ה\"ן ה\"ן גבורותי\"ו</b>: יל\"ש נחמי' רמז תתרעא."],["5035","438","<b>אין כמוך באלמים</b>: ראה גיטין נו, ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרז. מאמרי אדה\"א קונטרסים ס\"ע תקעב ואילך. וש\"נ."],["5036","439","<b>גוים מרקדי' בהיכלו </b>[ביא: ליתא]: יומא סט, ב (כגי' הע\"י)."],["5037","440","<b>וכמו\"כ. . לזה</b>: ב: ליתא. וכנראה נשמט מפני תיבות הדומות: והחסד לזה. . וחסד לזה."],["5038","441","<b>שנגמר. . כמו</b>: ביא: סם."],["5039","442","<b>ואלו</b>: שם: ואולי."],["5040","443","<b>שלא נתמלאה צור</b>: רש\"י תולדות כה, כג. ראה מאמרי אדה\"א דברים ח\"א ע' ס ובהערה שם."],["5041","444","<b>כשזה קם זה נופל</b>: רש\"י שם."],["5042","445","<b>ימינך ה'. . תרעץ אויב</b>: בשלח טו, טו."],["5043","446","<b>והנצח זו בנין ירושלים</b>: דהי\"א כט, יא. ראה ברכות נח, א. לעיל פ' בשלח רכא, ד הערה 5."],["5044","447","<b>עצם</b>: ביא: עכ\"ז."],["5045","448","<b>קשה</b>: שם: ליתא."]]],[2300550622,"שהוא הגורם השלוה והגדולה דאוה\"ע כצור שנתמלאה כו' שזהו כמו מעשה א' ממש כשנחלק להיות דין לזה וחסד לזה כהיפוך זה דנגוף ורפוא כו' וכן לע\"ל כנ\"ל וכמו במ\"ת שירדה שנאה לאוה\"ע<sup data-n=\"5046\">449</sup> [כו']).\n<b>(וענין</b> התכללות דגבו' שבחסד עם חסד שבגבורה בלב דוקא יובן יותר מענין ב' מדרגות דאוי\"ר דאברהם ויצחק<sup data-n=\"5047\">450</sup> שבאברהם הי' יראה [מ]בפני[ם] ואהבה מבחוץ וביצחק הי' יראה מבחוץ ואהבה מבפנים, כענין במקום גילה שם תהא רעדה<sup data-n=\"5048\">451</sup> אם רעדה מבחוץ וגילה מבפנים או רעדה מבפנים וגילה מבחוץ כמו ב' שרים שיושבים במשתה לפני<sup data-n=\"5049\">452</sup> המלך לשמוח עמו בשמחתו זה יגיל וישמח מבחוץ בריקוד וכה\"ג לעשות נח\"ר למלך (כדוד שהי' מפזז ומכרכר בכל עוז<sup data-n=\"5050\">453</sup> כמ\"ש ושחקתי לפני ה'<sup data-n=\"5051\">454</sup> ) ובודאי רעדה ואימת מלך בלבו [מ]בפני' (כמו שהי' דוד בביטול [ו]יראה<sup data-n=\"5052\">455</sup> בפנימי' כו'), וזה יגיל וישמח בפנימי' ורעדה מבחוץ ושניהם כא' עושים נח\"ר למלך. וכמ\"כ או' וכל הלבבות ייראוך<sup data-n=\"5053\">456</sup> מבפנים וכל קרב וכליות יזמרו לשמך<sup data-n=\"5054\">457</sup> מבחוץ או להיפך קרב וכליות יזמרו מבפנים ולבבות ייראוך מבחוץ. וזהו בחי' התכללו' בלב מגבו' שבחסד עם חסד שבגבו' כא' בתנועה א' בקול ניגון ושיר היוצא מן הלב בחדוה ומרירות יחד שבחדוה יש מרירות בהעלם ובמרירות יש חדוה בהעלם, כמו בכי' תקיע' בלבאי<sup data-n=\"5055\">458</sup> מסט' דא וחדוה מסט' דא ושניהם כא' מתכללי' יחד בקול וניגון ושיר א' בתערובות ומזיגה א', וכענין התכללות דאדום וישמעאלי' יחד כידוע בענין ניגוני הישמעאלים שהוא בעוצב ומרירות לפי שהוא בבחי' החסד ונגינו' היוונים<sup data-n=\"5056\">459</sup> בחדוה לפי שהוא בבחי' [ה]גבורה שזהו ענין בנוהי דאברהם בגלותא דאדום<sup data-n=\"5057\">460</sup> כו' וד\"ל).\n(יג) <b>והנה</b> ע\"ד הנ\"ל יש התכללו' מגבורה שבחסד בקו הימין עם הוד שבגבו' שבקו השמאל (שזהו כמו דרומית רומית עם צפוני' תחתית) ומחסד שבגבו' עם נצח שבחסד (שזהו כמו צפוני' רומי' עם דרומי' תחתי' הנ\"ל). ואמנם הנה כל בחי' התכללו' די\"ב ג\"א בו' מדות [הנ\"ל] היינו דוקא בהיות[ן] בלב",[["5046","449","<b>במ\"ת שירדה שנאה לאוה\"ע</b>: שבת פט, א."],["5047","450","<b>דאוי\"ר דאברהם ויצחק</b>: ראה גם לעיל שכג, ג ובהנסמן שם."],["5048","451","<b>במקום גילה. . רעדה</b>: ראה גם לעיל שכב, ד ובהערה שם."],["5049","452","<b>לפני</b>: ביא: ליתא."],["5050","453","<b>מפזז ומכרכר בכל עוז</b>: שמו\"ב ו, יד. טז."],["5051","454","<b>ושחקתי לפני ה'</b>: שם שם, כא."],["5052","455","<b>דוד בביטול [ו]יראה</b>: ראה גם שע\"ת ח, א."],["5053","456","<b>וכל הלבבות ייראוך</b>: תפלת נשמת לשויו\"ט. ראה גם מאמרי אדה\"א שמות ח\"א ע' מז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670348\" data-slug=\"torat-chaim\" data-id=\"2300670348\">תו\"ח בראשית לט, ב</a>. לקמן פ' פקודי תנח, ד."],["5054","457","<b>לשמך</b>: ביא: ליתא."],["5055","458","<b>בכי' תקיע' בלבאי</b>: נסמן לעיל שכב, ד הערה 175."],["5056","459","<b>ניגוני הישמעאלים. . היוונים</b>: ראה גם מאמרי אדה\"א נ\"ך ע' מה. וש\"נ."],["5057","460","<b>בנוהי דאברהם בגלותא דאדום</b>: ראה זהר (רע\"מ) פינחס ריח, סע\"ב. לעיל פ' שמות יג, ג. וש\"נ."]]],[2300550628,"דוקא כנ\"ל שאע\"פ שבלב מתפעל בחסד בפ\"ע [ודין בפ\"ע] וכשהוא בחסד לא יפעול דין וכשהוא בדין לא יפעול חסד, עכ\"ז יש התכללו' דחו\"ג בלב באופן שיהי' חסד בדין ודין בחסד ואהבה ביראה ויראה באהבה וכן חדוה ומרירות יחד כנ\"ל לפי שניכר כאו\"א בפ\"ע ע\"כ יתכללו זע\"ז ג\"כ. משא\"כ במוח שהמדות שבשכל הן מתחלקים רק בכלל לחו\"ג בבחי' הדעת שנוטה כלפי חסד או כלפי דין שהן ו' מדות בחסד וו' מדות בגבורה (והוא ענין ב' אבני שוהם שבב' כתפות האפוד כמשי\"ת). <span data-k=\"pg\">תקכא</span> ּ ושרש טעם הדבר מה שבלב מתכללים המדות יותר זהו לפי שמבואר למעלה בענין ב' חללים שבלב שהן בחי' רוח ונפש ורוח החיים שבלב שרשו ממוח החכ' [קר ולח] בבחי' החסדים ונפש שבחלל השמאלי שרשו במוח בינה שהוא חם ויבש<sup data-n=\"5058\">461</sup> בבחי' גבורה והן ב' מוחין דחו\"ב שכוללים לחו\"ג כידוע ובבחי' מוח הדעת הוא שמתחלקי'<sup data-n=\"5059\">462</sup> (כמשי\"ת). ואמנם בהגיע אור וחיות המוחין דחו\"ב בלב (כקנה וושט שנק' שר המשקים ושר האופים<sup data-n=\"5060\">463</sup> כמ\"ש במ\"א) אזי הם שמתכללי' יחד בדרך פרט כנ\"ל בהתכללו' דחו\"ג בכל פרטיהן, לפי שבחי' נפש שבחלל השמאלי מתאחד ברוח החיים שבחלל הימיני כנ\"ל הענין בב' דפיקו' בלב בבחי' רו\"ש, שהעלאת הדם הוא הנפש בחלל השמאלי שנמשך ממוח בינה בבחי' מקור הגבורה<sup data-n=\"5061\">464</sup> הוא שעולה חיות המובחר שבו להתאחד וליכלל באור חיים<sup data-n=\"5062\">465</sup> הרוחני' שבחלל הימיני הנמשך ממוח החכ' דבחי' מקור החסד[ים] וחוזר ונמשך מחלל הימיני לחלל השמאלי בבחי' שוב שהוא דפיקו הב'. ונמצא דמה שהי' ב' מוחין דחו\"ב שכוללי' לחו\"ג בלתי מתחברים יחד אלא כ\"א בפ\"ע, אבל בהגיע שפעם ללב דוקא ששם מתכללים בחי' רוח ונפש כדו\"נ גבורה דנוק' בחסדים דדכורא וחסד דדכורא בגבו' דנוק', לפי שמתאחדי' ב' החללים יחד להשפיע רב טוב מחיבורם יחד לכל האברים אור וחיות חדש שהוא כלול מנפש ורוח, א\"כ הרי בלב מתחברים יחד<sup data-n=\"5063\">466</sup> ומתייחדים חו\"ג דחו\"ב שבמוח שהוא מזיגה הכלולה מחסדים דחכ' קר ולח שרש חיים<sup data-n=\"5064\">467</sup> הרוחני' שברוח החיים שבחלל הימיני ומחום ויובש דרוח<sup data-n=\"5065\">468</sup> בינה בחי' הגבורה שבחלל השמאלי (והוא ענין חיות רוחני שבדם הוא הנפש שבדופק היד כמ\"ש במ\"א בענין נגעים שהוא הסתלקו' אור או\"א<sup data-n=\"5066\">469</sup> דאד\"ם א' ד\"ם<sup data-n=\"5067\">470</sup> הוא א' דחכ' שמאיר בדם הוא גבו' דבינה<sup data-n=\"5068\">*471</sup> וזהו דפ\"ק קפ\"ד אחוריי' דאבא<sup data-n=\"5069\">471</sup> כו', ולזאת עיקר האד\"ם חיבור א' בד\"ם שזהו התכללות דחו\"ג [ד]חו\"ב שבראש הוא בלב דוקא ששם מתחברים ומתכללים בהתכללו' דרוח ונפש ולא במוחין שבראש (ואע\"פ",[["5058","461","<b>ממוח החכ' [קר ולח]. . בינה שהוא חם ויבש</b>: ראה גם לעיל פ' שמות כז, ג. וש\"נ."],["5059","462","<b>לחו\"ג. . הדעת הוא שמתחלקי'</b>: ראה ע\"ח (שער דרושי הצלם) שכ\"ה, דרוש ב כלל יז. לקמן הערה 501."],["5060","463","<b>כקנה וושט שנק' שר המשקים ושר האופים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370453\" data-slug=\"torah-or\" data-id=\"3901370453\">תו\"א ויחי קב, ג</a>. לעיל פ' וארא עא, ג הערה 16."],["5061","464","<b>בינה בבחי' מקור </b>[ביא: דמקור]<b> הגבורה</b>: ראה גם לעיל פ' בא צו, א. וש\"נ."],["5062","465","<b>באור חיים</b>: שם: ברוח החיים."],["5063","466","<b>יחד</b>: שם: ליתא."],["5064","467","<b>חיים</b>: שם: (ה)חיות."],["5065","468","<b>דרוח</b>: שם: דמוח."],["5066","469","<b>נגעים שהוא הסתלקו' אור או\"א</b>: ראה זהר תזריע מט, ב (ובביאוה\"ז שם). ע\"ח (שער לאה ורחל) של\"ח, פ\"ז. מאמרי אדה\"ז תקס\"ה ח\"א ע' תכג ואילך. מאמרי אדה\"א ויקרא ח\"ב ע' תנג וע' תעג ואילך."],["5067","470","<b>דאד\"ם א' ד\"ם</b>: ראה מבוא שערים ש\"ה, ח\"ב פ\"ה. לעיל פ' וארא עב, ד הערה 22."],["5068","*471","<b>א' דחכ'. . בדם. . דבינה</b>: ראה גם לקמן פ' פקודי תנט, ב. וש\"נ."],["5069","471","<b>דפ\"ק קפ\"ד אחוריי' דאבא</b>: ראה גם לעיל פ' בא קד, ג. וש\"נ."]]],[2300550634,"שבחי' מוח הדעת כולל חו\"ג<sup data-n=\"5070\">472</sup> (כמשי\"ת) וכמ\"ש במ\"א שבלב דוקא שם יחוד דב' שמות<sup data-n=\"5071\">473</sup> [ד]הוי' ואלק\"י' שהן חו\"ג<sup data-n=\"5072\">474</sup> דחו\"ב כנ\"ל וכמ\"ש וידעת היום והשבות אל לבב\"ך<sup data-n=\"5073\">475</sup> דוקא, וזהו וייחד לבבינו ב' לבבות<sup data-n=\"5074\">476</sup> דרוח ונפש כנ\"ל, והוא כללות ענין המקדש דכתי' ועשו לי מקדש ושכנתי בתוכם שהוא בלב דכנ\"י<sup data-n=\"5075\">477</sup> דוקא מטעם הנ\"ל שזהו עיקר בחי' אד\"ם אע\"פ שעיקר האדם הוא החכ' שבראש כו', וזהו עיקר ענין די\"ב אבני החשן שבלב אהרן דוקא (כמשי\"ת). ובכ\"ז יובן עיקר הטעם לסיבת התכללות כל המדות זע\"ז שהוא בלב דוקא מטעם שהחיבור ב' החללים דרוח ונפש יחד להשפיע אור וחיות כללי [שכלול] מרו\"ש דחו\"ג שבחו\"ב בהילוך הדם הוא הנפש עם רוח החיים שבו בכל האברים כנ\"ל וד\"ל.\n<b>(ועם</b> טעם זה דהתכללות רוח ונפש בב' החללים דלב, יובן שרש כללי לענין התכללו' דמדות חו\"ג בלב בדבר והיפוכו ממש כמשלם לשונאיו כו' ויסורים לצדיקים וכמוכיח לב[ניו] ביסורים, וכענין הגלות שמלובש חסד בדין ודין בחסד במעשה א' מצד התכללות דגבורה דדמים בחלל השמאלי בחסדים דחלל הימיני <span data-k=\"pg\">1044</span> ּ וחסדים [ד]חלל הימני בחלל השמאלי יש מקום א' לסבול חו\"ג כא' ממש (משא\"כ במוח שכאשר השכל נוטה לחסד לא יסבול להיפך שלו [כלל] כמו שרואים בשני חכמים זה אוסר וזה מתיר שלא ימצאו [מיצוע] להכלל יחד כ\"א כ\"א מחולק לדיעה בפ\"ע לפי ששכל זה מחסדים דחכ' כו' ואין לו חיבור עם הגבורה ודין שבשכל [כלל] (כמשי\"ת). ויותר נראה זה בלב בהתכללות דאהוי\"ר או חדוה ומרירות כנ\"ל שישכנו במקום א' ובענין א' וכמו [ו]גיל[ו] ברעדה זה בפנים וזה בחוץ בהתאחדו' גמורה כו'. ועוד יותר נראה התכללו' זו בבחי' קול ושיר היוצא מהבל הלב שכלול ממש מחדוה ומרירות שזהו רו\"ש שבאים בהתכללו' דרוח ונפש שבב' החללים יחד והיינו לפי שהניגון דוקא [יוצא] מחיבור שניהם מרוח החיים שבחלל הימיני בקנה ונפש שבדם שבחלל השמאלי כלולה מיסוד מים ואש יחד).\n<b>והנה</b> בכל דוגמא הנ\"ל בהתכללות דרוח ונפש בב' חללים שבלב באדם התחתון יובן ג\"כ ענין בחי' התכללות דמדות דחו\"ג בלב אדה\"ע שעל הכסא כו'. דהנה מבואר למעלה בענין הקרבנות דהעלאות הדם בקרבנו' עולה בבחי' פני שור שבמרכבה ומשם עולה [ל]בחי' לב העליון (ועכשיו התפלה",[["5070","472","<b>מוח הדעת כולל חו\"ג</b>: ראה גם לעיל פ' וארא נז, ד. וש\"נ."],["5071","473","<b>שבלב דוקא שם יחוד דב' שמות</b>: ראה גם לעיל פ' תרומה שה, ג (ובהנסמן בריש המאמר שם)."],["5072","474","<b>[ד]הוי' ואלק\"י' שהן חו\"ג</b>: ראה גם מאמרי אדה\"א הנחות תקע\"ז ע' רח. לעיל פ' בא פח, ד. וש\"נ."],["5073","475","<b>וידעת. . אל לבב\"ך</b>: ואתחנן ד, לט."],["5074","476","<b>וייחד לבבינו ב' לבבות</b>: ראה גם לעיל פ' תרומה דש, ג. וש\"נ."],["5075","477","<b>ועשו לי מקדש. . בלב דכנ\"י</b>: ראה גם לעיל שם."]]],[2300550640,"כקרבן בבחי' רץ לבך בהתלהבות רשפי אש האלקי בחלל השמאלי שבדם הוא הנפש שנכלל ברוח שבחלל הימיני כו') ועי\"ז הרי נמשך מלמעלה מן המוחי' [דאדם] תוס' אור חדש ברוח החיים שבלב מבחי' העצמו' דא\"ס שנק' חיי החיים<sup data-n=\"5076\">478</sup> כו', ומתאחד ומתכלל בהעלאה זו דדם הוא הנה\"ב דקרבן שעולה לריח ניחוח לה' למעלה מעלה כנ\"ל. וע\"כ<sup data-n=\"5077\">479</sup> ממילא מובן שע\"י הקרבנות שנעשה לריח ניחוח כו' מתכללי' בחי' רוח ונפש שבלב אדה\"ע שהוא התכללות דחו\"ג שבמוחין דחו\"ב דאדם הנ\"ל, וא\"כ ודאי ממילא מובן שמטעם זה עיקר בחי' התכללו' המדות העליונו' דאצי' זע\"ז (כמו ברוגז רחם תזכור<sup data-n=\"5078\">480</sup> וכמו [כי] רגע באפו אז דוקא חיים ברצונו<sup data-n=\"5079\">481</sup> וכמ\"ש יה\"ר מלפניך שיכבשו רחמיך את כעסך<sup data-n=\"5080\">482</sup> וכה\"ג וכמשלם לשונאיו כו'<sup data-n=\"5081\">483</sup> ) ביחודים שונים בכמה מיני אופני' רבים מאד הכל הוא מצד שבא ונמשך האורות דמוחין דחו\"ב בלב אדה\"ע דוקא, והוא ענין י\"ב ג\"א דו\"ק העליונות דאצי' כנ\"ל שבא ונמשך גם בשבטים דבריאה. וזה שא' השבטים<sup data-n=\"5082\">484</sup> כשם שאין בלבך דוקא אלא אחד בהתכללות דו\"ק כך אין בלבינו כו' (והוא שנק' צבאות הוי' דבחי' אדם שבזה השבטי' שרשם יותר עליון גם מן האבות שהן בבחי' חג\"ת כנ\"ל (וכמשי\"ת).\n(יד) <b>ובכ\"ז</b> יובן ג\"כ בטעם ענין [י\"ב אבני החשן שעל לבו של אהרן שהן י\"ב שמות השבטים שבעולם הבריאה שעולין באצי' כמ\"ש ששם עלו שבטים שבטי כו' והן] י\"ב ג\"א דו\"ק דמל' דאצי' בבריאה, הרי הן בבחי' התכללו' זע\"ז בהיותם חקוקים באבנים הללו בחשן שעל לבו דוקא. וע\"כ הי' החשן על לבו דוקא לפי שבלב שם הוא בחי' ההתכללו' דוקא מטעם הנ\"ל שמתחברים רוח ונפש שהן בחי' חו\"ג הכללי דחו\"ב שבראש כו', שהרי בלב הרי בחלל השמאלי שם הוא בחי' [ה]העלאה דנה\"ב שיתחבר בו נשמת רוח החיים שבחלל הימיני כו' כנ\"ל. וזהו ונשא אהרן את שמות בנ\"י<sup data-n=\"5083\">485</sup> בחשן המשפט על לבו דוקא <span data-k=\"pg\">תקכב</span> ּ לזכרון לפני ה' תמיד שזהו בחי' ההעלאה דנש\"י שבגופים שנזדככו מחומריות שלהם בהעלאות דדם הוא הנפש כנ\"ל כמ\"ש<sup data-n=\"5084\">486</sup> לך אמר לבי כו' וכן צמאה לך נפשי כו' וחוזר ונמשך ממוח דחכ' ששם הוא בחי' הזכרון כנ\"ל וד\"ל.\n<b>אך</b> עדיין י\"ל בגוף ענין ההתכללו' די\"ב אבני החשן [הנ\"ל], דלכאורה הלא<sup data-n=\"5085\">487</sup> הן מספר י\"ב אבנים כאו\"א בפ\"ע מיוחד במראיתו ובמינו כפי שרשו של אותו השבט ואין א' דומה לחבירו כלל, ויש מקום מיוחד לכל א' בפ\"ע דוקא כמו אבן טוב דאודם מובדל מאבן פטדה במראה ובמקום כו', כפי",[["5076","478","<b>חיי החיים</b>: ראה יומא עא, א."],["5077","479","<b>וע\"כ</b>: ביא: ועי\"ז."],["5078","480","<b>ברוגז רחם תזכור</b>: חבקוק ג, ב. או: רחמים — נסמן לעיל פ' בא פז, ב."],["5079","481","<b>[כי] רגע באפו. . חיים ברצונו</b>: תהלים ל, ו."],["5080","482","<b>יה\"ר. . את כעסך</b>: סדר תקיעת שופר בסידור האריז\"ל [בדילוג]."],["5081","483","<b>כו'</b>: ביא: כנ\"ל."],["5082","484","<b>השבטים</b>: שם: ליתא."],["5083","485","<b>ונשא אהרן את שמות בנ\"י</b>: תצוה כח, כט."],["5084","486","<b>כנ\"ל כמ\"ש</b>: ביא: שבלב כו' וכמ\"ש."],["5085","487","<b>הלא</b>: שם: הרי."]]],[2300550646,"חילוקי שרשי השבטי' למעלה כך יהי' מראה כל אבן שיהי' שמו חקוק עליו לזכרון לפני ה' כו'. ואמנם עכ\"ז הרי כל הי\"ב אבנים היו חקוקים בחשן כולם ביחד דוקא דהיינו שבאמצעות כולם יחד דוקא הן עולים לזכרון לפני ה' ולא כל א' בפ\"ע כמ\"ש ששם עלו שבטים כו', לפי ששרש א' לכולם יחד בהיותם חקוקים על לבו של אהרן דוקא ששם הוא בחי' ההתכללו' [דוקא] והי' כל אבן כלול גם ממדריגת זולתו כמו כל שבט שיש בו התכללות מזולתו, לפי שי\"ב צרופים דשם הוי' כלולים כא' בשם הוי' וכמו י\"ב ג\"א, ובפרט בבחי' העלאה למעלה כמ\"ש לך ה' הגדולה והגבו' שהם ביטול והתכללות דו\"ק כו', וכן הנה מקום אתי כו' כנ\"ל לפי ששם הוי' שבעצמות [א]א\"ס שורה עליהם כשנק' צבאות ה' ונק' ה' צבאות כו' וכמ\"ש אנת הוא דמייחד לון<sup data-n=\"5086\">488</sup> כו' (והוא בחי' אד\"ם כמו שאברי [ה]אדם כלולים זע\"ז מבלי שימצא ראש וסוף<sup data-n=\"5087\">489</sup> כ\"א מקבל מחבירו וגם משפיע לו ובאמצעית כולם יחד דוקא נק' אדם שאין שלימות לא' בלא זולתו כלל כו', וראי' ממ\"ת דכתיב ויחן ישראל<sup data-n=\"5088\">490</sup> כאיש אחד ממש כו', וכן אנו אומרים ברכינו אבינו כולנו כאחד<sup data-n=\"5089\">491</sup> דוקא [כו'] כנ\"ל). וזה שאמרו השבטים כך אין בלבינו שהוא [כמו] י\"ב אבני החשן שבלב כה\"ג אלא אח\"פ כו' דאנת הוא [חד]<sup data-n=\"5090\">492</sup> כו' כמו ביחו\"ע דו\"ק דז\"א דאצי' (ויותר נראה עלי'<sup data-n=\"5091\">493</sup> מטעם הנ\"ל בשרש השבטי' למעלה מהאבות). וזהו שהיו כל הי\"ב אבנים שבחשן כלולים זע\"ז במה שהיו דבוקים וסמוכי' זה אצל זה בלתי מופרדי' בריחוק מקום (והיו [ה]אבנים מסודרים כסדרן זה אצל זה בד' טורים כסדר י\"ב צירופי' [ד]הוי' כמו שהשבטים הם סדורים בסדר ד' דגלים) כי הרי כולם היו חקוקים בחשן במקום אחד עכ\"פ, והוא מטעם הנ\"ל שבלב דוקא מתכללי' זע\"ז (כיחוד לב הימיני עם לב השמאלי שנעשה כמו לב אחד). אבל הנה בשתי כתפות האפוד הרי [הי'] ששה משמותם על אבן האח[ת] בכתף זה וששה הנותרי' באבן הב' [בכתף הב'] שהיו מרוחקי' ומובדלים ששה [ש]בכתף הימין [מ]ששה בכתף השמאל אלה בימין ואלה בשמאל דוקא (שזהו בחי' התחלקות דחו\"ג דוקא היפך בחי' התכללו' דחו\"ג שבאבני החשן כנ\"ל). ואע\"פ שששה משמותם שעל האבן האחד היו כלולים באבן אחד ולא הי' אבן מיוחד לכל שם בפ\"ע, הרי אין זאת ההתכללו' רק באופן ומדריגה הא' בימין דחסד לבד וכן בשמאל דגבורה ששה כאחד, ואדרבה זהו מורה דוקא בחי' ההתחלקו' דחו\"ג מאחר שכ\"א כלול ו' מדות שבו לבד בכללות <span data-k=\"pg\">1046</span> ּ כולם יחד בימין לבד ו[כן] בשמאל לבד כו'. אך הנה הטעם הוא בדרך כלל לפי שב' כתפות האפוד הרי הוא בבחי' האור דמשפיע במוחין דאבא כמו שהוא למעלה טרם בואו למקבל שהוא הלב שעדיין אין",[["5086","488","<b>אנת הוא דמייחד לון</b>: ת\"ז בהקדמה (יז, א)."],["5087","489","<b>מבלי שימצא ראש וסוף</b>: ע\"פ קהלת ג, יא."],["5088","490","<b>ויחן ישראל </b>[ב ניתוסף: כו'. יא ניתוסף: כולם]: יתרו יט, ב וברש\"י שם [ושם: ויחן שם ישראל — ראה הנסמן לעיל פ' שמות יד, א]."],["5089","491","<b>ברכינו אבינו כולנו כאחד</b>: סיום תפלת העמידה."],["5090","492","<b>דאנת הוא [חד]</b>: ת\"ז בהקדמה (יז, א)."],["5091","493","<b>נראה עלי'</b>: ביא: עליון מזה."]]],[2300550652,"המדות שם בבחי' התכללו' די\"ב ג\"א הנ\"ל אלא רק מחולקים לחו\"ג ימין ושמאל בכללות דוקא, וע\"כ הי' הששה משמותם כלולים באבן אחד בימין והששה [ה]אחרים באבן הב' בשמאל לפי שב' הכתפות הן ב' דרועין דרועא ימינא ודרועא שמאלא, ש[ה]התחלקות [בהם] הוא בדרך כלל[ות] לבד, חסד דרועא ימינא כולל [בו] ו' מדות דחסד מחסד שבחסד עד יסוד שבחסד וגבורה דרועא שמאלא כולל ו' מדות דגבורה והן מופרדים ומחולקים זה מזה שאין לו<sup data-n=\"5092\">494</sup> חיבור והתכללות עם ו' מדות האחרים. וגם בו' מדות שבכתף [ה]א' [הי'] כולם חקוקי' באבן שוהם א' ואין אבן מיוחד לכל שם בפ\"ע מטעם זה עצמו כנ\"ל, לפי שאין בו ו'<sup data-n=\"5093\">495</sup> מדות דימין ושמאל באים כא'<sup data-n=\"5094\">496</sup> בהתחלקות ניכרת בפ\"ע שאין כל א'<sup data-n=\"5095\">497</sup> אור מיוחד בכלי ולבוש בפ\"ע, אלא כולם באבן א' שהוא נעשה כלי א' לו' המדות יחד בין בימין ובין בשמאל מאחר שהתחלקות בא בדרך כללות דוקא כנ\"ל וד\"ל. משא\"כ בי\"ב אבני החושן גם<sup data-n=\"5096\">498</sup> שבא בהתחלקות בדרך פרט כי יש לכל שם אבן מיוחד לפי שהו\"ק שבחו\"ג מיוחד כל אור בכלי שלו דוקא כנ\"ל, אמנם היא הנותנת דוקא שבאים לבחי' התכללות זה עם זה שהרי סמוכים ודבוקים זה עם זה בלתי פירוד כלל וכ\"א כלול מזולתו ומתאחדים יחד בלב כנ\"ל (והרי יובן מזה דההתחלקות דו\"ק זו שבלב עושה ההתכללות והתכללות דו\"ק בכתפים עושה התחלקות דימין ושמאל כו').\n(טו ) <b>ולהבין</b> שרש הדברים הנה ידוע ששרש המדות הוא באו\"א שהן חו\"ב המולידים אותם ואמנם עדיין המדות הם כלולים שם בהעלם לבד ואין בהם התחלקות כלל, כמו המשכיל שכל וסברא א' אע\"פ שיכולים לדון ממנו איזו טעם לאיסור או להיתר לחיוב או לזכות עדיין זה הוא בהעלם שלא נודע עדיין אם יחייב מן השכל הזה איזה דבר מה כי אינו רק שכל וסברא שכלי' לבד. אך ע\"י בחי' הדעת [הוא שמוצא למדות דחו\"ג מן ההעלם דחו\"ב לידי גילוי לב' אופנים אם לחסד או לדין, והוא הנק' דעת נוטה<sup data-n=\"5097\">500</sup> שמטה את השכל והסברא שידון ממנה כלפי חסד ויש שכל וסברא שיטה<sup data-n=\"5098\">499</sup> ] כלפי דין, והכל ע\"פ כח מוח הדעת שכולל חו\"ג שבהעלם [ב]חו\"ב ומביא לידי גילוי להסתעף ולהתחלק מן השכל ב' מדות בלבד חסד או דין (וכמ\"ש במ\"א בענין ד\"פ דתפילין קדש והי' חו\"ב שמע והי' חו\"ג שמתחלקים ע\"פ הדעת<sup data-n=\"5099\">501</sup> כו') כב\"ש אוסרים וב\"ה מתירים<sup data-n=\"5100\">502</sup> שזה דעת[ו] נוטה לאיסור וזה",[["5092","494","<b>לו</b>: שם: לששה אלה."],["5093","495","<b>בו ו'</b>: ב: בוי\"ו. יא: הו'."],["5094","496","<b>כא'</b>: יא: כל א'."],["5095","497","<b>א'</b>: ביא: ליתא."],["5096","498","<b>גם</b>: שם: ליתא."],["5097","500","<b>דעת נוטה</b>: ראה גם לעיל פ' שמות מב, א. וש\"נ."],["5098","499","<b>הוא. . שיטה</b>: תוקן ע\"פ ביא. ובתו\"ח כאן: שמצווה שכל מסברא שמטה."],["5099","501","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670147\" data-slug=\"torat-chaim\" data-id=\"2300670147\">בענין ד</a>\"פ. . חו\"ג שמתחלקים ע\"פ הדעת</b>: ראה סידור שער התפילין ז, א ואילך. אמ\"ב שם קיב, א ואילך. תו\"ח וירא קי, ג ואילך."],["5100","502","<b>כב\"ש אוסרים וב\"ה מתירים</b>: פסחים נה, א (במשנה)."]]],[2300550658,"דעת[ו] נוטה להתיר. אבל פרטי התחלקות [שב]חסד [ו]גבו' אינו בא בגילוי עדיין רק לחסד סתם ודין סתם, וגם שיש בחסד דין ונק' גבורה שבחסד עם<sup data-n=\"5101\">503</sup> נה\"י<sup data-n=\"5102\">504</sup> שבחסד וכן בדין יש חסד שבגבו' עד נה\"י דגבו' זהו הכל בכללות שנכללים כולם בב' מדות אלה. וזהו בחי' הדעת שבין ב' כתפות<sup data-n=\"5103\">505</sup> ימין ושמאל שממנו מתחלק ב' מדות דחו\"ג לב' דרועין ימין ושמאל בלבד לפי שדעת זה נמשך בבחי' החיצוני' שבמוח הדעת שלצד העורף<sup data-n=\"5104\">506</sup>, וע\"כ נמשך לב' <span data-k=\"pg\">תקכג</span> ּ כתפות שהם ג\"כ חיצוני' המדות [ד]יד ימין ושמאל לבד שהכתף הוא בחי' אחוריי' כידוע. אבל בחי' פנימי' דמוח הדעת שבראש הוא אשר מתחלק במוח לל\"ב חדרי'<sup data-n=\"5105\">507</sup> כמ\"ש ובדעת חדרים ימלאון<sup data-n=\"5106\">508</sup>, והם ל\"ב נ\"ח<sup data-n=\"5107\">509</sup> שמתפשט בבינה דוקא והוא הטעם והסברא [שבא] בהשגה והבנה במוח בינה וע\"י הדעת הוא שנתחלק לל\"ב חדרים ונק' ל\"ב שבילים דמתפתחי' במוח<sup data-n=\"5108\">510</sup> כו', ומשם נמשך אל הלב שמפני זה נק' לב כי הלב [הוא] בחי' נוק' מקבל מל\"ב נ\"ח שבבינה ונתחלקו ע\"י הדעת כנ\"ל וזהו דבינה ליבא, וע\"כ נק' לב שמקבל מל\"ב חדרים שבמוח שהן ל\"ב נ\"ח כו'. וכ\"ז בבחי' הפנימי' שבדעת שנמשך ללב בבחי' התחלקות בפרטי הו' מדות [וב]בחי' [ה]התכללו' די\"ב ג\"א כנ\"ל רק שבלב הוא עיקר הגילוי התחלקות בכל פרט כל אור בכלי שלו וגם התכללות דמדות בי\"ב גבולי אלכסון, אבל [ב]ל\"ב חדרים שבמוח עדיין ההתחלקות וגם ההתכללו' הוא בהעלם דמח' בלבד כנראה בחוש בכל משפט ענין<sup data-n=\"5109\">511</sup> השכל בדעת נוטה לכמה הפכים יחד כו' וד\"ל. אך א\"כ יש להבין למה אמר ולא יזח החשן מעל האפוד דאפוד דכר וחושן נוק' כנ\"ל אחר שעיקר קבלת הלב הוא מן המוח דחו\"ב בדעת שמתחלק לל\"ב חדרים ומשם נמשך ללב ממש כנ\"ל, הענין הוא דבאמת הגם שבחי' הדעת דבין כתפות הנ\"ל אינו רק חיצוני' שבמוח הדעת כנ\"ל, מ\"מ יש לו שרש בפנימי' [מוח] אבא עצמו כמו שהוא בבחי' אין ממש טרם שמתפשט' החכ' בבינה, והוא במדות דחכ' עצמ[ה] כמו שהוא קודם שיבא מאי\"ן דחכ' לי\"ש דבינה בהשגה וטעם לדבר כב\"ש אוסרי' וב\"ה מתירי', אע\"פ שאין יודעים טעם לדבר כלל שזהו רק מצד עצם החכ' שבלי<sup data-n=\"5110\">512</sup> שמטה כלפי חסד א\"א [לו] לומר לאיסור ולחיוב. וראי' ממה שמצינו בגמ' שהקשה לרב וכי מה בין זה [לעגל] כו' אשתיק רב כו' ומ\"מ לא חזר בו<sup data-n=\"5111\">513</sup> אע\"פ שסתרו טעמו כי מצד עצם כח נשמתו א\"א [לו] לומר בהיפך כו' וזהו שנק' ו\"ק דאבא<sup data-n=\"5112\">514</sup> עצמו שא\"א לבא בהשגה<sup data-n=\"5113\">515</sup> [ו]טעם דבינה כמ\"ש במ\"א.",[["5101","503","<b>עם</b>: ב: עד. יא: או."],["5102","504","<b>נה\"י</b>: יא: נו\"ה."],["5103","505","<b>הדעת שבין ב' כתפות </b>[ביא: כתפי']: ראה ע\"ח (שער דרושי הצלם) שכ\"ה דרוש ב' כלל יז. מבוא שערים ש\"ג ח\"ב פ\"א [וכן צ\"ל ב]תו\"ח וירא קי, ג הערה 38."],["5104","506","<b>שבמוח הדעת שלצד העורף</b>: ראה גם לעיל פ' שמות כג ד ובהערה 9."],["5105","507","<b>דמוח הדעת. . מתחלק במוח לל\"ב חדרי'</b>: ראה גם לעיל שכב, ד. פ' בא קח, א הערה 463. לקמן שסא, ב."],["5106","508","<b>ובדעת חדרים ימלאון</b>: משלי כד, ד [ושם: ימלאו וכן הוא בב — ראה הנסמן לעיל מב, א]."],["5107","509","<b>ל\"ב נ\"ח</b>: ראה ס\"י פ\"א, מ\"א. מאמרי אדה\"א בראשית ע' ג. וש\"נ."],["5108","510","<b>ל\"ב שבילים דמתפתחי' במוח</b>: ראה זהר (אד\"ר) נשא קכח, ב. קכט, א. קלו, א. ראה גם לקמן שסא, ב."],["5109","511","<b>ענין</b>: ביא: עין."],["5110","512","<b>החכ' שבלי</b>: ביא: כח שכלי."],["5111","513","<b>וכי מה בין זה. . לא חזר בו</b>: ביצה ו, א. ראה מאמרי אדה\"א בראשית ס\"ע צד ואילך. וש\"נ. לעיל פ' בא קכט, ב. וש\"נ."],["5112","514","<b>ו\"ק דאבא</b>: ראה גם לעיל פ' שמות יא, א. וש\"נ."],["5113","515","<b>ו\"ק דאבא עצמו שא\"א לבוא בהשגה</b>: ראה גם לעיל פ' בא קכט, ב."]]],[2300550664,"(טז) <b>וזהו</b> ג\"כ שרש ענין דב' אבני השוהם שבב' כתפות שבחי' הדעת [ה]חיצוני שבהם שרשו מחו\"ג דאבא עצמו ע\"כ מפני זה [נק'] אבני זכרו\"ן שבחי' אור אבא עצמו (שנק' קדש מלה בגרמי' כמו השמן שצף ע\"ג היין כו' ואי[נו] בא מן ההעלם לגילוי בהשגה לעולם) שם הוא בחי' הזכרון, כי השכחה הוא באחוריים דאבא שהוא נה\"י דאבא שמלובש באימא כו' ונק' אדם א' ד\"ם. וזה שאמר כי לא אד\"ם הוא להנח\"ם מחסד לדין כו', וע\"כ הם רק ב' אבני' לימין ושמאל לבד ואין בהם חיבור והתכללות כי הרי במדות דחכ' עצמ[ה] עדיין לא בא להתחלקות פרטי' להיות ו' אבנים פרטיות (משא\"כ במוח בינה שהמדות הם שם בהתחלקות פרטי' כמו טעם לאיסור וטעם להיתר [ו]יכולים להתכלל יחד בכמה אופנים שונים ע\"י הדעת כנ\"ל), לפי שבחכ' שנק' אב<sup data-n=\"5114\">516</sup> שם הוא רק מקור עצם המדות ושרשם הכללי הכוללם יחד וע\"כ לא נמשכו משם רק לב' מדות דחו\"ג וכל הפרטי' כלולי' בכ\"א מהם. וזהו ששה <span data-k=\"pg\">1048</span> ּ משמותם על האבן האח[ת] ששה מדות דאבא עצמו כלולים באבן אחד דחסד וכן לשמאל מטעם הנ\"ל, ולפי שהוא למעלה מבינה שבלב<sup data-n=\"5115\">517</sup> ע\"כ נמשך דוקא בחיצוני' הדעת שבין כתפי' אבל חיצוני' זה למעלה מן הפנימי' שבמוח בינה כנ\"ל (וכידוע הכלל שכל הגבוה גבוה יותר<sup data-n=\"5116\">518</sup> לא יוכל לבא להוריד<sup data-n=\"5117\">519</sup> למטה כ\"א בחיצוני' דוקא כמו משלי שלמה<sup data-n=\"5118\">520</sup> כידוע, וכאור הבהיר ביותר שבהירתו הוא ניכר<sup data-n=\"5119\">521</sup> יותר בחשך וכאבן טוב החקוק בדבר גשמי כו'. וראי' לכ\"ז ממ\"ת ביוה\"ד שירד' התורה בלבוש דחיצוני' דק\"נ [כ]לא תרצח<sup data-n=\"5120\">522</sup> כו' ונק' משל הקדמוני, וגם שנק' נובלות חש\"מ<sup data-n=\"5121\">523</sup> חיצוני' זו יותר גבוה מפנימי' שבחכ' עילאה דתורה שהם טעמי המצות שיתגלו בימוהמ\"ש<sup data-n=\"5122\">524</sup> שהרי [ה]עוה\"ב הוא בא מן המצות<sup data-n=\"5123\">525</sup> בפו\"מ דוקא שהוא בחי' עד\"ן סתימאה<sup data-n=\"5124\">526</sup> [כו'] שלמעלה הרבה מתענוג של ח\"ע דטעמי מצות שבבחי' אלף<sup data-n=\"5125\">527</sup> כו' (וזהו משני עבריהם הם כתובים<sup data-n=\"5126\">528</sup> דגם בחי' אחוריי' [כ]פנימי' יחשב [ו]יותר עליון מן הפנימי' [ו]כך אמר אחרי הוי' תלכו<sup data-n=\"5127\">529</sup> בתו\"מ בגשמיות דוקא וכן אמר בכלב יען כי מלא אחרי<sup data-n=\"5128\">530</sup> כו'. וזהו שא' עבודת הקדש עליהם<sup data-n=\"5129\">531</sup> בכת\"ף ישאו בכת\"ף דוקא מטעם הנ\"ל בכתפות האפוד ששרשו בבחי' פנימי' דאור אבא עצמו שלמעלה מבינה, וזהו ואני נתתי [לך] שכם אחד<sup data-n=\"5130\">532</sup> על אחיך כו' כמ\"ש במ\"א, וכן מ\"ש לע\"ל ולעבדו שכם",[["5114","516","<b>שבחכ' שנק' אב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> פ\"ג. לעיל פ' בא קא, ד. וש\"נ."],["5115","517","<b>שבלב</b>: ביא: שבראש."],["5116","518","<b>שכל הגבוה גבוה יותר</b>: ראה לעיל פ' שמות כא, ב הערה 863."],["5117","519","<b>להוריד</b>: ביא: ולירד."],["5118","520","<b>משלי שלמה</b>: ראה גם לעיל פ' בא צה, א. וש\"נ."],["5119","521","<b>שבהירתו הוא ניכר</b>: שם: שהבהקתו נכרת."],["5120","522","<b>[כ]לא תרצח</b>: יתרו כ, יג."],["5121","523","<b>נובלות חש\"מ</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["5122","524","<b>טעמי המצות שיתגלו בימוהמ\"ש</b>: ראה רש\"י שה\"ש א, ב. (אותיות דר\"ע אות ז — אוצר המדרשים ח\"ב ע' 414). הנסמן במאמרי אדה\"א דברים ח\"ב ע' תקצ. שער האמונה ג, ב הערה 10."],["5123","525","<b>[ה]עוה\"ב הוא בא מן המצות</b>: ראה גם מאמרי אדה\"א בראשית ע' שצב. וש\"נ. לעיל פ' שמות ז, א. וש\"נ."],["5124","526","<b>עד\"ן סתימאה</b>: ראה גם לעיל ה, ג. וש\"נ."],["5125","527","<b>אלף</b>: ביא: או\"פ."],["5126","528","<b>משני עבריהם הם כתובים</b>: ראה תשא לב, טו. וראה גם לעיל פ' בשלח ריב, א. וש\"נ."],["5127","529","<b>אחרי הוי' תלכו</b>: פ' ראה יג, ה [ושם: ה\"א]."],["5128","530","<b>יען כי מלא אחרי</b>: דברים א, לו [ושם: אשר מלא — ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשפז. וש\"נ. שמות ח\"ב ע' תעא. וש\"נ. וראה גם שע\"ת כה, א ובהערה 4]."],["5129","531","<b>עבודת הקדש עליהם</b>: נשא ז, ט."],["5130","532","<b>ואני נתתי [לך] שכם אחד</b>: ויחי מח, כב. ראה מאמרי אדה\"א בראשית ד\"ה זה ע' תפח ואילך וע' תצא ואילך [ובהנסמן בריש המאמר שם]."]]],[2300550670,"א'<sup data-n=\"5131\">533</sup> וכה\"ג וד\"ל). וז\"ש ולא יזח החושן מעל האפוד דהגם שהחשן הי' בו י\"ב אבני שוהם<sup data-n=\"5132\">534</sup> באים בהתחלקות ובהתכללו' מצד שמקבל ע\"י לב במוח<sup data-n=\"5133\">535</sup> בינה ששם מתפשטי' ל\"ב נ\"ח ומתחלקי' לל\"ב חדרים ע\"י הדעת, אך באמת עיקר [מקור] המשפיע הראשון הוא בחי' אור אבא עצמו כמו שהוא טרם התפשטות[ו] בל\"ב נ\"ח [ב]בינה כנ\"ל, וע\"כ [ה]זה[י]ר שלא יזח החשן שבלב מן כתפות האפוד שהן ב' אבני שוהם ששרשם מחו\"ג דחו\"ב עצמו<sup data-n=\"5134\">536</sup> שנמשך [ב]בחי' הדעת שבין כתפין דוקא מטעם הנ\"ל וד\"ל<sup data-n=\"5135\">537</sup>, והוא שנק' מוח הזכרון דאור אבא עצמו (ששרשו בפנימי' ועצמי' הכתר שלמעלה מח\"ס שבא לגילוי כנ\"ל).\n(יז) <b>וזהו</b> שאמר ונשא אהרן את שמות בנ\"י בחשן המשפט על לבו לזכרון לפני ה' תמיד דהיינו שע\"י דביקות החשן באפוד אז בחי' ב' מדות דחו\"ג דאבא עצמו שבב' אבני השוהם שבכתפות האפוד הן המעלים לי\"ב אבני החושן שעל לבו דוקא שכבר הן בהתכללות כנ\"ל שיעלו ויבאו לבחי' אור אבא עצמו שלמעלה מבינה שנק' זכרו\"ן לפני ה' תמיד בלי שכחה לעולם כמאמר אין שכחה לפניו<sup data-n=\"5136\">538</sup> כו' וד\"ל (וזהו ששה\"ם אותיות מש\"ה שזהו בחי' פנימי' דאור אבא עצמו<sup data-n=\"5137\">540</sup> כידוע בענין מש\"ה מ\"ה שמ\"ו כו' (שזהו בחי'<sup data-n=\"5138\">541</sup> דע\"י<sup data-n=\"5139\">539</sup> כמ\"ש בע\"ח בכמה דוכתי) והוא [בחי'] או\"י שמאיר ומבהיק בעצם תולדתו כנ\"ל וזהו בחי' חסדי' עצמיי' דפנימי' אבא והוא בחי' יוסף צ\"ע כמ\"ש בגמ' בענין כדכד ח\"א שה\"ם כו' (וכמשי\"ת ועיין בלקו\"ת) והוא שרש אותיות כמו שהן בתורה הקדומה שבעצמות <span data-k=\"pg\">תקכד</span> ּ א\"ס ממש כידוע).\n<b>אך</b> הנה באמת עדיין אין כ\"ז מתיישב לכאו' דהלא לפי כל הנ\"ל עיקר קבלת הלב בהתכללות דו' מדות הוא בא דוקא מל\"ב נ\"ח שבבינה ודעת כנ\"ל, וא\"כ הי' צריך שהחשן יהי' לו דיבוק לבחי' המוחין הפנימי' שבראש ולא לכתפות האפוד שהם באחוריים, ואם האפוד הוא בחי' דכר משפיע לחשן הרי הי' צריך שיהי' החשן ג\"כ בבחי' הב' מדות דחו\"ג דכתפות האפוד שהן בלי התכללות כו' (וגם הנה מבואר למעלה בענין יום חתונתו במ\"ת פנים בפנים ושמחת לבו בבהמ\"ק בקרבנות שיש מעלה יתירה בקרבנות בשמחת לבו",[["5131","533","<b>ולעבדו </b>[ביא: לעבדו]<b> שכם א'</b>: צפני' ג, ט [ושם לעבדו — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231103\" data-slug=\"likkutei-sichot\" data-id=\"1300231103\">לקו\"ש שלח כרך כג ע' 103</a> בהערות. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680202\" data-slug=\"torat-chaim\" data-id=\"2300680202\">תו\"ח וישלח קצ, ד</a>]."],["5132","534","<b>אבני שוהם</b>: ביא: אבנים שהם(ן)."],["5133","535","<b>ע\"י לב במוח</b>: שם: הלב ממוח."],["5134","536","<b>דחו\"ב עצמו</b>: שם: דחכ' עצמה."],["5135","537","<b>וד\"ל</b>: שם: ליתא."],["5136","538","<b>לפניו</b>: שם: לפני."],["5137","540","<b>עצמו</b>: ביא: ליתא."],["5138","541","<b>בחי'</b>: ב ניתוסף: פנימי'. יא: פנימי'."],["5139","539","<b>פנימי' דאור אבא. . פנימי' דע\"י</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"ב ע' תתסה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380918\" data-slug=\"likkutei-torah\" data-id=\"4001380918\">לקו\"ת נצבים מט, ד</a>. לעיל פ' שמות כג, א. וש\"נ."]]],[2300550675,"יותר מהארת פנים שבמוחי' שבראש במ\"ת כו' שזהו ענין התפלה עצמו<sup data-n=\"5140\">542</sup> שלמעלה מאור דתורה עד שעושה וממשיך לאור דתורה מתפילת ישראל כנ\"ל, ולפי הנ\"ל עיקר התכללות דמדות שבלב אינו רק ממוחין דחו\"ב שבראש ע\"י הדעת שמתפשט בל\"ב חדרים כו' וזהו היפך ענין הנ\"ל). אך הנה בדוגמא זאת אנו מוצאים בענין מ\"ת שאע\"פ שהתורה היא בבחי' התכללות המדות דוקא שהוא בחי' אד\"ם וכמ\"ש וזא\"ת תור\"ת האד\"ם<sup data-n=\"5141\">543</sup> דוקא, וכמו שאנו רואים במ\"ט פנים טמא וטהור<sup data-n=\"5142\">544</sup> [ו]כן באו\"ה כשר ופסול חייב זכאי שכלולים זה עם זה כמו שיש בדין חסד וחסד בדין כו'. ובכללות המצות שבתורה הרי הן בציור אברי האדם שכלולי' זע\"ז כנ\"ל וכמ\"ש בזהר דאוריי' אית בה פרקין ושייפין<sup data-n=\"5143\">545</sup> כו', [ו]עכ\"ז הרי כלולים<sup data-n=\"5144\">546</sup> כל התורה ומצות כלולים רק בבחי' חו\"ג דרמ\"ח מ\"ע שהן בחי' ה' חסדים כללים ושס\"ה ל\"ת בחי' ה\"ג<sup data-n=\"5145\">547</sup> והיינו אנכי ולא יהי' כו' שמפי הגבורה<sup data-n=\"5146\">548</sup> עצמו שמענו, כידוע שזהו בחי' התחלקות לימין ושמאל דוקא וכמ\"ש מימינו אש דת<sup data-n=\"5147\">549</sup> כו' מימין דחסד ברמ\"ח מ\"ע ושמאל<sup data-n=\"5148\">550</sup> דגבורה בשס\"ה ל\"ת, דחו\"ג זה בלי חיבור והתכללות כלל שא\"א להיות חילוף ושינוי מטוב לרע ומרע לטוב כמ\"ש סו\"מ וע\"ט<sup data-n=\"5149\">551</sup> [ו]כמו חיים וטוב מות ורע שנק' ברכה וקללה שהן ב' הפכים בתכלית. וזהו בחי' חו\"ג דרצון שבפנימי' אור הכתר עצמו שלמעלה מהתחלקות טעם לרצון, שזהו כמו ענין ב' כתפות האפוד שימין ושמאל מפורדים זמ\"ז בלי חיבור כלל כנ\"ל (וכך הי' הברכה על הר גריזים<sup data-n=\"5150\">552</sup> והקללה על הר עיבל, שנחלקו הי\"ב שבטים לב' חלקים שוים מפורדים דוקא ו' שבטים על הברכה כו' כענין ו' משמותם על [ה]אבן [ה]אח[ת] כו', היפך ההתכללות דד' דגלים שהם בד' מילואי הטורים שבחשן שהוא התכללות דלב אדם בהתכללות מדות שבתורה כנ\"ל). ואע\"פ שנא' על התורה להבדיל בין טמא לטהור כו' זהו מצד שרש החכ' שבתורה בחו\"ג שברצון שמשם בא [ה]הבדלה בין טו\"ר עד שגם בבחי' ההתכללות דמדות יש הבדלה דוקא, וכמו שאנו רואים שדוקא אחרי ההתכללו' דחו\"ג בכל פרטי המדות שבתורה במ\"ע ול\"ת יצא אח\"כ תכלית ההבדלה והבירור שזה כשר וזה פסול זה טמא וזה טהור וכן חייב וזכאי כנ\"ל משום דבחכ' דוקא אתברירו<sup data-n=\"5151\">553</sup> כו', לפי ששלימות הבירור בפרטי פרטיות הוא אחר בחי' התכללו' דמדות שע\"פ החכ' אזי יצא לאור כל א' על מקומו להבדיל [בין] כו' <span data-k=\"pg\">1050</span> ּ כנ\"ל<sup data-n=\"5152\">554</sup> וד\"ל.",[["5140","542","<b>עצמו</b>: שם: עכשיו."],["5141","543","<b>וזא\"ת תור\"ת האד\"ם</b>: שמו\"ב ז, יט. ראה זהר (רע\"מ) משפטים קיז, ב. צו כט, ב."],["5142","544","<b>במ\"ט פנים טמא וטהור</b>: ראה ירושלמי סנהדרין פ\"ד, ה\"ב. הנסמן לעיל פ' שמות י, ג."],["5143","545","<b>דאוריי' אית בה פרקין ושייפין</b>: ראה זהר תולדות קלד, ב. משפטים שם."],["5144","546","<b>כלולים</b>: ביא: כללות."],["5145","547","<b>דרמ\"ח. . ה' חסדים. . ושס\"ה. . ה\"ג</b>: ראה קו\"א לתניא [ד\"ה להבין מ\"ש בפע\"ח קנח, ב]. הנסמן לעיל פ' בא צו, א."],["5146","548","<b>אנכי ולא יהי' כו' </b>[ביא: לך]<b> שמפי הגבורה</b>: מכות כד, א. ראה מו\"נ ח\"ב פל\"ג. <a class=\"ft-cite\" href=\"#/read/tanya/3401310025\" data-slug=\"tanya\" data-id=\"3401310025\">תניא</a> פ\"כ. לעיל פ' וארא סט, א. וש\"נ."],["5147","549","<b>מימינו אש דת</b>: ברכה לג, ב."],["5148","550","<b>ושמאל</b>: ביא: וא\"ש."],["5149","551","<b>סו\"מ וע\"ט</b>: תהלים לד, טו."],["5150","552","<b>הברכה על הר גריזים</b>: תבוא כז, יב ואילך."],["5151","553","<b>דבחכ'. . אתברירו</b>: ראה זהר (היכלות) פקודי רנד, סע\"ב. מאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא."],["5152","554","<b>כנ\"ל</b>: ביא: ליתא."]]],[2300550680,"<b>ונמצא</b> דמה שהי' בחי' ההבדלה בכלל ברצון העליון שלמעלה מן הטעם [ב]אנכי ולא יהי' לך [הוא] שב[א ל]שלימות הבירור והבדלה ע\"י החכ' דוקא [ו]בדרך פרטי פרטיות ברמ\"ח מ\"ע ושס\"ה ל\"ת, שהוא תושבע\"פ דוקא מל' קרינן לה<sup data-n=\"5153\">555</sup> ששם הוא תכלית שלימות הבירור כמו בכל דקדוקי סופרים<sup data-n=\"5154\">556</sup> בכל הלכות התורה בכל פרקין ושייפין שבה כמו כל אברי [ה]אדם שאע\"פ שכלולים זע\"ז [י]באו לבחי' ההתחלקות כל אבר על מקומו ולא ישנה תפקידו כו', והוא ע\"י הגידים דקים שמתפשטים מן המוח אל הלב דוקא ומן הלב הולך וסובב [כל האיברי'] להשפיע לכאו\"א לפי טבעו דוקא וד\"ל (ואע\"פ שבלב שם הוא עיקר בחי' התכללות דרוח ונפש בב' חללים שבו כנ\"ל אדרבה היא הנותנת שיוכל אח\"כ דם הוא הנפש שבחלל השמאלי להשפיע לכל אבר פנימי' וחיצוני' לכאו\"א כפי טבעו דוקא כנ\"ל ).\n<b>והנה</b> ע\"ד כ\"ז יובן ג\"כ בענין ב' אבני שה\"ם בב' כתפות האפוד לימין ושמאל להיות ששתי<sup data-n=\"5155\">557</sup> התחלקות זאת דימין ושמאל שבב' כתפות דוקא בא מבחי' דע\"ת עליון שבכת\"ר שלמעלה הרבה מחו\"ב שבראש והוא בבחי' כת\"ר שבכת\"ר שנק' גולגלתא<sup data-n=\"5156\">558</sup> כו' [להיות שיש בכח ד\"ע זה] להטות הרצון לחו\"ג א\"כ [שרשו למעלה מן הרצון (כמו שד\"ת מטה לשכל לחו\"ג ששרשו למעלה מן השכל כו') וזהו גדולה] דיעה שניתנה בין ב' אותיות י\"ה<sup data-n=\"5157\">559</sup> כו' ומשם נמשך למטה בחיצוני' הדעת שבין כתפות דוקא לחלק לחו\"ג בחיצוני' (והוא כמו שנמשך מחו\"ג שבכת\"ר שהוא עצם הרצון העליון לבא בהתחלקות ימין ושמאל באנכי ולא יהי' לך במ\"ע ול\"ת בחיצוני' דוקא שהוא למעלה מן הפנימי' דחו\"ב שבכת\"ר כו' כנ\"ל (כי שרש הכתפין למעלה ממוחין שבראש שהרי בנשיאות כפים א' וישא אהרן את ידיו<sup data-n=\"5158\">560</sup> כו' ומה שיכול להגביה ידיו למעלה מראשו זהו מן הכתפין, וז\"ש דרישא דמלכא בחו\"ג אתקין<sup data-n=\"5159\">561</sup> כמ\"ש במ\"א). וע\"כ הי' ששה משמותם על אבן הא' לפי שזהו שרש ומקור הראשון דמדות דחו\"ג כמו שיוצאין מעצמות אור הכת\"ר שלמעלה מחו\"ב דכת\"ר, ואמנם בהגיע אור זה בחכ' שזהו בחי' דעת דאבא שנק' מפתחא דכליל שי\"ת<sup data-n=\"5160\">562</sup> כו' שכלולים בו ו' מדות יחד והוא מוח הזכרון דאבא עצמו הנ\"ל, אבל אח\"כ ממילא נמשך מחכ' לבינה מאין ליש בהתחלקות דל\"ב נ\"ח ומשם ללב ע\"פ התחלקות דל\"ב חדרים כו', והוא מ\"ש ויקם עדות ביעקב<sup data-n=\"5161\">563</sup> שהוא התכללו'",[["5153","555","<b>תושבע\"פ. . מל' קרינן לה</b>: ת\"ז בהקדמה (יז, א)."],["5154","556","<b>דקדוקי סופרים</b>: סוכה כח, א."],["5155","557","<b>ששתי</b>: ביא: ששרש."],["5156","558","<b>כת\"ר שבכת\"ר שנק' גולגלתא</b>: ראה ע\"ח (שער א\"א) שי\"ג, פ\"ג. לעיל פ' בשלח רב, א. וש\"נ."],["5157","559","<b>גדולה] דיעה. . י\"ה</b>: ראה ברכות לג, א. סנהדרין צב, א וברש\"י שם. מאמרי אדה\"ז תקס\"ט ר\"ע טז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670239\" data-slug=\"torat-chaim\" data-id=\"2300670239\">תו\"ח וירא קיב, א</a> ובהערה 6."],["5158","560","<b>וישא אהרן את ידיו</b>: שמיני ט, כב. ראה גם לעיל פ' וארא עב, ב. וש\"נ."],["5159","561","<b>דרישא דמלכא בחו\"ג אתקין </b>[ביא: אתתקן]: ראה זהר (אדרא דמשכנא) משפטים קכב, רע\"ב. לעיל פ' בשלח רמט, א [ושם: באדר\"ז]. שעה\"י קכז, א ובהערה 13."],["5160","562","<b>דעת דאבא שנק' מפתחא דכליל שי\"ת</b>: נסמן לעיל פ' משפטים רצא, ד."],["5161","563","<b>ויקם עדות ביעקב</b>: תהלים עח, ה."]]],[2300550685,"דמדות שבלב והוא התכללות דמדות שבתורה הנ\"ל שנק' תור\"ת האד\"ם כו'.\n(יח) <b>וזהו</b> ג\"כ ענין אבני החשן על לב כה\"ג שבאים בבחי' ההתכללו' כנ\"ל, ואמנם באמצעות ההתכללו' הזאת הוא שבא להתחלקו' כאו\"א במינו [ו]במקומו המיוחד לו בי\"ב אבנים הללו שהן כמו התחלקו' אבר\"י האד\"ם אחר ההתכללות, וכמו התחלקות הדינים והלכות בס'<sup data-n=\"5162\">564</sup> בדקדוקי סופרים בתושבע\"פ בשלימות הבירור והבדלה בין טמא וטהור בכל פרט ופרט משום דבחכ' דוקא אתברירו, והוא חכ' דתושבע\"פ בחי' מל' דבינה יתירה ניתנה באשה יותר מבאיש. וזהו ג\"כ יתרון מעלה באבני החשן יותר מאבני האפוד כו', ועכ\"ז א' ולא יזח החשן מעל האפוד להיות שרשם ומקורם הראשון כו' וד\"ל (וז\"ש<sup data-n=\"5163\">565</sup> ביום שמחת לבו בקרבנות דבהמ\"ק שזהו עכשיו התפלות <span data-k=\"pg\">תקכה</span> ּ שקושר כתרים לקונ\"ו כו' והן אבני החושן ג\"כ שהן מזכוכית<sup data-n=\"5164\">566</sup> ונעשה עטר\"ה גבוה יותר מעטרה שבמ\"ת כנ\"ל, הענין הוא לפי שיש שרש לתפלה וקרבן לעורר לרח\"ר העליונים שבעצמו' א\"ס שבעצמו' הרצון הטוב ממש שלמעלה עדיין מהתחלקות הרצון לימין ושמאל ע\"י הדעת<sup data-n=\"5165\">567</sup> שנמשך למטה בכתפות (ובדעת<sup data-n=\"5166\">568</sup> שבמוחין דחו\"ב כו'), וע\"כ עטרה שבשמחת לבו בקרבנות גבוה מכתר תורה שאינו אלא מבחי' חו\"ג שבכתר שנמשך לחו\"ב בהארת פנים דחכ' במדות שנק' אד\"ם כו', אבל בעצמות אוא\"ס נא' כי לא אד\"ם הוא כו').\n<b>ומעתה</b> י\"ל מ\"ש ואת שמות הששה הנותרים על האבן הב' מהו הנותרים (עיין באוה\"ח), להיות שהעיקר הוא בחי' הימין והשמאל נכלל בימין כי שרש התחלקות זו באה מעצמות הרצון שנק' רעדכ\"ר שבמצחא כו' שכולו טוב וחסד בעצם וכמאמר דלית שמאלא בהאי עתיקא<sup data-n=\"5167\">569</sup> כו' (כמ\"ש במ\"א ע\"פ פקח עיניך כו' בדרוש דארדה<sup data-n=\"5168\">571</sup> נא<sup data-n=\"5169\">570</sup> כו'), ע\"כ א' ששה הנותרים מן החסד העצמי שבימין על האבן הב' שגם הוא מבחי' אור החסד וטוב בעצם שהוא אבן השה\"ם דוקא, כידוע דשרש השה\"ם הוא בבחי' יוסף צ\"ע שהוא עצם הטוב",[["5162","564","<b>בס'</b>: איא: ליתא."],["5163","565","<b>וז\"ש</b>: שם: ומ\"ש."],["5164","566","<b>מזכוכית</b>: שם: מזוככים."],["5165","567","<b>הדעת</b>: איא: ד\"ע."],["5166","568","<b>ובדעת</b>: אביא: ובד\"ת."],["5167","569","<b>דלית שמאלא בהאי עתיקא</b>: ראה זהר (אד\"ר) נשא קכט, א. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתעא."],["5168","571","<b>דארדה נא</b>: וירא יח, כא. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670342\" data-slug=\"torat-chaim\" data-id=\"2300670342\">תו\"ח שם קיד, א</a> ואילך."],["5169","570","<b>פקח עיניך. . דארדה נא</b>: דניאל ט, יח. ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670496\" data-slug=\"torat-chaim\" data-id=\"2300670496\">תו\"ח וירא קיח, א</a>."]]],[2300550690,"והחסד שבעצם הרצון שאין בו נטי' לדין כלל, והוא טו\"ב דמש\"ה אותיות שה\"ם שהוא בחי' או\"י המאיר בעצם תולדתו כמ\"ש וירא את האור כי טוב<sup data-n=\"5170\">572</sup> [כי טוב] בעצם והוא מ\"ש [אמרו] צדיק כי טוב<sup data-n=\"5171\">573</sup> שטבע עצם הטוב רק להטיב<sup data-n=\"5172\">574</sup> כו', וכך הוא בבחי' הטוב דמשה [ש]נא' בו כי טו\"ב הוא בטי\"ת רבתי<sup data-n=\"5173\">575</sup> שהוא עה\"ח שלמעלה מעה\"ד כידוע. וזה שבמלואים הד' טורים בטור הד' ניתקן<sup data-n=\"5174\">576</sup> שה\"ם וישפ\"ה שהן ב' שמות יוסף ובנימין בחי' צ\"ע וצ\"ת או\"י ואו\"ח כידוע בפי' ועמך כולם צדיקים<sup data-n=\"5175\">577</sup> כו' שהן ב' נהורין דנשמה נהורא חיורא ונהורא אוכמא כו', וכתיב עדות ביהוסף<sup data-n=\"5176\">578</sup> כו' שניתוסף ה\"א ביוסף ויש ג' אותיות דש' הוי' לבד ה\"א אחרונה כו' כמו יהונתן<sup data-n=\"5177\">579</sup> שמורה זה על ענין תמידי' השפע מבחי' צ\"ע לצ\"ת שהוא בנימין שמשפיע בו בתמידות, וזהו שסמך אבן ישפה לאבן שהם דוקא משום דבחי' או\"ח דמקבל צ\"ל סמוך לבחי' או\"י דמשפיע כידוע וד\"ל. אבל בב' כתפות האפוד היו ב' האבנים משהם להיות שהמדות הכפולים בין בו' מדות שבימין בין בו' מדות שבשמאל הכל כלולים באבן השהם דוקא שהוא בחי' יסוד<sup data-n=\"5178\">580</sup> שנק' צדי\"ק כי טו\"ב בעצם כנ\"ל, וכמ\"ש אלה תולדות יעקב יוסף<sup data-n=\"5179\">581</sup> שכל גילוי המדות דיעקב הוא ע\"י<sup data-n=\"5180\">582</sup> יוסף שהוא יסוד<sup data-n=\"5181\">583</sup> כנישו דכל נהורין<sup data-n=\"5182\">584</sup> [כו'] וע\"כ הי' יוסף נגד כללות השבטים כמ\"ש תהיין לראש יוסף<sup data-n=\"5183\">585</sup> ולקדקוד [נזיר אחיו] כו'. וכן א' לו ואני<sup data-n=\"5184\">586</sup> הנה נתתי לך שכם<sup data-n=\"5185\">587</sup> א' על אחיך שהן ב' אבני שה\"ם שבכתפות כו' וע\"כ הי' כל הששה אבנים בימין ו[ב]שמאל כלולים באבן א' דשה\"ם שכוללם יחד גם בשמאל כמו בימין להיות שרש שניהם מעצם החסד[ים] והטוב לבד כו' וד\"ל (והוא ב\"ה<sup data-n=\"5186\">588</sup> אותיות בו' שמות דבימין ובה'<sup data-n=\"5187\">589</sup> אותיות בו' שמות דשמאל<sup data-n=\"5188\">590</sup> ע\"י הוספת יוס\"ף בה'<sup data-n=\"5189\">591</sup> יהוס\"ף או [ב]בנימי\"ן מלא ושניהם באבן הב' שבשמאל<sup data-n=\"5190\">592</sup> כמ\"ש בגמ'<sup data-n=\"5191\">593</sup> ר\"י או' יוסף<sup data-n=\"5192\">594</sup> יהוס\"ף ר\"נ א' בנימי\"ן מלא לפי שבשמאל דוקא צ\"ל התגברות החסדי' על הגבו[רות] דשמאל [ע\"י] יוסף צ\"ע ממקום<sup data-n=\"5193\">595</sup> החסדי' או בתוס' יו\"ד בבנימין [שיש] ב[ו] ימין דחסד צ\"ת כו') וד\"ל.",[["5170","572","<b>וירא את </b>[ביא: ליתא]<b> האור כי טוב</b>: בראשית א, ג [בדילוג]."],["5171","573","<b>[אמרו] צדיק כי טוב</b>: ישעי' ג, י."],["5172","574","<b>שטבע עצם הטוב רק להטיב</b>: ראה שער היחוד והאמונה פ\"ד. לעיל פ' שמות לד, ג. וש\"נ."],["5173","575","<b>כי טו\"ב הוא בטי\"ת רבתי</b>: שמות ב, ב ובמנחת שי שם. ראה גם לעיל פ' שמות מג, ד. וש\"נ."],["5174","576","<b>ניתקן</b>: ביא: נחקק."],["5175","577","<b>ועמך כולם צדיקים</b>: ישעי' ס, כא. לעיל פ' משפטים רצה, ג ובהערה 38."],["5176","578","<b>עדות ביהוס\"ף</b>: תהלים פא, ו. סוטה לו, ב."],["5177","579","<b>יהונתן</b>: ראה גם מאמרי אדה\"א במדבר ח\"א ע' קמז ואילך."],["5178","580","<b>באבן השהם. . יסוד</b>: ראה גם קהלת יעקב מערכת שהם ב. מאמרי אדה\"א דברים ח\"ב ע' תמג וע' תעב."],["5179","581","<b>אלה תולדות יעקב יוסף</b>: וישב לז, ב. ראה זהר וישב קפ, א. ביאוה\"ז ויחי כט, ד. ל, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680234\" data-slug=\"torat-chaim\" data-id=\"2300680234\">תו\"ח ויחי רמו, א</a>."],["5180","582","<b>ע\"י</b>: ביא: יסוד."],["5181","583","<b>יוסף שהוא יסוד</b>: ראה זהר (רע\"מ) פינחס רלו, א. פרדס (שעה\"כ) שכ\"ג, מערכת יוסף."],["5182","584","<b>יסוד כנישו דכל נהורין</b>: ראה זהר בראשית יח, א. לג, א. לעיל פ' בשלח ריט, ג. וש\"נ."],["5183","585","<b>תהיין לראש יוסף</b>: ויחי מט, כו."],["5184","586","<b>ואני</b>: ביא: ליתא."],["5185","587","<b>הנה נתתי לך שכם</b>: בהוספת תיבת הנה כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670351\" data-slug=\"torat-chaim\" data-id=\"2300670351\">תו\"ח לך פה, ג</a>. וראה לעיל על יד הערה 532."],["5186","588","<b>והוא ב\"ה</b>: ביא: והיו כ\"ה."],["5187","589","<b>דבימין ובה'</b>: שם: דימין וכ\"ה."],["5188","590","<b>כ\"ה אותיות. . דבימין וכ\"ה. . דשמאל</b>: סוטה לו, א."],["5189","591","<b>בה'</b>: זביא: בוי\"ו (!)."],["5190","592","<b>ושניהם באבן הב' שבשמאל</b>: ראה רש\"י שם."],["5191","593","<b>כמ\"ש בגמ'</b>: ראה סוטה לו, ב. יל\"ש תצוה כח, י (רמז שעט)."],["5192","594","<b>יוסף</b>: ביא: הוס[י]ף (!)"],["5193","595","<b>ממקום</b>: ביא: ממקור."]]],[2300550059,"<b>בעזר\"ה שבת פ' תצוה תקס\"ו.</b>\n<span data-k=\"pg\">1052</span> ּ<b>ועשית</b> ציץ<sup data-n=\"5194\">1</sup> זהב טהור<sup data-n=\"5195\">2</sup> ופתחת עליו פתוחי חותם קדש להוי', וידוע דברי רז\"ל קדש למ\"ד הי' כתוב מלמטה והוי' מלמעלה<sup data-n=\"5196\">3</sup> כו'. ולהבין זה וגם להבין מהו עיקר ענין הציץ ומה שהי' הציץ מכפר וכמ\"ש ונשא אהרן את עון הקדשים<sup data-n=\"5197\">4</sup> כו'. וגם מה שאמר עוד והי' על מצח אהרן<sup data-n=\"5198\">5</sup> ונשא אהרן וכו' וכפל עוד ואמר והי' על מצחו תמיד<sup data-n=\"5199\">6</sup> לרצון להם לפני הוי', ומהו שדקדק לומר תמיד לרצון כו' דמשמע דמן הציץ נמשך הרצון תמיד וכיצד הציץ ממשיך הרצון. וגם מה שאמר לרצון להם לפני הוי' כו'. והנה כל זה יובן בהקדים תחלה משמעות הכתובים הללו דמשמע דלמשה נצטווה מעשה הציץ שהוא יעשנו דוקא וכמ\"ש ועשית ציץ זהב טהור כו', ונצטוה עוד להיות ציץ זה על מצח אהרן דוקא, ויש בזה ב' תנאים, הא' מעשה הציץ שיעשנו משה ושיהי' על מצח אהרן דוקא וזה בלא זה אינו כלום כו'. דהנה פי' ציץ לשון הבטה והסתכלות<sup data-n=\"5200\">7</sup> כמו מציץ מן החרכים<sup data-n=\"5201\">8</sup> וכיוצא, וגם מלשון הארה וזיו בהיותו עדיין מאיר בהתחלתו והוא מלשון הנצה כמו הנצו הרמונים<sup data-n=\"5202\">9</sup> כו' וכן בהתחלת יציאת האור נק' נץ החמה<sup data-n=\"5203\">10</sup> וכמ\"כ כתיב יציץ נזרו<sup data-n=\"5204\">11</sup> כו', וב' הפירושי' אחד הוא.\n<b>אך</b> הנה תחלה יש להבין מהו בחי' אהר\"ן. הנה ידוע דאהרן הוא משבעה הרועים<sup data-n=\"5205\">12</sup> כו', ופי' רועה היינו עד\"מ הרועה צאן שהוא זן ומפרנס אותם במרעה ומשקה כך אהרן הי' זן ומפרנס לכללות נ\"י בהמשכת אהבה רבה שלמעלה מן השכל כו'. וביאור ענין המשכה זאת דלכאורה אין הדבר תלוי אלא באדם כמארז\"ל הכל בידי שמים חוץ מיראת שמים<sup data-n=\"5206\">13</sup> כו', אלא הענין הוא דיש ב' מיני אהבה, הא' אהבה שביכולת האדם להגיע אליה והיא הנק' אהבה טבעי\"ת המסותרת בלב כאו\"א מישראל מצד הירושה מאבותינו<sup data-n=\"5207\">14</sup> שהיו בחי' מרכבה<sup data-n=\"5208\">15</sup> כנ\"ל<sup data-n=\"5209\">16</sup> כידוע, וע\"ז ניתן הבחירה לבחור בטוב שכאשר מתעורר האדם לאהוב את ה' לפי אופן התעוררותו כך תתעורר אהבה זאת המסותרת ולא יותר, משא\"כ אהבה רבה שלמעלה מן השכל והטעם, זה אינו תלוי בהתעוררו' אדם אלא נמשכת עליו מלמעלה וכמ\"ש עד",[["5194","1","<b>ועשית ציץ</b>: מאמר זה הוא הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז משנת תקס\"ו. והנחה אחרת נדפסה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370370\" data-slug=\"torah-or\" data-id=\"3901370370\">תו\"א תצוה פג, א</a>. וראה בהנרשם במ\"מ לשם. ובארוכה לקמן שסג, ב ואילך. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י."],["5195","2","<b>ועשית ציץ זהב טהור</b>: תצוה כח, לו."],["5196","3","<b>קדש למ\"ד. . מלמטה והוי' מלמעלה</b>: באוה\"ת כאן (ע' א'תרצ) מציין: פ\"ו דשבת דס\"ג ע\"א [צ\"ל: ע\"ב — וכ\"ה לעיל שם ע' א'תרפז]. ופ\"ק דסוכה דף ה' ע\"א. ושם הלשון: יו\"ד ה\"א למעלה וקודש למ\"ד למטה. ראה גם לקמן שנט, ד. שסב, א. שסג, ב. שעד, ב. שעה, ב. ירושלמי יומא פ\"ד, ה\"א. מגילה פ\"א, ה\"ט."],["5197","4","<b>ונשא אהרן את עון הקדשים</b>: תצוה כח, לח."],["5198","5","<b>והי' על מצח אהרן</b>: התחלת הכתוב ונשא אהרן."],["5199","6","<b>והי' על מצחו תמיד</b>: סיום הכתוב והי' על מצח."],["5200","7","<b>ציץ לשון. . והסתכלות</b>: באוה\"ת תצוה ע' א'תרפט מציין: ב[זהר] פ' ויקהל דרי\"ז ע\"ב ע\"פ ויעש את הציץ, ציץ אסתכלותא. ראה גם לקמן שסג, ג."],["5201","8","<b>מציץ מן החרכים</b>: שה\"ש ב, ט."],["5202","9","<b>הנצו הרמונים</b>: שה\"ש ו, יא. ז, יג."],["5203","10","<b>נץ החמה</b>: ברכות ח, ב. ט, ב. ועוד."],["5204","11","<b>יציץ נזרו</b>: תהלים קלב, יח."],["5205","12","<b>דאהרן הוא משבעה הרועים</b>: ראה תיקונים לז\"ח קד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201655\" data-slug=\"likkutei-sichot\" data-id=\"1300201655\">לקו\"ש חנוכה (כרך כ) ע' 643</a>. בהעלותך (כרך לח) ע' 193. לעיל פ' וארא עז, ב."],["5206","13","<b>הכל בידי שמים. . שמים</b>: ברכות לג, ב."],["5207","14","<b>אהבה. . הירושה מאבותינו</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>."],["5208","15","<b>מאבותינו שהיו בחי' מרכבה</b>: נסמן לעיל פ' יתרו רנא, ג."],["5209","16","<b>כנ\"ל</b>: אולי כתוב כו'."]]],[2300550091,"יערה עלינו רו\"ח ממרום<sup data-n=\"5210\">17</sup>. והמעורר לכנס\"י באה\"ר זו הוא הנק' רוע\"ה הזן ומפרנס אותם להיות להם אה\"ר זאת, וישנו לרוע\"ה זה בכל דור ודור ונק' אהר\"ן. וע\"ז נא' לאהבה את ה' אלקיך<sup data-n=\"5211\">18</sup> כו' ולא כתי' לאהוב דמשמע רק כפי ההתעוררו' והוא כפי כחו באהבה הטבעי' הנ\"ל, אלא כתי' לאהבה בתוס' ה\"א מפני שהוא בחי' א\"ר<sup data-n=\"5212\">19</sup> הנ\"ל שאינה נגבלת בכלי והוא הנק' רעותא דלבא<sup data-n=\"5213\">20</sup> והוא ה\"א שבהבל הלב שאינו מתיישב בלב כו' וכמ\"ש במ\"א. וזהו לאהב\"ה דהיינו לבחי' סוכ\"ע שאינו בבחי' כלי כלל, דלית מח' תפיסא בי'<sup data-n=\"5214\">21</sup> למעלה מן השכל וההשגה וכמ\"ש אני ה' לא שניתי<sup data-n=\"5215\">22</sup> כו' וכמאמר אתה הוא קודם שנברא העולם<sup data-n=\"5216\">23</sup> כו' ומשם נמשך אהבה רבה זו ג\"כ שלמעלה מן ההשגה כו', וכענין מי לי בשמים<sup data-n=\"5217\">24</sup> ועמך לא חפצתי כו' גם לא <span data-k=\"pg\">תקכו</span> ּ בג\"ע עליון וג\"ע התחתון מאחר שאינם אלא רק זיו והוד משמו כו' ובא\"ר זאת אין הדביקות רק בעצמותו ומהותו ית' דוקא וכמ\"ש ועמך לא חפצתי כו' וד\"ל.\n<b>והנה</b> ארז\"ל דמשחרב בהמ\"ק מחיצה של ברזל מפסקת<sup data-n=\"5218\">25</sup> בין ישראל לאביהם שבשמי\"ם, פי' בין ישראל לאביהם שבשמים ולא בין אביהם שבשמים לישראל דקמי' עצמותו ית' גם חשך לא יחשיך<sup data-n=\"5219\">26</sup> כו' ולא שייך לומר שיפסיק לו מחיצה של ברזל כו', אלא רק בין ישראל לאביהם שבשמים להם הוא שייך לומר שיפסיק מחיצה של ברזל בעדם. והענין הוא משום דאין השינוי בגרעון אור אלקי מצד עצמו ח\"ו כי אני ה' לא שניתי כתי' אלא השינוי הוא מצד המקבלים שאין אור האלקי נכנס ושורה בהם מחמת בחי' מחיצה מפסקת שמפסקת עליהם ונק' מחיצה של ברזל. וענין מחיצה זו הוא בחי' קליפת עמלק דכתיב מלחמה לה' בעמלק מדור דור<sup data-n=\"5220\">27</sup> שבכל דור קליפה זו תקיפה מאד כמחיצה של ברזל ממש, והטעם שנק' מחיצה של ברזל דוקא, כי בחי' הקליפה דעמלק היינו בחי' גסות הרוח וחוצפא בלא טעם שזהו מפני מדת הנצחון והעקשות שתקיף בדעתו מאד בעקשות ונצחון כו', לכך הוא מתנשא בחוצפא גדולה דהרי אנו רואים במלחמת עמלק דסיבת המלחמה שלו שיצא ללחום עם ישראל לא הי' מסיבת ענין שנגעו לו ולעמו באיזה דבר כשאר האומות אלא מצד עצמו יצא ללחום מפני שלא יכלו לסבול",[["5210","17","<b>עד יערה עלינו רו\"ח ממרום</b>: ישעי' לב, טו."],["5211","18","<b>לאהבה את ה' אלקיך</b>: פ' שופטים יט, ט. נצבים ל, ו. טז. כ. בתו\"א כאן: לאהבה את ה' אלקיכם — עקב יא, יג. כב."],["5212","19","<b>א\"ר</b>: אהבה רבה."],["5213","20","<b>רעותא דלבא</b>: זהר וירא ק, א. ראה גם בענין רעו\"ד מאמרי אדה\"ז תקס\"ג ח\"א ע' שכא."],["5214","21","<b>דלית מח' תפיסא בי'</b>: ת\"ז בהקדמה (יז, א)."],["5215","22","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["5216","23","<b>אתה הוא קודם שנברא העולם</b>: ראה של\"ה ג, ב. תפלת השחר."],["5217","24","<b>מי לי בשמים</b>: תהלים עג, כה. ראה גם לקמן שסד, ד. מאמרי אדה\"א בראשית ע' תקע. שמות ח\"ב ע' שפ. קונטרסים ע' תקצג ובהנסמן בהנ\"ל. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670125\" data-slug=\"torat-chaim\" data-id=\"2300670125\">תו\"ח נח ס, ב</a>."],["5218","25","<b>דמשחרב בהמ\"ק מחיצה של ברזל מפסקת</b>: ע\"פ פסחים פה, ב. ראה גם ברכות לב, ב וברש\"י שם. אוה\"ת כאן ע' א'תרצא."],["5219","26","<b>גם חשך לא יחשיך</b>: תהלים קלט, יב."],["5220","27","<b>מלחמה לה' בעמלק מדור דור</b>: בשלח יז, טז."]]],[2300550123,"התנשאות ישראל ועוצם רוממות מדריגת גילוי אלקות שהי' בהם ביציא' מצרים וכל האותות וכו' כי קליפה זו דחוצפא כו' לא תוכל לסבול כל דבר המתנשא וכו'. וכנראה בחוש דכל מי שיש בו גסות הרוח וחוצפא כו' שמאד לא יוכל לסבול התנשאות זולתו ביותר עד אשר ימסור נפשו להפילו כו', משא\"כ במי שאין לו מדה זו הגם שיהי' רוצח ואכזרי ושאר מדות רעות לא יתפעל כ\"כ מהתנשאות זולתו כו' וד\"ל. וזהו שנק' קליפת עמלק בשם מחיצה של ברזל דוקא לפי שהיא קשה כברזל וזהו בחי' פנימיות דקליפה זאת, ואמנם בחי' חיצוניות שלה הוא אשר המדה נמצאת בכמה בנ\"א שתשוקתם להתגדל בעיני הבריות וזהו כל חיותם כו' ולכך המה מתנהגים במלבושי כבוד בלבושי יקר ובכלים נאים מכסף וזהב ודירה נאה והפיזור להוצאות ביד מלאה ורחבה כו', ויש בנ\"א ששונאים מדה והנהגה זאת והוא לפי שחיצוניות דגסות הרוח וחוצפא הוא ההנהגה ברוממות בלבושי' ודירות ושאר הוצאות כו', ומי שאין בו מדת עמלק בפנימיות אין לו גם בחיצוניות כו' וד\"ל. ואע\"פ שגם ז' מדות דקליפה כמו הרציחה והתאוה וכיוצא כולם רעים מאד, אבל שרש כולם הוא קליפת עמלק הנ\"ל משום דשאר המדות הרעות הן רק תולדות הגסות כנראה בחוש הטבע, וזהו ראשית גוים עמלק<sup data-n=\"5221\">28</sup> כו', שהוא בחי' ראשית לז' גוים כו', ולכך כתי' בי' בעמלק כי יד על כס יה<sup data-n=\"5222\">29</sup> מלחמה כו' פי' על כס י\"ה מפני שקליפה זו דעמלק מכסה על שם י\"ה ומעלים אורו. דהנה ארז\"ל שאין השם שלם<sup data-n=\"5223\">30</sup> ואין הכסא שלם עד שימחה זכר עמלק כו', פי' אין השם שלם <span data-k=\"pg\">1054</span> ּ היינו מה שנחלק י\"ה מו\"ה שבשם הוי' ואין הכסא שלם היינו מה שנסתלק האור גם מי\"ה והיינו שנק' כס לפי שאלף דכסא הוא ענין בחי' אור ההשראה ששורה על הכסא, משא\"כ בהסתלקות האלף נק' כס חסר אלף והוא מפני מסך ומחיצה של ברזל דעמלק שכיסה והעלים אור זה, וזהו כי יד על כס י\"ה כלומר נרתק י\"ה מפני שיש בכאו\"א מחיצה של ברזל המכסה על בחי' י\"ה שבנפשו כו', וביאור ענין י\"ה למעלה ואיך שישנו גם בפרט בכל נפש מישראל.\n<b>הנה</b> כתיב עזי וזמרת יה<sup data-n=\"5224\">31</sup> ויהי לי לישועה, פי' וזמרת י\"ה הנה אותיות י\"ה מרמזים לבחי' סוכ\"ע ולבחי' ממכ\"ע<sup data-n=\"5225\">32</sup> בכלל, דהנה בתמונת האותיות ידוע בספרי הקבלה דהיו\"ד צריך לעשות תחלה כשכותבין אות ה\"א ראשונה בשם הוי'<sup data-n=\"5226\">33</sup> דהיינו שכותב כמו יו\"ד בתחלה ואח\"כ ממשיך ממנו אורך ורוחב בצורת ה\"א כו', והטעם הוא לפי שא\"א להיות התפשטות אורך ורוחב בלתי צמצום בתחלה מפני שאחר הצמצום דוקא יוכל להיות התפשטות כו', והיו\"ד הוא מורה בחי' צמצום<sup data-n=\"5227\">34</sup> כידוע",[["5221","28","<b>ראשית גוים עמלק</b>: בלק כד, כ. ראה גם לקמן שסה, א. שסו, ג. מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ."],["5222","29","<b>כי יד על כס יה</b>: בשלח שם."],["5223","30","<b>שאין השם שלם</b>: ראה תנחומא ס\"פ תצא. רש\"י ולקח טוב ס\"פ בשלח. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300231268\" data-slug=\"likkutei-sichot\" data-id=\"1300231268\">לקו\"ש</a> י\"ג סיון (כרך כג) ע' 268 הערה 33."],["5224","31","<b>עזי וזמרת יה</b>: בשלח טו, ב."],["5225","32","<b>י\"ה. . סוכ\"ע ולבחי' ממכ\"ע</b>: ראה בסמוך בפנים."],["5226","33","<b>בספרי הקבלה דהיו\"ד. . ה' ראשונה בשם הוי'</b>: ראה מ\"ח מסכת תקון תפילין פ\"ב, מ\"ד. וראה גם לקמן שסז, ב. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תריד."],["5227","34","<b>והיו\"ד. . צמצום</b>: ראה אגה\"ת פ\"ד. לעיל פ' בשלח קנ, ב. וש\"נ."]]],[2300550155,"והאורך ורוחב שממשיך אח\"כ ממנו הוא בחי' התפשטו' שאחר הצמצום כו'. וכך יובן למעלה דכתי' בי\"ה ה' צור עולמים<sup data-n=\"5228\">35</sup> באותיות י\"ה נבראו ב' עולמות עוה\"ב ביו\"ד ועוה\"ז בה\"א ולמעלה יותר הן הנה בכלל בחי' עלמא דאתכסי' ועלמא<sup data-n=\"5229\">37</sup> דאתגליא<sup data-n=\"5230\">36</sup> והיינו בחי' סוכ\"ע ובחי' ממכ\"ע<sup data-n=\"5231\">38</sup>, בחי' סובב הוא הבחי' העלם בחי' הצמצום שביו\"ד כו' ואח\"כ נמשך ובא בבחי' הגילוי והוא בחי' התפשטות אורך ורוחב בבחי' ממכ\"ע וד\"ל. וזהו ענין כללי לכללות כל ההשתל' עד רום המעלות דהיינו גם מבחי' עצמות אור א\"ס שלפני האצי' אחר שאין אצי' ערוך לו כלל<sup data-n=\"5232\">39</sup> הנה כדי שיאיר אורו בנאצלים מוכרח לבוא בבחי' הצמצום בתחלה כיו\"ד שהוא צמצום, וזהו מ\"ש ישת חוש\"ך סתרו<sup data-n=\"5233\">40</sup> שהוא רק כנקודה א' דיו\"ד לפי שאין אור זה נחשב רק כטפה בים אוקיינוס בלבד לכך אינו אלא נקודה א' כיו\"ד כו', ואח\"כ נמשך מיו\"ד זה בחי' אורך ורוחב כו', והיינו ממש כדוגמת כתיבת ה\"א ראשונה שא\"א לכתוב אלא באופן הנ\"ל שיכתוב כמו יו\"ד קודם ואח\"כ ימשיך אורך ורוחב מטעם הנ\"ל וד\"ל. וזהו וזמרת יה אחר שנזמר ונמשך אותיות י\"ה בצמצום ואח\"כ התפשטות ואזי ממילא ויהי לי לישועה, אך כאשר יש כיסוי מסך המבדיל הנה עושה כס ונרתק לי\"ה בב' אופנים, א' שלא יאיר אור א\"ס בי\"ה והב' שלא יומשך מי\"ה לו\"ה, והיינו שאין השם שלם ואין הכסא שלם כנ\"ל. והנה צריך בודאי להסיר המסך הזה והוא ענין הסרת המסך דעמלק הנ\"ל, ובמה שיסירו אותו, ותחלה יש להבין מהו בחי' י\"ה בפרט בכל נפש מישראל. הנה ידוע שההתבוננו' בהשגה ודעת שהוא משיג בהשתל' וכיוצא זהו בחי' ה\"א בהתפשטו' באורך ורוחב והאהבה הנולדה מהתבוננות זהו בחי' ו\"ה, והאהבה רבה שנולדה מלמעלה מן השכל וההשג\"ה דהיינו מבחי' סוכ\"ע כנ\"ל זהו בחי' יו\"ד וכנ\"ל שיו\"ד ה\"א למעלה הם בחי' סובב וממלא, וכך הוא בחי' י\"ה בנפש האלקי' <span data-k=\"pg\">תקכז</span> ּ בהתפעלותה מהתבוננו' בחי' סובב ובחי' ממלא כידוע. והנה המסך המסתיר על בחי' י\"ה שבנפש האלקי' היינו קליפת עמלק הנ\"ל שהוא גסות הרוח ועקשות ונצחון כמו שנראה בחוש שלפעמים גם כשיעמיק האדם דעתו בהתבוננו' בתפלה לא תתפעל הנפש מאומה מפני גסות הרוח דנפשו הבהמיות דאע\"פ שלבבו יבין וכו' מ\"מ הוא רוצה בנצחון להיות דוקא בחי' נפרד, מפני שטבע דקליפה זו למסור נפשה לעמוד לנגד לכל מי שיש לו עלי' והתנשאות כנ\"ל וע\"כ בהעלות הנפש האלקי' להדבק באלקי' חיים אזי תעמוד קליפה זו דוקא לבטלו ולהסתיר האור כו', ומונעת ב' דברים, א' לבלתי יאיר אור אלקי' בי\"ה שבנפש דהיינו בחו\"ב. והב' במניעת התפעלו' אהבה שלא תומשך גם מן ההתבוננו' והוא להבדיל ו\"ה מי\"ה כו' וד\"ל.",[["5228","35","<b>בי\"ה ה' צור עולמים</b>: ישעי' כו, ד. ראה מנחות כט, ב."],["5229","37","<b>עלמא דאתכסי' ועלמא דאתגליא</b>: ראה זהר בראשית יח, א. (ס\"ת) ויצא קנב, א. קנח, רע\"ב. וארא כט, ב. ת\"ז בהקדמה (א, סע\"א ואילך)."],["5230","36","<b>עוה\"ב. . ועוה\"ז. . עלמא דאתכסי' ועלמא דאתגליא</b>: ראה גם לקמן שסז, א."],["5231","38","<b>סוכ\"ע ובחי' ממכ\"ע</b>: זהר (רע\"מ) פינחס רכה, א."],["5232","39","<b>שאין אצי' ערוך לו כלל</b>: ראה גם לקמן פ' ויקהל תג, ג. ש\"א ט, א. ובהערה 9."],["5233","40","<b>ישת חוש\"ך סתרו</b>: תהלים יח, יב."]]],[2300550187,"<b>וצריך</b> להסיר המסך הזה, וענין התיקון בזה הוא ע\"י ב' דברים, א' שצריך לפרוץ מחיצה זו של ברזל. והב' אחר שנפרץ מחיצה זו יאיר האור דרך הפרצה למטה בי\"ה וגם בו\"ה כו'. וכללות ענין זה הוא ענין הציץ שעשה משה כמו דכתיב ועשית צי\"ץ זה\"ב טהו\"ר כו', דהנה בפי' ציץ הוא ג\"כ מלשון הבטה והסתכלות כמ\"ש מציץ מן החרכים, פי' חרכים<sup data-n=\"5234\">41</sup> הן כמו סדקים מפולשין שעושים במחיצה של ברזל כי ע\"י הרהורי תשובה שלמטה נעשי' כמו פרצות קטנות במחיצה להסתכל בהן, וכך למעלה יש כמו בחי' סדקים מפולשי' שנעשי' במחיצה של ברזל הנ\"ל, ואע\"פ שהם קטנים מאד ואינם כמו החלונות הגדולים שנאמר בהן משגיח מן החלונות<sup data-n=\"5235\">42</sup> כו', אבל מ\"מ מביט ומסתכל הוא ית' בכנס\"י בחרכים הקטנים, והבטה זאת נק' ציץ, או כמו יציאת האור מתוך הסדק הקצר שנק' בשם ציץ ג\"כ כמו ענין הנץ החמה דהיינו משעה שמתחלת הארתה וזיווה לבקוע במסך עובי רקיע והכל ענין א' הוא דהיינו ענין בקיעת האור כשבוקע ועובר דרך פרצה קצרה. והוא מובן למעלה שזהו בחי' הבטה והסתכלות שמעצמות אור א\"ס בי\"ה כשבוקע ועובר דרך החרכים הקטנים כמ\"ש מציץ מן החרכים כו', וזה האור הי' בבחי' הציץ שעשה משה כמ\"ש יציץ נזרו כו' שהרי הי' מרצה ומכפר כמ\"ש והי' על מצחו תמיד לרצון להם כו' וד\"ל.\n<b>וזהו</b> ועשית ציץ זהב טהור כו' והי' על מצח אהרן כו' שיש בזה ב' תנאים, א' שיעשנו משה דוקא. והב' שיונח על מצח אהרן אח\"כ, מפני שיש ב' דברים בתיקון האור, א' שיעשו פרצה. והב' שיאיר אור בה, והנה אותו האור שמאיר בה עשה משה דוקא כמ\"ש ועשית ציץ זהב כו'. והטעם הוא לפי שעיקר המנגד לבטל הסתר המסך דעמלק לא הי' אלא ע\"י משה לפי שבחי' משה הוא מבחי' מ\"ה כמ\"ש ונחנו מ\"ה כי תלינו עלינו<sup data-n=\"5236\">43</sup> וכו' והוא בחי' מ\"ה שבחכמ\"ה שנק' כח מ\"ה<sup data-n=\"5237\">44</sup> כלומר בחי' אי\"ן והיינו בחי' הביטול במציאות, ולכך כל התורה אינו נק' אלא על שם משה ונק' תורת משה<sup data-n=\"5238\">45</sup> וכמ\"ש תורה צוה לנו משה<sup data-n=\"5239\">46</sup> דמשמע שהתורה של משה היא ממש כאילו הוא צוה אותה מעצמו, ולכאו' זה יפלא מאד דהלא משה קיבל תורה מפי הגבורה בכל דבר ודבר כמבואר בתורה בכל פ' ויאמר ה' אל משה<sup data-n=\"5240\">47</sup> כו'. אך הענין הוא לפי שהי' נשמתו מבחי' מ\"ה הרי <span data-k=\"pg\">1056</span> ּ הי' בבחי' הביטול בתכלית ולא הי' תופס מקום בפ\"ע כלל וע\"כ התורה שנאמרה לו נק' על שמו כי לא הי' רק בחי' כלי לאור",[["5234","41","<b>חרכים</b>: ראה גם בענין חרכים מאמרי אדה\"ז תקס\"ד ע' רמב. ע' רמה. לקו\"ת שמ\"ע צא סע\"ג ואילך. מאמרי אדה\"א נ\"ך ע' תט. לקמן שסט, א ואילך."],["5235","42","<b>משגיח מן החלונות</b>: שה\"ש ב, ט."],["5236","43","<b>ונחנו מ\"ה כי תלינו עלינו</b>: בשלח טז, ז. ראה גם לעיל פ' שמות מג, א. וש\"נ."],["5237","44","<b>שבחכמ\"ה שנק' כח מ\"ה</b>: ראה זהר (רע\"מ) צו כח, א. לד, א."],["5238","45","<b>תורת משה</b>: יהושע ח, לא. לב. כג, ו. ועוד. ראה גם לקמן שסב, ד."],["5239","46","<b>תורה צוה לנו משה</b>: ברכה לג, ד. ראה גם לקמן שסב, ג."],["5240","47","<b>בכל פ' ויאמר ה' אל משה</b>: ראה גם לעיל פ' וארא נט, א הערה 30."]]],[2300550219,"התורה בלתי תפיסת מקום ויש בפ\"ע עד שיתפס בשם בפ\"ע, וזהו תורה צוה לנו משה דהיינו אור אלקי שדיבר בפי משה אחר שלא הי' רק כמו כלי בעלמא לדיבור העליון כמארז\"ל שכינה מדברת מתוך גרונו<sup data-n=\"5241\">48</sup> של משה כו'. וזהו ג\"כ כל עיקר ענין לימוד התורה בכל דור ודור שיהא רק בחי' כלי לדבר ה' זו הלכה<sup data-n=\"5242\">49</sup> או המקרא שלומד וכמ\"ש ודברי אשר שמתי בפיך<sup data-n=\"5243\">50</sup> כו' ואינו אלא בפה בלבד ובפיו הוא שוכן דבר ה' שלמעלה מכל ההשתל', כי אין התלבשות אור א\"ס כמו שהוא בעצמותו באין שינוי קודם שנברא העולם לאחר שנברא כו' אלא בחכמ\"ה שבתורה דוקא מטעם שאין אוא\"ס שורה אלא בבחי' מ\"ה כו' וכמ\"ש במ\"א ע\"פ הוי' בחכמ\"ה<sup data-n=\"5244\">51</sup> כו' שאין אור א\"ס אלא בחכמ\"ה<sup data-n=\"5245\">52</sup> לפי שבה בחי' הביטול כו', משא\"כ האומר אין לי אלא תורה<sup data-n=\"5246\">53</sup> כו' שעושה את לימודו עצמו ליש ודבר מבלעדי אוא\"ס ששורה בתורה הרי הוא מפריד בזה החכמ\"ה שבתורה מאור א\"ס ואז אפי' תורה אין לו כי מסתיר בזה אוא\"ס ואין לחכ' שבתורה קיום רק מאור א\"ס שמתלבש בה וזהו לא תחללו<sup data-n=\"5247\">54</sup> לא תעשו חלל<sup data-n=\"5248\">55</sup> כו' וכמ\"ש במ\"א וד\"ל. וזהו ואשים דברי בפיך<sup data-n=\"5249\">56</sup> ובצל ידי כסיתי\"ך לנטוע שמים כו', פי' ע\"י דבר ה' זו הלכה שבפיך אזי בזה הוא יסוד מוסד לכל ההשתל' באורות וכלים פנימים ומקיפים כי בתורה מתחבר אוא\"ס בעולמות דאבי\"ע, והיינו לנטוע שמי\"ם שהן עולם הנאצלים וליסוד ארץ הן עולמות הנפרדים בי\"ע והכל מפני שדברי אשים בפיך ובצל ידי כסיתיך, פי' בפיך בבחי' א\"פ ובצל יד\"י היינו בחי' מקיפים ששורין בחכ' שבתורה כי כל הקורא ושונה<sup data-n=\"5250\">57</sup> הקב\"ה יושב וקורא ושונה כנגד\"ו בבחי' מקיף עליו וכמ\"ש ה' צלך<sup data-n=\"5251\">58</sup> כו' וד\"ל.\n<b>וזהו</b> ועשית ציץ כו' דמשה דוקא יעשנו לפי שבחי' מ\"ה שבתורה הוא עיקר המנגד לבחי' החוצפא והגסות דעמלק להיותו תכלית היפוכו וע\"כ ביכולתו דוקא לשברו ולהפילו. וזהו שאמר משה ליהושע בחר לנו אנשים<sup data-n=\"5252\">59</sup> וצא הלחם בעמלק בחר לנ\"ו דוקא אותן שהן ממדרגות מ\"ה דתורת משה כנ\"ל, כי בחי' מ\"ה זה ביכולתו לשבור גם מחיצה של ברזל הנ\"ל דקליפת עמלק. והענין הוא בחי' לב נשבר ונדכה<sup data-n=\"5253\">60</sup> ונבזה בעיניו נמאס<sup data-n=\"5254\">61</sup> כו' שנעשה ע\"י סיבת בחי' הביטול דמ\"ה כו' כידוע, ולב נשב\"ר זה הוא הסדק והפרצה שבמחיצה של הברזל הקשה דעמלק שהוא הגסות והחוצפא כו' מפני שנשבר ונופל הגסות ע\"י עוצם בחי' לב נשבר כו' וד\"ל. וזהו ענין הציץ כמ\"ש מציץ",[["5241","48","<b>שכינה מדברת מתוך גרונו</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310039\" data-slug=\"tanya\" data-id=\"3401310039\">תניא</a> פל\"ד. לעיל פ' בשלח קצד, ד הערה 540."],["5242","49","<b>לדבר ה' זו הלכה</b>: עמוס ח, יב. שבת קלח, ב."],["5243","50","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["5244","51","<b>הוי' בחכמ\"ה</b>: משלי ג, יט."],["5245","52","<b><a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">שאין אור א</a>\"ס אלא בחכמ\"ה</b>: ראה גם תניא פל\"ה בהג\"ה. לעיל פ' שמות ז, ד. וש\"נ."],["5246","53","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["5247","54","<b>לא תחללו</b>: אמור כב, לב [ושם: ולא — ראה גם לקמן שנט, ב. פ' פקודי תמג, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשסב]."],["5248","55","<b>לא תחללו לא תעשו חלל</b>: ראה גם לקמן פ' פקודי תמג, ד. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שפו ואילך (ד\"ה זה). תקס\"ה ח\"ב ע' תרעה (ובהנסמן במ\"מ לשם) וע' תשסב. פרשיות התורה ח\"ב ע' תשיט ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370371\" data-slug=\"torah-or\" data-id=\"3901370371\">תו\"א כאן פג, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380056\" data-slug=\"likkutei-torah\" data-id=\"4001380056\">לקו\"ת פקודי ד, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380219\" data-slug=\"likkutei-torah\" data-id=\"4001380219\">אמור לג, ב</a>. וראה ג\"כ לקוטי ביאורים לשעה\"י (קה\"ת) קעה, ד. קפ, א."],["5249","56","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["5250","57","<b>כל הקורא ושונה</b>: ראה תדא\"ר רפי\"ח. לעיל פ' וארא נח, ג. וש\"נ."],["5251","58","<b>ה' צלך</b>: תהלים קכא, ה. ראה גם לעיל פ' וארא סה, ג הערה 283."],["5252","59","<b>בחר לנו אנשים</b>: בשלח יז, ט."],["5253","60","<b>לב נשבר ונדכה</b>: תהלים נא, יט."],["5254","61","<b>ונבזה בעיניו נמאס</b>: תהלים טו, ד."]]],[2300550251,"מן החרכי\"ם שהן עניני הרהורי תשובה שבלב נשבר שנעשי' ע\"י מ\"ה דמשה דוקא כנ\"ל, וזהו ועשית ציץ שמשה דוקא יעשה להיות מצי\"ץ מן החרכי\"ם כו' וד\"ל.\n<b>וענין</b> זהב טהור דוקא לפי שיש ב' מדרגות באהבה, א' אהבה שנמשך כמים והיא בבחי' קרירות כידוע וכמ\"ש אהבת עולם אהבתיך<sup data-n=\"5255\">63</sup> ע\"כ משכתיך חסד כו', והוא בחי' כסף שהוא <span data-k=\"pg\">תקכח</span> ּ בקרירות, ויש אהבה בבחי' רשפי אש<sup data-n=\"5256\">62</sup> בחמימות התשוקה והיא בבחי' הזהב וידוע שבזה מעלת הזהב על הכסף<sup data-n=\"5257\">64</sup> יתירה להיות כי האהבה ברשפי אש אין לה שיעור ולא הפסק כלל כו'. ובבחי' אהבה זו דרשפי אש הי' ענין הציץ כי כדי שיהא מרצה תמיד כמ\"ש והי' על מצחו תמי\"ד לרצון כו' בלי הפסק כלל, לכך נאמר ועשית ציץ זה\"ב טהור דוקא לפי שבזה הוא יתרון מעלת הזהב על הכסף כנ\"ל, כי בציץ דזהב טהור הי' בחי' הסתכלות הרצון מלמעלה למטה בכנס\"י בבחי' אהבה ברשפי אש שאין לה הפסק כו' וכתי' אז לא הביט און ביעקב<sup data-n=\"5258\">65</sup> כו' כי מחמת רשפי אש האהבה מים רבים לא יכבו\"ה<sup data-n=\"5259\">66</sup> כו'. וזהו פי' זהב טהו\"ר כמ\"ש טהו\"ר עיני\"ם מראות ברע<sup data-n=\"5260\">67</sup> כו' עד\"מ הבן לגבי אביו דאם אהבת אביו אליו באהבה ברשפי אש גם שיעשה הבן דברי' שנגד רצונותיו לא איכפת לו מפני שתמיד ירצ\"ה לו וכמ\"ש כאב את בן ירצ\"ה<sup data-n=\"5261\">68</sup> כו' וד\"ל (וזהו דכתי' לי הכסף ולי הזה\"ב<sup data-n=\"5262\">69</sup> נאום ה', פי' ל\"י הזה\"ב היינו אהבה ברשפי אש שנמשך מאוא\"ס להיות מציץ מן החרכי\"ם בציץ הנ\"ל וד\"ל).\n<b>ופתחת</b> עליו פתוחי חותם קדש להוי' קדש למ\"ד מלמטה והוי' מלמעלה כו'. הנה ארז\"ל חותמו של הקב\"ה אמ\"ת<sup data-n=\"5263\">70</sup> ואין אמ\"ת אלא תורה<sup data-n=\"5264\">71</sup> כו', דהנה עד\"מ החותם הגשמי שאותיות החותם כשנחקקי' בשעוה ומתהוים שם אותיות אע\"פ שהאותיות החוקקי' עם אותיות הנחקקי' בשעוה אין להם ערך ומהות אחד שהרי אותיות החוקקי' הם מגופו של החותם החוקק ואותיות שבשעוה הם מהות אחר, מ\"מ האותיות הנחקקים בשעוה המה בדוגמא ממש לאותיות החותם אחר שנחקקו האותיות מאותיות החותם הרי נחקק כל אות ואות שבחותם בשעוה בצלמו וכדמותו כמו שהוא בחותם ממש כידוע. וכך יובן הנמשל מזה בענין חותמו של הקב\"ה, דהנה גופו של חותם העליון הוא מדת אמ\"ת והוא כולל ראש תוך סוף<sup data-n=\"5265\">72</sup> שבכ\"ב אותיות ולמעלה הן הנה בחי' רמ\"ח אברים דמלכא<sup data-n=\"5266\">73</sup> ומתלבשים ונחקקים בכ\"ב אותיות התורה למטה, אבל למעלה בשרש אותיות התורה הם בחי' אותיות שבחותם עצמו וכמאמר אין אמת אלא תור\"ה וא\"כ כללות כ\"ב אותיו' שבתורה נק' גופו של חותם ואשר נחקק על ידו בהשתל'",[["5255","63","<b>אהבת עולם אהבתיך</b>: ירמי' לא, ב [ושם: ואהבת — נסמן לעיל פ' וארא סב, ג]."],["5256","62","<b>אהבה שנמשך כמים. . רשפי אש</b>: ראה גם מאמרי אדה\"א בראשית ע' רלט."],["5257","64","<b>מעלת הזהב על הכסף</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310055\" data-slug=\"tanya\" data-id=\"3401310055\">תניא פ\"נ</a>. מאמרי אדה\"א בראשית ע' קסט. וש\"נ."],["5258","65","<b>לא הביט און ביעקב</b>: בלק כג, כא."],["5259","66","<b>מים רבים לא יכבו\"ה</b>: ע\"פ שה\"ש ח, ז."],["5260","67","<b>טהו\"ר עיני\"ם מראות ברע</b>: חבקוק א, יג (ושם — רע. ראה מנחת שי שם. לעיל פ' בא קכג, ד הערה 468]."],["5261","68","<b>כאב את בן ירצ\"ה</b>: משלי ג, יב [ושם: וכאב]."],["5262","69","<b>לי הכסף ולי הזה\"ב</b>: חגי ב, ח."],["5263","70","<b>חותמו של הקב\"ה אמ\"ת</b>: שבת נה, א."],["5264","71","<b>ואין אמ\"ת אלא תורה</b>: ראה ירושלמי ר\"ה פ\"ג, ה\"ח. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' שסט."],["5265","72","<b>אמ\"ת. . ראש תוך סוף</b>: נסמן לעיל שלא, ג."],["5266","73","<b>רמ\"ח אברים דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."]]],[2300550282,"העולמות מאין ליש בצירופי אותיות הרבה כידוע, ע\"ז נא' נעשה אדם בצלמינ\"ו כדמותינ\"ו<sup data-n=\"5267\">74</sup> פי' שאין זה אלא כמו בחי' דמות לאותיו' החותם עצמו, והיינו כמשל האותיו' הנחקקי' בשעוה שהן מהות אחר אלא שנעשו בדוגמא בלבד כך כתיב נעשה אד\"ם בצלמנו כדמותנו כו', אבל באמת אין להם ערך ויחוס כלל לגבי עצמות האצי'. וכמ\"כ מאותיות המאציל בנאצלים כו' נאמר ג\"כ נעשה אדם בצלמנו כו' אלא שנק' אדם דאצי' כידוע, אבל בעצמות אור א\"ס נא' כי לא אדם הוא<sup data-n=\"5268\">75</sup> כו' וכמאמר ולאו מכל אינון מדו\"ת כלל<sup data-n=\"5269\">76</sup> וד\"ל. והנה רמ\"ח מ\"ע למטה שנק' למעלה רמ\"ח אברי' דמלכא הוא אשר באי' ונמשכי' למטה בדרך חקיקה מן גופו של חותם כנ\"ל, וזהו ופתחת עליו פתוחי חותם פי' פתוחי היינו חקיקת האותיות שבחותם והוא שיהא נחקקי' האותיות שבחותם למטה בכ\"ב אותיות שבתו' וברמ\"ח מ\"ע בפרט <span data-k=\"pg\">1058</span> ּ בכדי שע\"י פתוחי חות\"ם הזה יהי' להם לזכרון רצון תמיד לפני ה' כי ע\"י שהחותם נחקק בו בדוגמא ממש עי\"ז יזכור להיות לו לרצון תמיד, עד\"מ אדם שנגמר בדעתו איזה ענין ונחלט ברצונו וירא שישכח ויעשה היפך רצונו עושה חותם ואות לזכרון רצון שירצה בענין זה תמיד ולא ישתנה, והחותם הוא שיחתום בטבעתו באותיות חקוקים בשעוה וכיוצא ובראותו חותמו בשעוה יזכור להיות לו לרצון ולא ישנה כו', כך חותמו של הקב\"ה הי' נחקק בציץ זהב טהור וכמ\"ש ופתחת עליו פתוחי חותם והוא מבחי' חותם של התורה כנ\"ל בכדי שיהי' לרצון תמיד לפני הוי' במעשה המצות שיעשו ישראל ולא ישכח עליהם, וזהו והי' על מצחו לרצון להם לפני ה' כו' וד\"ל.\n<b>אך</b> יש להבין מהיכן יש כח לאותיות הללו קדש להוי' שנחקק בציץ לעורר הרצון תמיד כו', ותחלה יש להבין מהו ענין אותיות הללו קדש להוי', ומה שאמרו ז\"ל קדש למ\"ד הי' כתוב מלמטה והוי' מלמעלה. כי הנה ידוע דהמצות הן רצונותיו ית' והתורה היא חכמתו ורצונו וחכמתו שבתורה ומצות הרי ירדו ונתלבשו למטה מטה בעניני' גשמי' מאד כצמר הציצית וקלף התפילין אך מ\"מ הן בחי' רצון העליון אלא שירד הרצון ונתלבש בדרך חקיקה באותיות החותם בשעוה וכיוצא. והנה ידוע דבאתעדל\"ת נעשה אתעדל\"ע<sup data-n=\"5270\">77</sup> כמאמר הידוע דרוח אייתי<sup data-n=\"5271\">78</sup> רוח ואמשיך רוח כו', וא\"כ כשישראל עושין רצונו של מקום במעשה המצות רוח אייתי רוח כו' לעורר בחי' הרצון העליון למעלה כי כמים הפנים<sup data-n=\"5272\">79</sup> וכו' להיות מציץ מן החרכי\"ם באהבה ורצון ברשפי אש כנ\"ל. אך בזה יש תנאי אחד והוא שיהי' במעשה המצות ענין הכנעה בקבלת עומ\"ש ולא בפריקת עול, כי ע\"י המצוה מעורר בחי' הרצה\"ע שהוא מקור כל המקיפי' העליונים",[["5267","74","<b>נעשה אדם בצלמינ\"ו כדמותינ\"ו</b>: בראשית א, כו."],["5268","75","<b>כי לא אדם הוא</b>: שמו\"א טו, כט."],["5269","76","<b>ולאו מכל אינון מדו\"ת כלל</b>: ראה ת\"ז בהקדמה (יז, ב)."],["5270","77","<b>דבאתעדל\"ת נעשה אתעדל\"ע</b>: נסמן לעיל פ' יתרו רנט, ב."],["5271","78","<b>דרוח אייתי רוח</b>: נסמן לעיל רנא, א."],["5272","79","<b>כמים הפנים</b>: משלי כז, יט."]]],[2300550310,"וכמו שאנו אומרים אשר קדשנ\"ו<sup data-n=\"5273\">80</sup> במצוותיו פי' קדשנ\"ו ל' הבדלה כדפרש\"י קדושי\"ם תהיו מובדלים<sup data-n=\"5274\">81</sup> כו' והוא בחי' המקיף העליון וכידוע שהמצות הן בחי' לבושים שעליהם דוקא שורה אור המקיף<sup data-n=\"5275\">82</sup> וכמ\"ש במ\"א. וא\"כ בקדושה זו דבחי' מקיף צריך שלא יהא מסתיר דבר שנראה לבחי' יש ובחי' נפרד והוא התנשאו' הלב אלא צריך הכנעה והוא מפני שנא' כי תועבת ה' כל גבה לב<sup data-n=\"5276\">83</sup>, ופי' כל מרבה הוא<sup data-n=\"5277\">*84</sup> גם להגסות הנראה בבחי' חיצוניות בלבד והוא חיצוניות הקליפה דעמלק כנ\"ל שהן הנהגות הגדולה בבגד יקר ודירה נאה כו'. ומכ\"ש כשהגסות הוא בבחי' הפנימי' כו' וכמארז\"ל אין אני והוא יכולים לדור<sup data-n=\"5278\">84</sup> כו' כי תועבת ה' כל גבה לב גם בחיצוניות עד שאין לו דירה עמו גם במעשה המצות שיעשה אע\"פ שהם לבושים לאור מקיף. ולכך צריך דוקא קבלת עול והכנעה במעשה המצות בכדי שיהי' לו דירה עמו לשכון בו אור המקיף באמרו אשר קדשנ\"ו במצוותי\"ו כו', והוא מטעם הנ\"ל שהתורה היא בבחי' מש\"ה דהוא שם מ\"ה לכך אומר תורה ציוה לנו משה שהוא בחי' הביטול היפך הגסות כו' וד\"ל. וזהו ענין קדש למ\"ד שהי' כתוב בציץ מלמטה פי' קדש למ\"ד היינו בחי' קדושת אור המקיף שנמשך ע\"י מעשה המצות כאמרו אשר קדשנ\"ו במצוותי\"ו כו' כי רוח אייתי רוח כו' וכנ\"ל שעי\"ז מעורר בחי' הרצון העליון למעלה <span data-k=\"pg\">תקכט</span> ּ בציץ להיות מציץ מן החרכים כו', ולהיות כי קדושה זאת נמשכת מלמעלה ע\"י אתעדל\"ת דוקא במעשה המצות כנ\"ל לכך נכתב קדש למ\"ד מלמטה דהיינו כלומר מפני שמלמטה למעלה מתעורר קדושה זאת והיינו קדש לה' כי כל למ\"ד מורה ענין ההעלאה למעלה<sup data-n=\"5279\">85</sup> כמו נברך לאלקינו<sup data-n=\"5280\">86</sup> וכיוצא, אבל בשיטה העליונה הי' כתוב הוי' בלבד ולא להוי'.\n<b>והענין</b> לפי שיש ב' מדרגות ברצון, הא' הרצון המתגלה כבר כמו רצונות האדם שנובעים ומתגלים בו תמיד לפעמים ירצה כך ולפעמים כך כו', וא\"כ בהכרח שהשינוי בגילוי רצון זה מה שלפעמים כך ולפעמים בהיפך הוא בא ונמשך מלמעלה מן הרצון כמו שנובע השכל מלמעלה מן השכל כו' והוא בחי' המקור של כל רצונות הנולדים ומתגלים וכמ\"ש במ\"א ונק' בעל הרצון<sup data-n=\"5281\">*87</sup> כו'. וכך יובן בדוגמא למעלה שיש ב' מדרגות ברצון העליון, הא' בחי' רצון הנגלה בציץ כבר ע\"י מעשה המצות כי רוח אייתי רוח כנ\"ל, והב' בחי' מקור הרצונות",[["5273","80","<b>שאנו אומרים אשר קדשנ\"ו</b>: נוסח ברכת המצות."],["5274","81","<b>קדשנ\"ו. . כדפרש\"י קדושי\"ם תהיו מובדלים</b>: כ\"ה גם (בשם רש\"י) במאמרי אדה\"ז תקס\"ה ח\"א ע' רנב (נוסחא שני'). מאמרי אדה\"א שמות ח\"ב ע' תקצז. ויקרא ח\"ב ע' תקסד (וש\"נ). ראה רש\"י קדושים יט, ב. לעיל פ' וארא נא, ד הערה 10."],["5275","82","<b>לבושים שעליהם. . אור המקיף</b>: ראה גם לעיל פ' בשלח קפ, ג. וש\"נ."],["5276","83","<b>כי תועבת ה' כל גבה לב</b>: משלי טז, ה [בהוספת תיבת כי — וכ\"ה גם בעמה\"מ (שער קרית ארבע) שי\"ד, פצ\"ב (קג, א)]."],["5277","*84","<b>כל מרבה הוא</b>: ראה גם לקמן שעה, א."],["5278","84","<b>אין אני והוא יכולים לדור</b>: סוטה ה, א. ערכין טו, ב."],["5279","85","<b>כי כל למ\"ד מורה ענין ההעלאה למעלה</b>: ראה גם לקמן שסב, ב. שעה, ב. להעיר מ<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830033\" data-slug=\"or-hatorah-hb\" data-id=\"8158830033\">אוה\"ת במדבר ס\"ע לג</a>."],["5280","86","<b>נברך לאלקינו</b>: זהר (רע\"מ) פינחס רמו, א. ז\"ח רות פז, ג ובהנסמן בניצוצי זהר שם. ראה גם לקמן שעה, ב."],["5281","*87","<b>בעל הרצון</b>: ראה גם בענין בעל הרצון לקמן פ' ויקהל תיב, ד. וש\"נ."]]],[2300550335,"כולן והוא הנק' בזהר רעוא דכל רעוין<sup data-n=\"5282\">87</sup> פי' מקור הרצון כי לכל הרצון הנגלה יש לו מקור שמשם הוא נובע ונמשך כנ\"ל. והנה צריך להיו' לזה המקור של כל הרצונות הנק' רעוא דכל רעוין המשכה מיוחד' בפ\"ע והוא נמשך ובא מן ההעלם לגילוי ע\"י שם הוי' ג\"כ כמו שהרצון הנגלה נמשך ע\"י שם הוי' כו', אלא ששם הוי' זה שנמשך על ידו מרעוא דכל רעוין הרי הוא קדוש ומובדל במדרגה הרבה מקדושה זאת דהמשכת הרצון שבמעשה המצות כו'. וזהו ענין ב' שמות הוי' הנא' בי\"ג מדו' הרחמי' כמ\"ש ויעבור ה' כו' ויקרא הוי' הוי'<sup data-n=\"5283\">88</sup> אל רחום כו' ופסיק טעמא בינייהו<sup data-n=\"5284\">89</sup> כו', כי הוי' הא' הוא בעצמו' אוא\"ס דהיינו שיהי' נמשך הרצון לרצון והוא ההארה מרעוא דכל רעוין כו', והוי' הב' להיות אל רחום וחנון וא\"כ הוי' הא' הוא בחי' מקור להוי' הב' והיינו שהוא מהווה כל הויות שבגילוי רצון כו' וד\"ל. וזהו ג\"כ ענין ההוי' שהי' כתוב בציץ מלמעלה שהוא כמו הוי' א' שבי\"ג מדה\"ר והוא להיות נמשך בחי' רעוא דכל רעוין במצח אהרן ע\"י הציץ וכמשי\"ת וע\"כ לא הי' כתוב בלמ\"ד אחר שהוא מהווה כל הויות כו' וזהו קדש למ\"ד מלמטה והוי' מלמעל\"ה וד\"ל.\n<b>וזהו</b> ופתחת עליו פתוחי חותם קדש לה' כו', והי' על מצח אהרן כו' ונשא אהרן עון הקדשים כו'. דהנה מבואר למעלה דיש בענין הציץ ב' תנאים הא' שיעשנו משה והב' שיונח על מצח אהרן דוקא כו', וענין ובחי' אהרן מבואר למעלה שהוא בחי' הרועה לכנס\"י באהבה רבה כו', אך ענין ובחי' מצח אהרן, הנה יובן בהקדים תחלה שיש בחי' ג' חללי גלגלתא<sup data-n=\"5285\">90</sup> והן ג' מוחין הידועים מוח החכ' ומוח הבינה ומוח הדעת באמצע, והציץ הי' מונח באמצע הראש לנגד מוח הדעת<sup data-n=\"5286\">91</sup> כו'. וביאור ענין המוח הדעת הנה ידוע בפי' מוח הדעת שהוא בחי' כח התקשרות<sup data-n=\"5287\">92</sup> המקשר א\"ע לדבר מה והוא מה שתוקע כל עצמותו בדבר ובדעת זה הוא עיקר התלבשות הרצון לפי שבמוח הדעת הוא כח ההרגשה<sup data-n=\"5288\">93</sup> מה שמרגיש א\"ע, כידוע בפי' דעת שהוא מענין הרגשה ג\"כ והרגשת עצמותו הוא מבחי' הרצון כידוע דהרצון שורה ומתפשט בגידי ההרגשה<sup data-n=\"5289\">94</sup> שבכל הגוף כו' (וע\"כ <span data-k=\"pg\">1060</span> ּ בלא מוח הדעת אינו מוליד<sup data-n=\"5290\">95</sup> לפי שהתענוג שברצון הוא בחי' הפנימיות ובלעדו אין לרצון קיום כו' וזהו והאדם יד\"ע<sup data-n=\"5291\">96</sup> כו' לפי שהתקשרות שבדעת הוא עיקר פנימי' הרצון והוא התענוג כו' כמ\"ש במ\"א). והנה פנימי' הרצון ועיקרו שבא ונמשך מן",[["5282","87","<b>רעוא דכל רעוין</b>: ראה זהר (ספרא דצניעותא) תרומה קעו, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670202\" data-slug=\"torat-chaim\" data-id=\"2300670202\">תו\"ח בראשית לו, ג</a> הערה 23."],["5283","88","<b>ויעבור. . ויקרא הוי' הוי'</b>: תשא לד, ו. ראה גם לעיל פ' בשלח קמט, ד. וש\"נ."],["5284","89","<b>ופסיק טעמא בינייהו</b>: ראה זהר (אד\"ר) נשא קלח, רע\"א. לעיל פ' בשלח קנז, ב הערה 361."],["5285","90","<b>ג' חללי גלגלתא</b>: ראה זהר ואתחנן רסב, א. (אד\"ר) נשא קמ, א. וראה גם לעיל פ' שמות כג, ד. וש\"נ."],["5286","91","<b>והציץ הי' מונח באמצע הראש. . הדעת</b>: ראה גם לקמן שעז, ג. וב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370373\" data-slug=\"torah-or\" data-id=\"3901370373\">תו\"א</a> כאן (בהביאור פג, ד) והמצח הוא כנגד מוח הדעת."],["5287","92","<b>הדעת. . התקשרות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא</a> פ\"ג. לעיל פ' בשלח קנה, ג. וש\"נ."],["5288","93","<b>הדעת. . ההרגשה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310051\" data-slug=\"tanya\" data-id=\"3401310051\">תניא</a> ספמ\"ו. לעיל פ' בא קד, ב. וש\"נ."],["5289","94","<b>דהרצון. . בגידי ההרגשה</b>: ראה גם לקמן שעח, א. מאמרי אדה\"א במדבר ח\"א ע' קפו. ח\"ב ס\"ע תקצה ואילך."],["5290","95","<b>בלא מוח הדעת אינו מוליד</b>: ראה יבמות נג, סע\"ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370465\" data-slug=\"torah-or\" data-id=\"3901370465\">תו\"א ויחי קה, סע\"ג</a> ואילך. לעיל פ' בשלח קמה, ב. וש\"נ."],["5291","96","<b>והאדם יד\"ע</b>: בראשית ד, א."]]],[2300550360,"התענוג<sup data-n=\"5292\">97</sup> מתלבש בבחי' מוח הדעת וזהו וידע\"ת היום<sup data-n=\"5293\">98</sup> כו' אתה הראת לדע\"ת<sup data-n=\"5294\">99</sup> כי ה' כו' ושרש נשמת משה הי' ג\"כ מבחי' מוח הדעת<sup data-n=\"5295\">100</sup> שעולה עד בחי' פנימי' הרצון כו'.\n<b>אך</b> הנה ג' חללי המוחין חב\"ד המה טמונים ונכסים כולם תחת עצם הגלגלתא דחפיא עלייהו כידוע דגלגלתא חפיא על מוחא<sup data-n=\"5296\">101</sup> כו', וא\"כ בהכרח לומר שיש כח יותר עליון בגלגלתא גם ממוח הדעת לאחר שמוח הדעת נכסה תחתיו והוא חופה עליו בבחי' מקיף כו'. והענין הוא נראה בחוש הטבע, דהנה אנו רואים בעבודה שבלב זו תפלה<sup data-n=\"5297\">102</sup> בהתבוננו' במוח הדעת עד שמקשר כל עצמותו ותקוע כל שכלו ומדותיו רק לה' לבדו כו', הנה מיד אחר התפלה חולפת ועוברת אותו הרצון שהי' מלובש במוח הדעת כו', אמנם יש אשר נשאר אצלו בחי' רשימו מאותו הרצון שהי' לו בתפלה גם כל היום אחר עסקו במו\"מ בטרדא גדולה והוא הנק' הסכם שכך הוסכם אצלו בתפלה שיהי' הולך אחרי ה' ולדבקה בו כו', וענין הסכמה זאת אינה בבחי' רצון בפנימי' אלא רק בחיצוניות בלבד. והדוגמא מזה אנו מוצאי' שהוא ענין קבלת רצון לרצון כמו בשעת מ\"ת שאמרו נעשה ונשמע<sup data-n=\"5298\">103</sup> ואע\"פ שלא שמעו עדיין ולא הי' להם רצון בפנימי' אלא שקיבלו עליהם להיות כל רצונם במה שירצה ה' כו', וכן ענין קבלת מלכות שמים כו'. וכמו שמבואר במ\"א בענין מעשה דר\"י ור\"ל דר\"ל קביל עלי'<sup data-n=\"5299\">104</sup> כו' שעי\"ז הי' חילו רב לחשק התורה אח\"כ ברצון גמור, וענין קביל עלי' הי' רק קבלה ע\"ע להיות לו רצון לתורה. וזוהי ענין ההסכמה שנשארת אחר התפלה והיא חזקה מאד עד שלא תאבד גם בטרדת העסק, משא\"כ הרצון הנעשה ע\"י מוח הדעת שחולפת ועוברת כו'. וכל זה ההסכם כחו במצח ששם הוא כח ההסכם לעשות רצון לרצון לכך חופה הוא על מוח הדעת בבחי' המקיף כי גדול כחו הרבה ממנו כו' והיות שהוא רק בבחי' חיצוני' לכך המצח ג\"כ בבחי' חיצוני' כו'. ובהיפך בסט\"א כתי' ומצח אשה זונה הי' לך<sup data-n=\"5300\">105</sup> שהוא עקשות ונצחון דעמלק הנ\"ל, לפי שבאוה\"ע נאמר אין דע\"ת אלקי' באר\"ץ<sup data-n=\"5301\">106</sup> שאין להם בחי' הדע\"ת וההתקשרות הנ\"ל בפנימי' הרצון ואדרבה המה לעומת בחי' הדעת דקדושה, כי נק' אומו\"ת העולם מלשון אם<sup data-n=\"5302\">107</sup> שהעולם הם בחי' תולדה שלהם, כי דעתם והתקשרותם העצמי להיות בחי' נפרד דוקא כו' והוא לנגד דעת דקדושה, וזהו קליפת עמלק ואדרבה הי' לו החוצפא כמו בבחי' מצח כו'. וזהו שציוה ה' שיונח על מצ\"ח אהרן דוקא פי' מצח הוא הבחי' ההסכם שעושה הרצון ואע\"פ שהוא בחיצוניות אבל הוא מפני זה בחי' כלי לשכון בו בחי'",[["5292","97","<b>פנימי' הרצון. . ונמשך מן התענוג</b>: ראה גם לעיל פ' בשלח רב, ד. מאמרי אדה\"א דברים ח\"ד ע' א'תעא."],["5293","98","<b>וידע\"ת היום</b>: ואתחנן ד, לט."],["5294","99","<b>אתה הראת לדע\"ת</b>: ואתחנן שם, לה."],["5295","100","<b>ושרש נשמת משה. . מוח הדעת</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא</a> פמ\"ב. לעיל פ' וארא פה, ד הערה 856."],["5296","101","<b>דגלגלתא חפיא על מוחא</b>: ראה זהר (אד\"ר) נשא קכח, ב."],["5297","102","<b>בעבודה שבלב זו תפלה</b>: ראה תענית ב, א. לעיל פ' בשלח קסב, א הערה 13."],["5298","103","<b>שאמרו נעשה ונשמע</b>: משפטים כד, ז."],["5299","104","<b>מעשה דר\"י ור\"ל דר\"ל קביל עלי'</b>: ראה ערכין טז, ב בריב\"נ ור\"ע."],["5300","105","<b>ומצח אשה זונה הי' לך</b>: ירמי' ג, ג."],["5301","106","<b>אין דע\"ת אלקי' באר\"ץ</b>: הושע ד, א [ושם: ואין — ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370373\" data-slug=\"torah-or\" data-id=\"3901370373\">תו\"א כאן פג, ד</a>.]."],["5302","107","<b>אומו\"ת העולם מלשון אם</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370373\" data-slug=\"torah-or\" data-id=\"3901370373\">תו\"א כאן פג, ד</a> ”שהם אומות\" ובהערות ותיקונים לשם (קלז, ב — נראה לי בדרך אפשר) ”אמות (ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ\"ג</a>)\". וראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קצב (בשולי היריעה). ח\"ב ע' תקנה. קצרים ע' קכב. אוה\"ת בלק ע' א'ט."]]],[2300550380,"רעוא דכל רעוין וכמבואר באד\"ר דבמצחא דוקא אתגלי' רעוא דכל רעוין<sup data-n=\"5303\">108</sup> לפי שביכולתו להמשיך הרצון מבעל הרצון כו'.\n<b>וזהו</b> והי' על מצח אהרן ונשא אהרן את <span data-k=\"pg\">תקל</span> ּ עון הקדשים כו' להיות אל רחום כו' נושא עון ועובר על פשע<sup data-n=\"5304\">109</sup> כו' כי בבחי' רעוא דכל רעוין דוקא עובר על פשע כמבואר באד\"ר, והוא מפני שגם חושך לא יחשיך ממנו כו' והזדונות נעשו כזכיות<sup data-n=\"5305\">110</sup> וכמשי\"ת. ואע\"פ שאהר\"ן הי' רועה וזן לכנס\"י באהבה רבה שברצון היינו רק בבחי' התגלות הרצון שהוא רק בבחי' הוי' הב' דאל רחום כו', ואמנם כדי שיהי' מאיר בו מבחי' הוי' הא' שבעצמות אוא\"ס דהיינו מרעוא דכל רעוין וגם נק' סתימו דכל סתימין כו' וכמ\"ש ויקרא הוי' הוי' פי' שקרא להוי' הא' שיאיר בהוי' הב' מן ההעלם לגילוי כנ\"ל הי' זה דוקא ע\"י הציץ שהי' מונח על מצח אהרן, והי' בזה ב' תנאים, א' שעשה משה הציץ שיאיר מרעוא דכל רעוין, והב' שיהי' לו בחי' כלי שיקבל האור והוא בחי' מצח דאהרן מטעם הנ\"ל. והטעם שע\"י מעשה הציץ שעשה משה נמשך האור מבחי' רעוא דכל רעוין הוא לפי שהי' משה מבחי' מוח הדעת שעולה לבחי' פנימי' הכתר, אך הרי מ\"מ ע\"י כלי הדעת בלבד חולפת ועוברת ההארה, אבל במצח אהרן הי' הציץ מרצה בתמידות והיינו דעת ר' יהודה באמרו עודהו על מצחו מרצה<sup data-n=\"5306\">111</sup> כו' וד\"ל.\n<b>והי'</b> על מצחו תמיד לרצון להם לפני ה' כו', להיות מבואר למעלה דעיקר המנגד לקליפת עמלק לשבור החוצפא והעקשות הוא ע\"י הציץ מפני שנגד נצחון דקליפה הוא נצחון ההסכם דקדושה ובה שוכן אור רעוא דכל רעוין כו', והיינו שיוכל להיות גם בהיות האדם טרוד כל היום שיהי' לו רצון כו', וזהו על מצחו תמי\"ד לרצו\"ן, פי' תמיד שלא יופסק אורו כלל וכלל. וזהו מפני שהציץ הי' לרצון להם לפני הוי' פי' לפני הוי' למעלה משם הוי' שבהתגלות הרצון בי\"ג מדו' הרחמי' להיות נושא עון וכו', והיינו לרצון להם להיות רצון לרצון בבחי' מקור כל ההויות שברצון, וזהו לפני הוי' מפני שהוא בחי' הוי' הא' שבי\"ג מדה\"ר דפסיק טעמא בינייהו כנ\"ל והיינו בחי' רעוא דכל רעוין וד\"ל. ועתה יובן המשך כל הפסוקי' יחד ועשית ציץ זהב כו' שהוא להיות מציץ מן החרכים מבחי' רעוא דכל רעוין ע\"י משה דוקא מטעם הנ\"ל שהוא בחי' מ\"ה כו'.",[["5303","108","<b>דבמצחא דוקא אתגלי' רעוא דכל רעוין</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, ב."],["5304","109","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["5305","110","<b>והזדונות נעשו כזכיות</b>: ראה יומא פו, ב. לעיל פ' בא קכג, ג הערה 449."],["5306","111","<b>ר' יהודה. . עודהו על מצחו מרצה</b>: יומא ז, ב."]]],[2300550060,"<b>בעזר\"ה ביאור על התורה ועשית ציץ הנ\"ל</b>\n<b>להבין</b> שרשי הדברים הנ\"ל<sup data-n=\"5307\">1</sup>, הנה להבין שרש ענין הצי\"ץ שהוא לשון זכר<sup data-n=\"5308\">2</sup> כי יש מבחי' זו בנוק' ונק' ציצית<sup data-n=\"5309\">3</sup> כו', להיות ידוע בג' חללי גלגלתא<sup data-n=\"5310\">4</sup> דמוח החכמה היינו הכלי לאור השכל והוא מוח גשמי ממש כידוע בספרי הרפואה וכן מוח הבינה ומוח הדעת אשר באמצע המה כלים גשמי', אך מוח הדעת שבאמצע נק' פנימי' המוחין ומשם נמשך שרש נשמת משה<sup data-n=\"5311\">5</sup> באצי' ולמעלה מאצי' הוא מבחי' דעת דא\"א<sup data-n=\"5312\">6</sup> כו'. ולעומתו ממש הוא קליפה דעמלק דהיינו באחורי מוח הדע\"ת<sup data-n=\"5313\">7</sup> הזה בעורף שנגד המצח ממש, כי המצח עיקרו הוא במקום שנגד מוח הדעת דהיינו באמצעיתו כו' ולנגדו ממש הוא קליפה דעמלק כו'. והמצח הוא מבחי' גלגלתא דא\"א ויש בתיקוני גלגלתא ב' מדרגות, הא' תיקוני הראש עצמו והוא המצח וכיוצא ועוד תיקונין שלמטה ממנו והם כמו תיקוני פיאות הראש מימין ושמאל ותקוני הדיקנא כו' כמשי\"ת שהן ב' הויות דויעבור ה' על פניו<sup data-n=\"5314\">8</sup> וכו'. ולהיות כי בחי' תקוני הגלגלתא עצמו הוא גבוה מאד נעלה ע\"כ נצטוה למשה דוקא שהוא יעשה תיקון זה <span data-k=\"pg\">1062</span> ּ והוא הציץ שעל המצח שבגלגלתא כו', וענין התיקון הזה הוא שיאיר מבחי' רעוא דכל רעוין במצח ע\"י הציץ כמשי\"ת.\n<b>אך</b> תחלה יש להבין מהו שרש ענין בחי' מצח זה כו', דהנה מבואר למעלה דאהרן הוא מז' הרועים<sup data-n=\"5315\">9</sup> כו' שמפרנס לכנס\"י ברעותא דלבא באהבה רבה וזה נמשך מהארת תקוני הדיקנא כמ\"ש כשמן הטוב כו' על זקן אהרן<sup data-n=\"5316\">10</sup> ונק' דיקנא דכהנא רבא<sup data-n=\"5317\">11</sup> כו'. אך אהבה רבה זו אין לה קיום נצחי כל היום אלא חולפת ועוברת כו' מפני קליפת עמלק שמאחורי הדעת הממשיך בחי' השכח\"ה ונק' מחיצה של ברזל<sup data-n=\"5318\">12</sup> משום דכתי' בי' אם תגביה כנשר<sup data-n=\"5319\">13</sup> בבחי' החוצפא כנ\"ל, וכדי לשבור מחיצה זו א\"א כ\"א מה שלעומתו בקדושה האלקי' והוא מבחי' הארת המצחא דאהרן כהנא רבא הנ\"ל להיותו גבוה הרבה מתקוני דיקנא כנ\"ל. וענין בחי' מצח זה הוא ענין ההסכם החזק שנשאר כל היום כו' מפני",[["5307","1","<b>להבין שרשי הדברים הנ\"ל</b>: הנחת כ\"ק אדה\"א מדרוש אביו כ\"ק אדה\"ז משנת תקס\"ו. הנחה אחרת נדפסה ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370373\" data-slug=\"torah-or\" data-id=\"3901370373\">תו\"א פ' תצוה פג, ד</a>. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י."],["5308","2","<b>הצי\"ץ שהוא לשון זכר</b>: לקמן שעז, ב מציין: בלק\"ת. וב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370374\" data-slug=\"torah-or\" data-id=\"3901370374\">תו\"א כאן פד, א</a> מציין: עיין בטעמי מצות להרח\"ו פ' תצוה מצות ציץ כו'. וראה גם זהר (רע\"מ) שלח קעה, רע\"א. פע\"ח (שער הציצית) ש\"ג, פ\"ג. פ\"ה. מאו\"א מערכת ציץ אות יט."],["5309","3","<b>בנוק' ונק' ציצית</b>: ראה זהר שם. ירושלמי ברכות פ\"א, ה\"ב ובפי' יפה מראה שם. פע\"ח שם."],["5310","4","<b>בג' חללי גלגלתא</b>: נסמן לעיל שנח, ב."],["5311","5","<b>הדעת. . נשמת משה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא</a> פמ\"ב. לעיל פ' וארא פה, ד הערה 856."],["5312","6","<b>נשמת משה. . דעת דא\"א</b>: ראה ע\"ח (שער דרושי הצלם) שכ\"ה, דרוש ב כלל יז. בשם זהר בראשית. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670131\" data-slug=\"torat-chaim\" data-id=\"2300670131\">תו\"ח וירא קי, ב</a>. ובהערה 27."],["5313","7","<b>דעמלק דהיינו באחורי מוח הדע\"ת</b>: ראה מק\"מ ר\"פ ויקהל. מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ."],["5314","8","<b>דויעבור ה' על פניו</b>: תשא לד, ו."],["5315","9","<b>מבואר למעלה דאהרן הוא מז' הרועים</b>: שנו, א. וש\"נ."],["5316","10","<b>כשמן הטוב כו' על זקן אהרן</b>: תהלים קלג, ב [בדילוג]."],["5317","11","<b>דיקנא דכהנא רבא</b>: ראה זהר נשא קלב, ב."],["5318","12","<b>מחיצה של ברזל</b>: ראה לעיל שנו, ב. וש\"נ."],["5319","13","<b>אם תגביה כנשר</b>: עובדי' א, ד."]]],[2300550092,"שהוא בחי' כלי לשכון בו מאור רעוא דכל רעוין וכמ\"ש באד\"ר דבמצחא דוקא אתגלי' מבחי' רעוא דכל רעוין<sup data-n=\"5320\">14</sup> וכמו במנחה דשבת<sup data-n=\"5321\">15</sup> באמרינו ואני תפלתי כו' ע\"ת רצו\"ן<sup data-n=\"5322\">16</sup> והוא היכל הרצון דבי' אתגניז משה<sup data-n=\"5323\">17</sup> במנחה דשבת<sup data-n=\"5324\">18</sup> כמבואר בספרי הקבלה. וזהו המנגד לעקשות וניצוח דעמלק וכמ\"ש משה בחר לנ\"ו אנשים וצא הלחם<sup data-n=\"5325\">19</sup> כו' לנו דוקא לפי שהי' שרש נשמת משה מבחי' מ\"ה<sup data-n=\"5326\">20</sup> שמאיר במצחא מפני שנאמר בו כי מן המי\"ם משיתיהו<sup data-n=\"5327\">21</sup> כלומר מבחי' מ\"ה שבחכ' הקדומה והוא מ\"ה החדש דא\"ק שמאיר במצחא<sup data-n=\"5328\">22</sup> כו', ולכך נק' משה מ\"ה ושי\"ן<sup data-n=\"5329\">23</sup> בג' קוין נמשך אח\"כ ממנו והוא מ\"ש תורה צוה לנו מש\"ה<sup data-n=\"5330\">24</sup> כו' כמ\"ש במ\"א וד\"ל, ולמטה הימנו ענין לימוד התורה בבחי' ביטול עצמותו מכל וכל וכמ\"ש לא תחללו<sup data-n=\"5331\">25</sup> כו' ובהיפך האומר אין לי אלא תורה<sup data-n=\"5332\">26</sup> כו' כנ\"ל, ואורייתא מחכמה עילאה נפקת<sup data-n=\"5333\">27</sup> היינו מבחי' חכ' הקדומה וכמ\"ש ואהי' אצלו אמון<sup data-n=\"5334\">28</sup> אצל\"ו דוקא כו' ואח\"כ ירדה ונתלבשה בכל העולמות עד סוף כל המדרגות התחתונות והוא שרש לבחי' החכמה שבכל עולם ועולם עד רגלי י\"ס דעשי'. כי הנה ידוע דתורה שבע\"פ נק' חכמה תתאה<sup data-n=\"5335\">29</sup> בלבד וכמ\"ש בס\"י שיש חכמה בראש וחכמה בסוף<sup data-n=\"5336\">30</sup> כו' וגם היא יורדת ומתלבשת בבי\"ע כידוע דבחי' מל' דאצי' נעשה עתיק לבריאה<sup data-n=\"5337\">31</sup> ותורה שבע\"פ מלכו' קרינן לה<sup data-n=\"5338\">32</sup> כידוע ויורדת עד סוף עולם העשי' דהיינו עד בחי' חכמה שבנוק' דז\"א דעשי' והיא התורה שלנו כידוע וד\"ל. ונמצא שרש התורה שנק' תורת משה הוא מבחי' מ\"ה שבחכמה הקדומה ומאיר תחלה במצחא דאהרן כהנא רבא כו', ואח\"כ נמשך ויורד בג' קוין באצי' ומשם לבי\"ע עד חכמה שבנוק' דעשי'. וזהו ענין הציץ שעשה משה דוקא, והוא לשון זכ\"ר לפי שהוא בחי' משפיע מקור החכמה להיות תורה ציוה לנו משה כו' וכמ\"ש מצי\"ץ מן החרכי\"ם<sup data-n=\"5339\">33</sup> מלמעלה עד למטה מטה, והוא מבחי' תיקוני גלגלתא עצמו שיאיר ויצי\"ץ בו מבחי' מ\"ה דא\"ק כנ\"ל. ולכך הי' מונח במצח אהרן שהוא מתיקוני גלגלתא וכנגד מוח הדעת דוקא כדי שיומשך בתור\"ה שהוא מבחי' הקו האמצעי כידוע. משא\"כ בחי' התפלה שנק' בשם אור חוזר והוא בחי' ההעלאה מלמטה למעלה",[["5320","14","<b>דבמצחא. . אתגלי'. . רעוין</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, ב."],["5321","15","<b>רעוא דכל רעוין. . במנחה דשבת</b>: ראה זהר יתרו פח, ב. (אד\"ר) נשא קכט, ב. (אד\"ז) האזינו רפח, ב. רצג, סע\"א."],["5322","16","<b>ואני תפלתי. . רצו\"ן</b>: תהלים סט, יד."],["5323","17","<b>היכל הרצון. . משה</b>: ראה זהר בראשית מד, ב. (היכלות) פקודי רנג, סע\"ב."],["5324","18","<b>אתגניז משה במנחה דשבת</b>: ראה זהר תרומה קנו, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061373\" data-slug=\"likkutei-sichot\" data-id=\"1300061373\">לקו\"ש שמות (כרך ו) ע' 361</a>."],["5325","19","<b>בחר לנ\"ו אנשים וצא הלחם</b>: בשלח יז, ט."],["5326","20","<b>משה מבחי' מ\"ה</b>: ראה גם לעיל פ' שמות מג, א. וש\"נ."],["5327","21","<b>כי מן המי\"ם משיתיהו</b>: שמות ב, י."],["5328","22","<b>מ\"ה החדש דא\"ק שמאיר במצחא</b>: ראה ע\"ח (שער התיקון) ש\"י, פ\"ב."],["5329","23","<b>משה מ\"ה ושי\"ן</b>: ראה גם מאמרי אדה\"ז על ענינים ע' ס."],["5330","24","<b>תורה צוה לנו מש\"ה</b>: ברכה לג, ד. ראה גם לעיל שנז, א ואילך."],["5331","25","<b>לא תחללו</b>: נסמן לעיל שנז, ב."],["5332","26","<b>האומר אין לי אלא תורה</b>: ראה יבמות קט, ב."],["5333","27","<b>ואורייתא מחכמה עילאה נפקת</b>: נסמן לעיל רסח, ד."],["5334","28","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["5335","29","<b>דתורה שבע\"פ נק' חכמה תתאה</b>: ראה גם לעיל פ' וארא עא, ג. וש\"נ."],["5336","30","<b>וכמ\"ש בס\"י שיש חכמה. . בסוף</b>: כ\"ה גם בביאוה\"ז אמור פא, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תצה. וש\"נ. שמות ח\"ב ע' תנד. וש\"נ. דרושי חתונה ח\"ב ע' תרכ. ראה זהר בראשית כו, ב. (רע\"מ) פינחס רלח, סע\"א. לעיל פ' בא צח, ד הערה 109."],["5337","31","<b>מל' דאצי' נעשה עתיק לבריאה</b>: נסמן לעיל פ' משפטים רעט, ד."],["5338","32","<b>ותורה שבע\"פ מלכו' קרינן לה</b>: ת\"ז בהקדמה (יז, א)."],["5339","33","<b>מצי\"ץ מן החרכי\"ם</b>: שה\"ש ב, ט."]]],[2300550124,"דוקא ע\"כ נק' ציצית לשון נוק' והוא כענין לאסתכלא ביקרא דמלכא<sup data-n=\"5340\">34</sup> שזהו מלמטה למעלה, אבל התורה היא בבחי' אור ישר מלמעלה למטה <span data-k=\"pg\">תקלא</span> ּ לכך נק' ציץ לשון זכר לפי שמשפיע האור, והוא ההסתכלות מלמעלה למטה כמ\"ש עיניו כיונים<sup data-n=\"5341\">35</sup> כו' וכמ\"ש מצי\"ץ מן החרכים וזה נעשה ע\"י משה דוקא מטעם הנ\"ל, וכדי להכניע לקליפת עמלק כי בחי' מ\"ה זה במוח הדעת הוא עיקר המנגד לחוצפא דעמלק שמאחורי הדעת ולכך אמר בחר לנו אנשים לנ\"ו דוקא אותם שהם מבחי' מ\"ה דמשה וכנ\"ל וד\"ל.\n<b>ב</b> ופתחת עליו פתוחי חותם<sup data-n=\"5342\">36</sup> כו'. הנה שרש ענין פתוחי חותם הוא בבחי' יסוד אימא<sup data-n=\"5343\">37</sup> כידוע שה\"ג דמנצפ\"ך<sup data-n=\"5344\">38</sup> דאימא<sup data-n=\"5345\">39</sup> הוא בבחי' פתוח\"י חות\"ם<sup data-n=\"5346\">40</sup> כמ\"ש בספרי הקבלה. וביאור הדברים הנה ציור האותיות הוא באור הבינה<sup data-n=\"5347\">41</sup> דוקא, לפי שאור החכמה הוא למעלה עדיין מהתהוות ציור אותיות כלל מפני שהחכמה היא למעלה מן ההשגה עדיין ואין בה אלא כח היולי בלבד להשכיל המושכל וע\"כ מושלל שם מבחי' אותיות, כי בחי' אותיו\"ת לא שייך אלא בדבר שכבר יש בו השגה ותפיסא בבחי' אורך ורוחב כו'. והיינו דוקא באור הבינה שלפי שמשיג הדבר בהשגה ימצא מזה ג\"כ שרש לאותיות מחשבה וכמ\"ש במ\"א ששרש האותיות שבמחשבה הוא מה\"ג מנצפ\"ך דאימא<sup data-n=\"5348\">42</sup> שהוא הנק' פתוחי חות\"ם, והוא ענין דלי\"ת רבתי דאחד<sup data-n=\"5349\">43</sup> שהוא בחי' קשר של תפילין<sup data-n=\"5350\">44</sup> כו'. והנה אורייתא מחכמה עילאה נפקת כידוע, ואעפ\"כ הרי אנו רואים שנתלבשה התורה בצירופי אותיות דוקא כי בכל פרשה שבתורה נתלבש אור החכמה שבה בצירופי האותיות דוקא עד שיש גם קרי וכתיב וכיוצא. אלא הענין הוא דשניהם אמת דשרש התורה משם מ\"ה דחכמ\"ה כנ\"ל שהוא למעלה מן האותיות אבל ירד ונתצמצם האור בכלי והוא בצירופי אותיות כמו שההשגה שבבינה נמשכת בבחי' יש מאין מכח היולי שבחכמ\"ה כו' דלכך נק' הבינה יש והחכמ\"ה אין וכמ\"ש והחכמה מאין תמצא<sup data-n=\"5351\">45</sup> וכמ\"ש במ\"א וד\"ל. ואמנם אין התלבשות אור א\"ס אלא בחכמ\"ה<sup data-n=\"5352\">46</sup> דוקא, וזהו ענין עוסק בתורה לשמ\"ה<sup data-n=\"5353\">47</sup>, פי' לשם התורה דהיינו להמשיך אור א\"ס בחכמ\"ה שבתורה כו', וכמ\"ש במ\"א. וזהו ופתחת עליו פתוחי חותם, פי' עד\"מ החותם שאדם חותם את שמו אברהם",[["5340","34","<b>לאסתכלא ביקרא דמלכא</b>: נסמן לעיל של, ב."],["5341","35","<b>עיניו כיונים</b>: שה\"ש ה, יב."],["5342","36","<b>ופתחת עליו פתוחי חותם</b>: תצוה כח, לו."],["5343","37","<b>חותם. . יסוד אימא</b>: ראה מאו\"א מערכת חותם אות סח. פע\"ח שבהערה 40. ביאוה\"ז פינחס קיג, ג."],["5344","38","<b>שה\"ג דמנצפ\"ך</b>: ראה שער היחוה\"א ספ\"ד. מאמרי אדה\"א ויקרא ח\"א ע' רלז. וש\"נ. סה\"מ ליקוט ח\"ב ע' מא."],["5345","39","<b>שה\"ג דמנצפ\"ך דאימא</b>: ראה מאמרי אדה\"א דברים ח\"ג ע' א'כג ואילך."],["5346","40","<b>שה\"ג דמנצפ\"ך. . פתוח\"י חות\"ם</b>: ראה מאו\"א מערכת פתוחי חותם אות לז. פע\"ח (שער ספה\"ע) שכ\"ב, פ\"ג. סידור שחרית נג, א. מאמרי אדה\"ז על מארז\"ל ע' שעב וע' שעג."],["5347","41","<b>ציור האותיות. . הבינה</b>: לקו\"ת פ' תצוה [ טעמי המצות להאריז\"ל מצות ציץ]. רמ\"ז ר\"פ ויקרא (ט, סע\"ב). זהר הרקיע ויקהל ריז, ב (ע' קסו). ביאוה\"ז להצ\"צ ח\"א ע' תקנח."],["5348","42","<b>האותיות. . דאימא</b>: ראה גם מאמרי אדה\"א שבהערה 39."],["5349","43","<b>דלי\"ת רבתי דאחד</b>: ראה ד\"ה זה במאמרי אדה\"א דברים ח\"א ע' רפג. וש\"נ."],["5350","44","<b>דלי\"ת. . קשר של תפילין</b>: ראה זהר פינחס רלו, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תסח וש\"נ. שעה\"י קלט, א ובהערה 12."],["5351","45","<b>והחכמה מאין תמצא</b>: איוב כח, יב. ראה גם מאמרי אדה\"א בראשית ע' ב. וש\"נ."],["5352","46","<b>התלבשות אור א\"ס אלא בחכמ\"ה</b>: נסמן לעיל שנז, ב."],["5353","47","<b>עוסק בתורה לשמ\"ה</b>: ראה אבות רפ\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380502\" data-slug=\"likkutei-torah\" data-id=\"4001380502\">לקו\"ת שלח מז, ג</a>. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. לעיל פ' וארא פ, ד. וש\"נ. וראה לקמן שסג, א."]]],[2300550156,"וכיוצא אע\"פ ששמו העצמי שקורין לו אברהם הוא עיקר השם ומה שנחקק אותיו' שמו אברהם בציור הכתב אינו מערך ומהות של שמו העצמי כלל וכלל, מ\"מ חקיקת שמו אברהם הן ממש בדוגמא לקריאת שמו וכאשר חותם שמו כאלו ניתן ונמשך שם משמו העצמי ממש ולא יוכל לחזור בו כאלו אמרו הדבר בשמו כו'. וכך יובן למעלה דהתורה נק' חותמו של הקב\"ה כנ\"ל, אמנם אין זה ערך ויחוס כלל לעצמו' שמו אלא שנחקק שמו באותיות התורה ומפני החקיקה כאילו קורין בשמו העצמי וכמארז\"ל הקורא בתורה קורא בשמותיו<sup data-n=\"5354\">48</sup> כו', וזה נק' פתוחי חותם שהוא רק בבחי' אותיות דאימא אבל בקריאת פתוחי חותם הרי קורין לשמו העצמי ונמשך אור א\"ס ממש בחכמה שבתורה, ומן החכמה נמשך מאין ליש בצירופי אותיו' כנ\"ל. והיינו ופתחת עליו פתוחי חותם פי' משה דוקא לפי שהי' ביכולתו בציץ להאיר מעצמות אור א\"ס שבחכמה דא\"ק ע\"כ נצטוה ג\"כ לפתח בו פתוחי חותם, והוא להביא האור דא\"ס בחכמה שבתורה כענין עוסק בתורה לשמה הנ\"ל בכל אדם מישראל ע\"י פתוחי חותם, והן צירופי אותיות הכלליי' שכוללי' כל התורה והמצו' והן אותיות קדש להוי' כמשי\"ת בעזר\"ה וד\"ל.\n<span data-k=\"pg\">1064</span> ּ<b>קדש</b> למ\"ד מלמטה והוי' מלמעלה<sup data-n=\"5355\">49</sup> כו', הנה כתיב ותורת\"ך בתוך מעי<sup data-n=\"5356\">50</sup> כו', דמשמע שהתורה הוא בחי' אור פנימי כמאכל המתפשט בתוך המעיים ומזין ומפרנס את כל הגוף וזהו ותורתך בתוך מעי ממש וכמ\"ש לכו לחמו בלחמ\"י<sup data-n=\"5357\">51</sup> כו' וכידוע, ועל המצות אנו אומרים אשר קדשנו במצותיו<sup data-n=\"5358\">52</sup> משמע שהן בחי' אורו' מקיפי' כי פי' קד\"ש הוא לעולם בבחי' אור מקיף<sup data-n=\"5359\">53</sup>, והטעם הוא לפי שהתורה הוא בחי' מזון לנפש והמצות בחי' לבושים<sup data-n=\"5360\">54</sup> כמ\"ש בספרי המקובלי' ועל הלבושים דוקא שורה אור המקיף<sup data-n=\"5361\">55</sup> כמ\"ש במ\"א. והנה מה שבאתערותא דלתתא נעשה אתעדל\"ע<sup data-n=\"5362\">56</sup> לעורר בחי' קדש העליון במעשה המצות כענין אשר קדשנו במצוותיו, פי' בבחי' קדש העליון והוא בחי' אור מקיף הכללי דבחי' כתר עליון זהו העולה מלמטה למעלה ולכך נכתב קדש למ\"ד מלמטה והלמ\"ד הן ג' אורו' מקיפי' דכח\"ב<sup data-n=\"5363\">57</sup> כו'. אך יש עוד בחי' קדש למעלה מבחי' קדש זה והוא אשר אין אתעדל\"ת מגיע לשם כלל וכמ\"ש אם",[["5354","48","<b>הקורא בתורה קורא בשמותיו</b>: ראה פתיחת הרמב\"ן עה\"ת. לקמן פ' פקודי תמג, ב. תנג, ג. מאמרי אדה\"א דברים ח\"א ע' קלט. וש\"נ. תו\"ח ח\"ש קלד, ב ובהערה 10."],["5355","49","<b>קדש למ\"ד. . מלמעלה</b>: נסמן לעיל שנו, א."],["5356","50","<b>ותורת\"ך בתוך מעי</b>: תהלים מ, ט."],["5357","51","<b>לכו לחמו בלחמ\"י</b>: משלי ט, ה."],["5358","52","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' לא."],["5359","53","<b>קד\"ש. . אור מקיף</b>: ראה מאמרי אדה\"ז תקס\"ו ע' קז. לעיל פ' תרומה שיז, ב. וש\"נ. ראה גם לקמן פ' פקודי תנ, א."],["5360","54","<b>שהתורה. . מזון לנפש והמצות בחי' לבושים</b>: ראה תניא פ\"ה (ובמ\"מ הגהות והע\"ק שם)."],["5361","55","<b>ועל הלבושים. . אור המקיף</b>: ראה גם לעיל פ' בשלח קפ, ג. וש\"נ."],["5362","56","<b>שבאתערותא דלתתא נעשה אתעדל\"ע</b>: נסמן לעיל פ' יתרו רנט, ב."],["5363","57","<b>והלמ\"ד. . דכח\"ב</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380864\" data-slug=\"likkutei-torah\" data-id=\"4001380864\">לקו\"ת תצא לו, ד</a> [צויין אליו ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370374\" data-slug=\"torah-or\" data-id=\"3901370374\">תו\"א כאן פד, א</a>] ושם: חב\"ד."]]],[2300550188,"צדקת מה תתן לו<sup data-n=\"5364\">58</sup> כו', וביאור ענינו יובן בהקדים תחלה שרש ענין ב' שמות הוי' דויעבור ה' על פניו כו' ופסיק טעמא בינייהו<sup data-n=\"5365\">59</sup> כנ\"ל. דהנה ידוע דשם הוי' בכלל הוא עולם הנאצל<sup data-n=\"5366\">60</sup> היו\"ד בחכמה והה\"א בבינה<sup data-n=\"5367\">61</sup> וי\"ו בז\"א כו', וקוצו של יו\"ד רומז לבחי' כת\"ר<sup data-n=\"5368\">62</sup> דאצי' הכללי והיינו כשעלה ברצונו להאציל שהוא בחי' מקור ושרש הכללי לכל מה שנאצל אח\"כ כו' כידוע, וזהו ענין שם הוי' שבאצי' בכללותו. אך שם הוי' שלפני האצי' היינו בחי' שם הוי' דכתר<sup data-n=\"5369\">63</sup> עצמו, דהנה הכתר עצמו כלול מי\"ס<sup data-n=\"5370\">64</sup> ובחי' כתר וחכמה שבכתר הנק' חכמ' סתימא' דא\"א היינו בחי' קוצו של יו\"ד והיו\"ד, והה\"א בבינה דא\"א כו'. ונמצא הגם דשם הוי' זה מובדל בערך לגמרי משם הוי' שבאצי' כי הרי הוא עדיין לפני עיקר ומקור האצי' מ\"מ הרי הוא כדוגמא לשם הוי' שבאצי', כי כמו שקוצו של יו\"ד בכתר דאצי' כך יש קוצו של יו\"ד בכתר עצמו ונק' כתר שבכתר וכן עד\"ז היו\"ד והה\"א כו', ואדרבה כאשר נמשך שם הוי' דאצי' אינו נמשך רק מבחי' שם הוי' שלפני האצי' דהיינו שנמשך מן ההעלם לגילוי וזהו ויעבור ה' על פניו ויקרא הוי' הוי' פי' ויקרא שקרא להוי' הא' שלפני האצי' שיצא מן ההעלם לגילוי להיות בבחי' שם הוי' באצי'<sup data-n=\"5371\">65</sup> כו' וד\"ל. ואמנם לפ\"ז כללות ענין גילוי ההעלם בקוצו של יו\"ד דהוי' הא' לקוצו של יו\"ד דהוי' הב' היינו מה שנתגלה הרצון העליון מן ההעלם, והענין הוא דכשעלה ברצונו כו' זהו קוצו של יו\"ד דהוי' הב', ומוכרח לומר שהי' רצון קדום בתחלה שיעלה לו רצון זה והוא הנק' רעוא דכל רעוין<sup data-n=\"5372\">66</sup> מקור כל הרצונות כנ\"ל זהו בחי' קוצו של יו\"ד דהוי' הא', והוא הנק' כת\"ר שבכת\"ר כלומר רצון לרצון, וממילא נמשך מקור חכמה לחכמה דאצי' והוא היו\"ד דהוי' הא' שנק' בשם ח\"ס דא\"א כו'. וזהו דאע\"פ דפסיק טעמא בין ב' השמות מפני שאין ערוך ביניהם ואעפ\"כ נמשך מזה לזה כמ\"ש ויקרא כו' מפני שזה שרש לזה ושניהם ענין א' אלא שזה בהעלם וזה בגילוי וד\"ל.\n<b>ובזה</b> יובן ג\"כ מה שנא' בציץ והי' על מצחו תמיד לרצון לפני הוי'<sup data-n=\"5373\">67</sup> דקדק לומר לפני הוי' כלומר לפני שם הוי' דאצי', כי הציץ מעורר בחי' רעוא דכל רעוין כנ\"ל שהוא בחי' <span data-k=\"pg\">תקלב</span> ּ כתר שבגלגלתא דא\"א והמצח הוא רק בחי' כלי שישכון בו אור כת\"ר שבכתר כמ\"ש באד\"ר דביה אתגלי כו' וכנ\"ל, והיינו לרצון לפני הוי' כלומר להיות בחי' רצון לרצון שבהוי' דאצי' וזהו לרצון לפני הוי' וכענין ויקרא הוי' הוי' כנ\"ל וד\"ל. וזהו קדש למ\"ד מלמטה דהיינו בבחי' ג' מקיפים דכח\"ב דאצי' שהוא בחי' שם הוי' הב' הנ\"ל, אבל שם הוי' שכתוב בשטה הראשונה הוא",[["5364","58","<b>אם צדקת מה תתן לו</b>: איוב לה, ז."],["5365","59","<b>דויעבור. . ופסיק טעמא בינייהו</b>: נסמן לעיל שנח, ב."],["5366","60","<b>דשם הוי'. . עולם הנאצל</b>: ראה גם לעיל פ' בא קטו, א."],["5367","61","<b>היו\"ד בחכמה והה\"א בבינה</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["5368","62","<b>וקוצו של יו\"ד. . כת\"ר</b>: ראה זהר ויקרא י, ב. פרדס (שער שם בן ד') שי\"ט, פ\"ב. הנסמן במאמרי אדה\"א קונטרסים ע' תכז."],["5369","63","<b>שם הוי' דכתר</b>: ראה גם לעיל פ' בשלח קמט, ד. וש\"נ."],["5370","64","<b>הכתר עצמו כלול מי\"ס</b>: ראה גם לעיל פ' בא פט, ג. וש\"נ."],["5371","65","<b>ויקרא שקרא להוי' הא'. . להיות. . באצי'</b>: ראה גם לעיל פ' בשלח קמט, ד. וש\"נ."],["5372","66","<b>רעוא דכל רעוין</b>: נסמן לעיל שנח, ב."],["5373","67","<b>והי' על מצחו. . לפני הוי'</b>: תצוה כח, לח."]]],[2300550220,"בחי' שם הוי' הא' שבכתר עצמו, והוא להמשיך רעוא דכל רעוין שהוא בבחי' עצמות המאציל אשר אין העלאת מ\"ן מגיע לשם כמ\"ש אם צדקת כו' כי קמי' כחשיכה כאורה<sup data-n=\"5374\">68</sup> כו' להיותו למעלה מעלה מכל עיקר ההשתל' דאצי' כנ\"ל, וע\"כ הי' כתוב הוי' מלמעלה להיותו למעלה הרבה מקדש למ\"ד שלמטה שנמשך ע\"י המצות כו' וד\"ל. ומה שהי' מונח על המצח תמיד דוקא כמ\"ש והי' על מצחו תמיד כו' הענין הוא לפי שרצון הנגלה יש לו הפסק לפרקים שאינו מאיר כ\"כ, אבל ההארה מבחי' רעוא דכל רעוין להיות שהוא רצון פשוט בתכלית הפשיטות בבחי' א\"ס לכך אין לו הפסק ותמיד הוא מאיר להיות למקור לרצון באצי', וזהו והי' על מצחו תמיד לרצון לפני הוי' כו' ובלעדו אין קיום לרצון לכך בהכרח הי' שיונח בתמידות כו' וד\"ל. ומה שמשה הי' העושה לפי שהי' מבחי' הדעת שבו שוכן בחי' עתיקא<sup data-n=\"5375\">69</sup> שהוא התענוג לרצון וע\"כ ביכולתו להמשיך מרעוא דכל רעוין דהיינו להיות תענוג לרצון ויהי' עי\"ז רצון לרצון כו'. ואמנם במצח אהרן מפני שאין בו אלא חיצוניות הסכם הרצון, הרצון שם הוא בחי' הכלי יותר לשכון בו הרצון שלמעלה מן הטעם והתענוג והוא רצון הפשוט כו', לכך הי' צריך ב' התנאים, א' שיעשנו משה, והב' שיונח על מצח אהרן וכמ\"ש והי' על מצח אהרן<sup data-n=\"5376\">70</sup> ולא על מצח משה כי משה הי' מבחי' הדעת דהיינו מלגי\"ו<sup data-n=\"5377\">71</sup> בבחי' הדעת שהוא פנימיות הרצון וא\"צ לציץ, אבל במצח אהרן שם צריך לציץ שיאיר בו מקור הרצון בתמידות וזה הי' לעומת קליפ' דעמלק מצח אשה זונה<sup data-n=\"5378\">72</sup> כו' וכנ\"ל וד\"ל.\n<b>ונשא</b> אהרן את עון הקדשים<sup data-n=\"5379\">73</sup> כו', הנה מבואר למעלה בענין ב' שמות דהוי' שבי\"ג מכילין דרחמי דהארת שם הוי' הב' להיות אל רחום וחנו\"ן כו' הוא נמשך מאור שם הוי' הא' כו' וא\"כ מובן שהוי' הא' די\"ג מדה\"ר הוא למעלה מעלה מהמשכת י\"ג מדה\"ר עדיין כו'. ושרש הענין כנ\"ל דיש ב' מדריגות בבחי' תיקוני גלגלתא א' בתיקוני הראש עצמו והוא בדרך כלל בבחי' כתר שבכתר וחכמה שבכתר כו', אבל המדרגה הב' הם תיקונים הנמשכים מחכמה שבכתר למטה והשרשים הראשונים הן ב' פאות דימין ושמאל ושיבולת הזקן וכל תקוני הדיקנא הן יותר פרטי' ונק' מזלות דא\"א כמו דאור אבא יונק ממזל השמיני<sup data-n=\"5380\">74</sup> ונוצר וכו', והן י\"ג מדה\"ר אל רחום וחנון כו' עד מזל הי\"ג ונקה, וכללותם אינו אלא שם הוי' הא', והוא שם הוי' שלפני התחלת המשכתן מחכמה שבכתר ואח\"כ יורדי' בדרך פרט וכו', והמה תלוים במעשה התחתונים אם העלאת מ\"ן של מעשה התחתונים עולה כהוגן מעוררי' האר\"ת פני\"ם מי\"ג מכילין",[["5374","68","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["5375","69","<b>הדעת שבו שוכן בחי' עתיקא</b>: ראה תו\"א כאן פד, ב."],["5376","70","<b>והי' על מצח אהרן</b>: תצוה כח, לח."],["5377","71","<b>משה. . מלגי\"ו</b>: ראה ת\"ז תי\"ג (כט, א)."],["5378","72","<b>מצח אשה זונה</b>: ירמי' ג, ג."],["5379","73","<b>ונשא אהרן את עון הקדשים</b>: המשך הכתוב והי' על מצח אהרן — תצוה כח, לח."],["5380","74","<b>דאור אבא יונק ממזל השמיני</b>: ראה זהר (אד\"ז) האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. לעיל פ' שמות לו, א. וש\"נ."]]],[2300550252,"דרחמי ואם לאו כתי' אסתי\"ר פנ\"י<sup data-n=\"5381\">75</sup> כו'. אמנם בחי' הוי' הא' <span data-k=\"pg\">1066</span> ּ שלפני שרש י\"ג מכילין דרחמי אינו תלוי בהעלאת מ\"ן אלא מעצמו יאיר אורו וכמ\"ש ויעבור ה' על פניו למעלה מבחי' הארת הפנים כו', והם ע\"י תיקוני הראש כמו ציץ על המצח וכיוצא, ולכך נאמר בציץ ונשא אהרן את עון הקדשים כו' שהי' הציץ מרצה תמיד על הטומאות מפני שאין העלאת מ\"ן לא מעלה ולא מורדת כלל וכמ\"ש אם צדקת כו' אלא הוא נושא עון ממילא וכמ\"ש ונשא אהרן את עון הקדשים, מפני שנעשו הזדונות כזכיות בהשוואה א' כי קמי' כחשיכה כאורה כו', אלא רק בירידת האור ממנו בי\"ג מדה\"ר אז נק' חנון ורחום להיות נושא עון ועובר על פשע מצד הרחמים כו' כי מ\"מ צריך שיבא האור בבחי' רצון נגלה וכמ\"ש כי רצה ה' את מעשיך<sup data-n=\"5382\">76</sup>, והוא הנק' סליחה שהוא ענין התגלות הרצון דאע\"פ שעבר על רצונו ימחול וירצה לו כו'. וזהו בהכרח להיות ברצון התחתון הנגלה בי\"ג מדה\"ר ואעפ\"כ אין לו קיום רק מבחי' רעוא דכל רעוין כי שם עיקר מקור הסליח\"ה וכמ\"ש כי עמ\"ך הסליח\"ה למען תורא<sup data-n=\"5383\">77</sup> וכמ\"ש במ\"א. והיינו והי' על מצחו תמי\"ד לרצו\"ן להם לפני הוי' אע\"פ שלא יהי' להם העלאת מ\"ן ממעשה המצות וכיוצא מטעם שהוא מרבה לסלוח כו', וזהו בבחי' שם הוי' הא' שבעצמות המאציל דוקא כנ\"ל וד\"ל.",[["5381","75","<b>אסתי\"ר פנ\"י</b>: וילך לא, יח."],["5382","76","<b>כי רצה ה' את מעשיך</b>: קהלת ט, ז [ושם: כבר רצה האלקים]."],["5383","77","<b>כי עמ\"ך הסליח\"ה למען תורא</b>: תהלים קל, ד. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'קב."]]],[2300550061,"<b>בעזר\"ה יום א' דחג הפסח (ביאור שני לדרוש דועשית ציץ זהב טהור כו'), תקס\"ו</b>\n<b>להבין</b> שרשי הדברים<sup data-n=\"5384\">1</sup> הנ\"ל ע\"פ ועשית ציץ זהב טהור<sup data-n=\"5385\">2</sup> כו' והי' על מצח אהרן<sup data-n=\"5386\">3</sup> וכו'. הנה יש להבין תחלה כללות ענין הציץ שעל מצח אהרן וכו' ואח\"כ יתבאר פרטי הענינים הנאמרים בזה. דהנה מבואר באדר\"ז דמצחא דז\"א<sup data-n=\"5387\">4</sup> מתערין מארי דדינים וכ\"ד בתי דינין כו', ובשעתא דאתגליא מצחא דעתיקא בהאי מצחא אתהדר חוורא כתלגא ואקרי עת רצון, ובמנחה דשבתא גלי עתיקא מצחא דילי' וכל אינון דינין אתכפיין כו', ובריש האדר\"ז ובמצחא דעתיקא בי' גלי רצון<sup data-n=\"5388\">5</sup> מרדל\"א דפשיט חד טורנא (תכשיט<sup data-n=\"5389\">6</sup> והוא הציץ) בסימא יאה דאתכלל במצחא ואיהו רעוא דכל רעוין כו' ומתנהרין אנפוהי דז\"א וכולהו ברחמי אשתכח וכל דינין אתכפיין כו' וכן אמר באד\"ר",[["5384","1","<b>להבין שרשי הדברים</b>: הנחת כ\"ק אדה\"א ממאמר אביו כ\"ק אדה\"ז. ונדפס עם הגהות וכו' באוה\"ת תצוה ע' א'תשיז ואילך על ד' פרקים. עוד הערה מכ\"ק אדמו\"ר הצ\"צ על פ\"ה נמצא בבוך 306 ע' שס. ראה עוד ע\"ד המאמר להלן ברשימת הכת\"י."],["5385","2","<b>ועשית ציץ זהב טהור</b>: תצוה כח, לו."],["5386","3","<b>והי' על מצח אהרן</b>: תצוה כח, לח."],["5387","4","<b>באדר\"ז דמצחא דז\"א</b>: ראה זהר האזינו רצג, א (בשינויים)."],["5388","5","<b>ובריש האדר\"ז ובמצחא דעתיקא בי' גלי רצון</b>: ראה זהר שם רפח, ב (בשינויים)."],["5389","6","<b>תכשיט</b>: דרך אמת לאד\"ז שם."]]],[2300550093,"(דקכ\"ט) <b>מצחא</b> דגלגלתא<sup data-n=\"5390\">7</sup> רעוא דרעוין כו' רעותא דז\"א לקבלא האי רעותא דכתי' והי' על מצחו תמיד לרצון<sup data-n=\"5391\">8</sup> כו' עד וד' מאה בתי דינין כולהו משתככין קמי' כו' ותאנא שערא לא קאים בהאי משום דאתגלייא ולא אתכסייא כו' ועוד שם (דקל\"ו ע\"ב) כד נהירין אנפוהי<sup data-n=\"5392\">9</sup> דע\"ק באנפוהי ונהיר להאי מצחא אקרי עת רצון כו' וכולהו דינין אשתככו כו'.\n<b>בהיות</b> ידוע שיש בנפש האדם ב' מיני רצון, הא' נק' רצון העליון והוא אשר אינו נלקח באדם מצד השכל וההתבוננו' אלא הוא רצון שלמעלה מן הטעם כמו ענין המאמר שתוק כך עלה במחשבה<sup data-n=\"5393\">10</sup> כו' כלומר אין טעם לרצון זה<sup data-n=\"5394\">11</sup> כו'. והב' נק' רצון התחתון<sup data-n=\"5395\">12</sup> והוא הרצון אשר נלקח באדם רק מצד השכל והטעם שיש לו למה הוא רוצה בדבר זה, או מצד המדות דהיינו מפני שטבעו נמשך לאהוב אותו הדבר לכך יהי' לו רצון תמיד לאותו הדבר, והכל מפני ענין הלבשה הוא דהיינו שהרצון מלובש בשכל והשכל שמוליד אח\"כ האהבה זהו לבוש שני. והלבושי' של השכל והמדות מלבישים ומסתירים להרצון כאילו נעשה התהוות הרצון רק מן השכל והמדות, ובאמת אינו כן שהרי הרצון הוא העיקר אלא שמתלבש בשכל ומדות ונק' בחי' רעותא דז\"א למעלה, והוא רעותא דלבא למטה באדם <span data-k=\"pg\">תקלג</span> ּ התחתון כו' כידוע. והנה ברצון זה התחתון שמלובש בשכל הנ\"ל אע\"פ שהשכל מלבישו, מ\"מ כשעדיין אור השכל מאיר בו הוא כולו רחמים וחסדים כי אין השכל לבוש מסתיר כלל, אלא במוחי\"ן שבמדות הוא מתגלה להיות הרצון ע\"פ השכל, ואמנם זהו דוקא כשהרצון עולה מיד ששכלו מחייבו להיות לו רצון שאז השכל עדיין בהארתו. אבל יש עוד בחי' רצון והוא אשר גמר בדעתו פ\"א שראוי לאהוב ולרצות דבר מה ואח\"כ נשכח הטעם והשכל לאותו הרצון ולא נשאר רק ההסכם בלבד שהוא הסכמת הרצון שכך נגמר בדעתו ורצונו פ\"א, ועכשיו אינו יודע מאיזה טעם הוא רוצה אלא רק הסכמה בעלמא שכך הוסכם אצלו כנ\"ל הנה זהו הנק' בחי' מצחא דז\"א למעלה, והוא עד\"מ באדם התחתון שהמצח מסתיר הוא על המוחין שבראש ומעלים אותם כו'. וכך הענין בבחי' ההסכם הנ\"ל שנשאר אחר ההתבוננו' כו' שאין השכל מאיר בהסכם זה כלל אלא הוא רק הסכם פשוט בלא טעם והוא מעלים ומסתיר על השכל שיש ברצון זה כמשל המוחין שמונחי' בהסתר תחת המצחא כו'. וכך כל זמן שהשכל מאיר ברצון עדיין לא נק' מצחא אלא בחי' גילוי מוחין כו', אך כשהמוחי\"ן שמתגלה בהרצון מתקצרים ולא",[["5390","7","<b>באד\"ר (דקכ\"ט) מצחא דגלגלתא</b>: ראה זהר נשא שם (בשינויים)."],["5391","8","<b>והי' על מצחו תמיד לרצון</b>: תצוה כח, לח."],["5392","9","<b>שם (דקל\"ו ע\"ב) כד נהירין אנפוהי</b>: ראה שם (בשינויים)."],["5393","10","<b>שתוק כך עלה במחשבה</b>: מנחות כט, ב. ראה גם שעה\"י קכה, א ובהערה 11."],["5394","11","<b>אין טעם לרצון זה</b>: ראה הנסמן באוה\"ת כאן ע' א'תשיח."],["5395","12","<b>רצון העליון. . התחתון</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' שמ. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370395\" data-slug=\"torah-or\" data-id=\"3901370395\">תו\"א ויקהל פז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381319\" data-slug=\"likkutei-torah\" data-id=\"4001381319\">לקו\"ת שה\"ש מז, ד</a> ואילך. לקמן פ' ויקהל תלד, ב."]]],[2300550125,"נשאר גם<sup data-n=\"5396\">13</sup> רק הרשימו כו', אזי נעשה כמו ההסכם בלבד ואותו ההסכם מאיר במצח והוא תוקף הרצון כשמלובש בשכל ומדות הנק' רצה\"ת כו'. ולמעלה נק' זה בשם בחי' מצחא דז\"א וע\"כ כל מארי דינין מתערין במצחא זה, לפי שההסכם הזה להיות שאין בו הארת המוחין כלל רק הסכם, והוא מצומצם וקצר מאד ע\"כ לא יכול לסבול היפך ההסכם אפי' מעט מזעיר, כנראה בחוש שיכעוס האדם ויקצוף מאד כשיעשו דבר שנגד הסכמת רצונו שהוסכם אצלו ואין מועיל שום טעם ואמתלא להמתיק הדבר בשכלו אולי מטעם זה ראוי להיות בהיפוך מהסכמתו אחר שאינו יודע טעם להסכמתו כו'. וה\"ז עד\"מ התינוק שמלא דינין וקפידות וכעס על עשות נגד רצונו כי לא ימצא טעם ושכל לסבול דבר שנגד רצונו מפני צמצום המוחין שלו כידוע, משא\"כ הגדול שדעתו רחבה יסבול הרבה דברים שנגד רצונו כי ימצא מקום בשכלו לסבול גם למה שנגד רצונו, וע\"כ החכמה מקור החסדים כידוע בפי' אבינו אב הרחמן<sup data-n=\"5397\">14</sup> כו' דאור אבא כולו חסדים כו', כי מפני רוחב החכמה לא יתפס<sup data-n=\"5398\">*15</sup> מקום מה שעושין נגד רצונו כו' כי רוחב השכל יסבול הכל וצמצום השכל לא יסבול<sup data-n=\"5399\">15</sup> אפי' כל שהוא כו' וכמ\"ש במ\"א. וכך בענין ההסכם הנ\"ל אחר שהמוחין מצומצמים בו מאד כנ\"ל לא יוכל לסבול אפי' כל שהוא וכנגד ההסכם כו'. וזהו שבמצחא דז\"א למעלה מתערין ד' מאה בתי דינין לעוברי רצונו כו', משא\"כ בהארת המוחין ברצון דז\"א ממוחי\"ן דאו\"א שמתחלק לד' מוחין בז\"א כולם רחמים וחסדים כי <span data-k=\"pg\">1068</span> ּ לפי שכל\"ו יהולל איש<sup data-n=\"5400\">16</sup> היינו בחי' מוחין דגדלות ז\"א מפני שהרוחב של השכל המאיר במדות ממתיק כל הדינין כנ\"ל, אך כשמתעלמים המוחין תחת בחי' מצחא שהוא ההסכם בלבד אזי מתערין כל ד' מאה בתי דינין כו' כמבואר באד\"ר ובאדר\"ז הנ\"ל וד\"ל.\n<b>ב</b> והנה מאחר שיש ב' מיני רצון כנ\"ל והוא מ\"ש בזהר דאית רצון ואית רצון<sup data-n=\"5401\">17</sup> כו', וא\"כ גם בבחי' רצון העליון הנ\"ל שלמעלה מן השכל והטעם לגמרי כו' יש ככל דוגמא זאת הנז' ברצון התחתון, דהיינו שגם בו יש בחי' המוחין ומדות שמלובש בהן וגם בחי' מצחא דחופף ומעלים על בחי' המוחין<sup data-n=\"5402\">18</sup> באופן הנ\"ל ברצון התחתון כו'. וביאור הדברים, הנה ידוע דיש בחי' מדות גם ברצון העליון הנ\"ל ונק' טורי חשוכא<sup data-n=\"5403\">19</sup> וכמ\"ש ישת חש\"ך סתר\"ו<sup data-n=\"5404\">20</sup>, משא\"כ במדות שלמטה מן החכמה נק' טורי",[["5396","13","<b>גם</b>: בתחלה נכתב: מהם, ומחקו וממעל למחיקה כתב תיבת גם."],["5397","14","<b>החכמה. . אבינו אב הרחמן</b>: ברכת ק\"ש דשחרית. ראה סידור שער התפילין ט, סע\"ד. מאמרי אדה\"א הנחות תקע\"ז ע' כח. וש\"נ."],["5398","*15","<b>יתפס</b>: כ\"ה בגוכתי\"ק."],["5399","15","<b>רוחב השכל יסבול. . לא יסבול</b>: ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' קצה. ע' קצו ואילך. ענינים ע' פו. לעיל פ' יתרו רעג, ד."],["5400","16","<b>לפי שכל\"ו יהולל איש</b>: משלי יב, ח."],["5401","17","<b>דאית רצון ואית רצון</b>: ראה זהר (אד\"ר) נשא קכט, א: מצחא דאקרי רצון. לעיל פ' בשלח קצט, א הערה 774."],["5402","18","<b>ומעלים על בחי' המוחין</b>: ראה אוה\"ת כאן ע' א'תשכא."],["5403","19","<b>טורי חשוכא</b>: ראה אוה\"ת כאן ע' א'תשכא. להלן הערה 21."],["5404","20","<b>ישת חש\"ך סתר\"ו</b>: תהלים יח, יב."]]],[2300550157,"נהורא<sup data-n=\"5405\">21</sup> כו', ולמדות הללו יש בחי' מוחין חב\"ד ונק' חב\"ד דא\"א, חכמ' דא\"א נק' חכמ' סתימא' דא\"א כו'. וביאור ענין טורי חשוכא ידוע שהוא בחי' אהבה רבה שלמעלה מן הטעם שמתפשטת בבלתי הגבלה וכיוצא, והטעם הוא לפי שהעלם הכח של הרצון הוא בלתי מוגבל מצד עצמו כידוע לכך כל כחות שיש בו ג\"כ המה מתפשטים בלתי גבול וכמו המדות חו\"ג אוי\"ר וכיוצא שהם בבחי' זה הרצון נק' יד הגדולה ויד החזקה כידוע ולכך נק' טורי חשוכא<sup data-n=\"5406\">22</sup> ע\"ש ההעלם העצמות של כח הרצון וכמ\"ש ישת חשך סתר\"ו וכמ\"ש במ\"א. וא\"כ גם בחי' המקור המוליד חו\"ג שברצון המה ג\"כ בבחי' כח ההעלם של הרצון, והוא ג' מוחין שיש ברצון ונק' חב\"ד דא\"א מוח חכמה ונק' ח\"ס דא\"א וכמאמר חכים ולא בחכמ' ידיע'<sup data-n=\"5407\">23</sup> וכן מבין ולא בבינה ידיע' אלא כולם סתומי' בהעלם הרצון, ומבואר במ\"א שחכמה סתימא' דא\"א נק' טעם כמוס לרצון<sup data-n=\"5408\">24</sup> כי אע\"פ שאין טעם נגלה לרצון כנ\"ל מפני שהרצון למעלה מן הטעם והשכל הנגלה, אבל מ\"מ יש טעם כמוס לרצון שמאותו הטעם והשכל הכמוס ונעלם ירצה כו'. וא\"כ גם במוחין דא\"א מלובש הרצון דהיינו שמתלבש בשכל וטעם<sup data-n=\"5409\">25</sup> נעלם עכ\"פ ויהי' איך שיהי' אין זה עצמיות הרצון אלא לבוש, אמנם לא הרצון הנגלה מתלבש בשכל הנעלם הנק' ח\"ס, אלא כח הרצון והוא ענין הרצון לרצון דהיינו להיות לו רצון לזה והוא הנק' רעוא דכל רעוין והוא ענין המקור שממנו נולדו ונמשכו כל הרצונות וכו' וכמ\"ש במ\"א והוא אשר מתלבש בח\"ס ובמדות שבאים ונמשכי' ממוחין חב\"ד דא\"א כו' ע\"ד המבואר בבחי' רצון התחתון הנ\"ל וד\"ל.\n<b>ג</b> והנה מבואר בפרד\"ס<sup data-n=\"5410\">26</sup> בשער הנתיבות בשם קבלת הגאונים ז\"ל דבמוחין דז\"א יש ל\"ב נתיבות חכמה<sup data-n=\"5411\">27</sup> והטעם לפי שהדעת נחלק לב' חו\"ג ונעשים ד' מוחין חו\"ב חו\"ג וכל א' נחלק לשמונה חלקי' וד\"פ ח' הרי ל\"ב<sup data-n=\"5412\">28</sup> והן בחי' ל\"ב שבילין דמתפתחין במוחי' דז\"א<sup data-n=\"5413\">29</sup> כו' שנזכר באד\"ר ואדר\"ז ע\"ש. וביאור ענין הל\"ב נתיבות הללו מבואר במ\"א שהן החדרים הקטנים שבמוח שמתחלקי' לל\"ב בפרט וכללותם ד' חדרים גדולים והן ד' מוחין חו\"ב וחו\"ג וענפיהן מכל א' מתחלק ח' חדרים והכל ע\"י הקרומו'<sup data-n=\"5414\">30</sup> שמפסיק בין כאו\"א כו' כמ\"ש ובדע\"ת חדרי\"ם ימלאו\"ן<sup data-n=\"5415\">31</sup> שמפני הדעת שמתחלק לשנים נתמלא כל החדרים הללו בפרט כו' <span data-k=\"pg\">תקלד</span> ּ ע\"ש. ומזה יובן למשכיל למעלה דכל מה שיש",[["5405","21","<b>טורי חשוכא. . נהורא</b>: ראה זהר פינחס רמט, ב. הנסמן לקמן פ' פקודי תנא, א."],["5406","22","<b>ולכך נק' טורי חשוכא</b>: ראה גם מאמרי אדה\"ז על מארז\"ל ע' כב."],["5407","23","<b>חכים ולא בחכמ' ידיע'</b>: ת\"ז בהקדמה (יז, ב)."],["5408","24","<b>שחכמה סתימא'. . טעם כמוס לרצון</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380510\" data-slug=\"likkutei-torah\" data-id=\"4001380510\">לקו\"ת שלח מט, ג</a>. מאמרי אדה\"א דברים ח\"ד ע' א'שצב. וש\"נ."],["5409","25","<b>הרצון. . שמתלבש בשכל וטעם</b>: ראה אוה\"ת כאן ע' א'תשכב."],["5410","26","<b>בפרד\"ס</b>: כ\"ה בכ\"מ בהנחות ודרושי כ\"ק אדה\"א. ראה גם לעיל פ' בא צ, א. וש\"נ."],["5411","27","<b>בפרד\"ס בשער הנתיבות בשם קבלת הגאונים. . ל\"ב נתיבות חכמה</b>: שם פ\"ב (הגאונים שמו להם שמות כפי אשר קבלו בפעולתם. ֿ. עד הנה הגיע מה שנמצא בביאור הנתיבות בדברי הגאונים). וראה גם לעיל שנד, ב הערה 509."],["5412","28","<b>שהדעת. . הרי ל\"ב</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רמא ואילך. ולהעיר ממאמרי אדה\"ז תקס\"ז ע' תיח ואילך."],["5413","29","<b>ל\"ב שבילין דמתפתחין במוחי' דז\"א</b>: ראה זהר (אד\"ר) נשא קכח, ב. קלו, א."],["5414","30","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080056\" data-slug=\"or-hatorah-hb\" data-id=\"8160080056\">והכל ע\"י</a> הקרומו'</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560060\" data-slug=\"or-hatorah-hb\" data-id=\"8316560060\">אוה\"ת ויקרא (כרך א</a>) ע' נו. בראשית (כרך ג) תצו, ב."],["5415","31","<b>ובדע\"ת חדרי\"ם ימלאו\"ן</b>: משלי כד, ד [ושם: ימלאו — ראה גם הנסמן לעיל פ' שמות מב, א]."]]],[2300550189,"למטה בז\"א בהכרח שיהי' לזה שרש ומקור בהעלם הכת\"ר והיינו בבחי' חב\"ד דא\"א, שהרי ידוע דכל אורות דאצי' נאצלו רק מבחי' ההעלם של הכת\"ר מאין ליש וכמ\"ש והחכמה מאי\"ן תמצא<sup data-n=\"5416\">32</sup> מאין דכת\"ר כו' וכמא' דאור אבא ממזל הח'<sup data-n=\"5417\">33</sup> מזל ונוצר ובי' אחיד אור אבא ותליא כו' ומוח הבינה דאצי' במזל הי\"ג ונקה כו', אלא שנאצלו ונמשכו משם דרך צמצומי' גדולים והיינו דרך בחי' שערות כמשי\"ת בסמוך. אבל א\"א שיהי' מציאות אור באצי' מבלתי שקדם לבוא תחלה בהעלם במקור העצמי והוא הרצון, ומשם נמשך השרש ומקור לזה עד דבז\"א הוא שמתפתחין ל\"ב שבילין ממש בבחי' הגילוי כו'. ושרש מקור לההבדלה הזאת בהעלם המוחין דא\"א הוא הנק' קרומא דאוירא<sup data-n=\"5418\">34</sup> (והוא קרום העליון הדבוק לגלגלת כו', משא\"כ קרום התחתון דמחפיא על מוחא<sup data-n=\"5419\">*35</sup> כו' והוא שמפסיק בחדרים הנ\"ל כו'). והנה רצון העליון הנ\"ל הנק' רעוא דכל רעוין הוא מתלבש במוחי' חב\"ד דא\"א הנ\"ל ובכל פרטיהן, וגם שם יש כל אופן הנ\"ל ברצון התחתון והוא שכאשר המקור של הרצון הזה עולה מיד אחר הטעם הכמוס שהוא ענין כאשר עלה ברצונו הפשוט כו' עדיין אור ח\"ס מאיר בו וכו', ויש בחי' גילוי מקור הרצון הזה שמתגלה אחר העלם והסתר המוחין חב\"ד דא\"א והוא הנק' הסכם ג\"כ, אלא שנק' הסכם מקור כל הרצונות כענין המאמר שתוק כך עלה במחשבה לפני כלומר כך עלה במח' ברצון הפשוט והוא מלובש בטעם הכמוס כנ\"ל, אך כעת נתעלם הטעם הכמוס ואין כאן אלא הסכם בלבד שכך הוסכם להיות הרצון כך, וגם טעם הכמוס אינו מאיר והוא הנק' בחי' מצחא דא\"א דחפיא על המוחי' דא\"א דהיינו מפני שבהסכם זה במקור הרצון נתעלמו כנ\"ל בבחי' רצון התחתון וד\"ל.\n<b>ואמנם</b> מה שמבואר למעלה באד\"ר ואדר\"ז דבמצחא דע\"ק גלי רצון מרדל\"א כו' דמשמע דיותר מתגלה רעוא דכל רעוין במצחא מבמוחין דא\"א וכמבואר שם בהדיא שערא לא קאים בהאי אתר משום דמתגליא ולא מתכסיא כו'. הענין הוא כך להיות שאע\"פ שחו\"ב דא\"א מאיר בהם הרצון הפשוט בודאי יותר בהתרחבות מטעם הנ\"ל, אבל בירידת אור ושפע מהם למטה אינו מאיר ובא רק דרך צמצום גדול והם בחי' י\"ג ת\"ד<sup data-n=\"5420\">35</sup> דא\"א שמאירים למטה רק מהמשכו' בחי' מותרות דמוחי' חב\"ד דא\"א, וכנראה בחוש שאין בצמיחת שערה<sup data-n=\"5421\">36</sup> רק כח והבל בעלמא ויניקתו רק מבחי' כח הצומח שבמוחין דמה שיש בהם כח הצומח להצמיח שערות הוא רק בחי' עשי' שבהם כצמיחת",[["5416","32","<b>והחכמה מאי\"ן תמצא</b>: איוב כח, יב. ראה הנסמן לעיל קא, ג."],["5417","33","<b>דאור אבא ממזל הח'</b>: ראה זהר (אד\"ז) האזינו רפט, ב. ע\"ח שער הכללים פ\"ה. לעיל פ' שמות לו, א. וש\"נ."],["5418","34","<b>קרומא דאוירא</b>: ראה זהר (אד\"ר) נשא קכח, ב. מאמרי אדה\"א בראשית ע' ח. וש\"נ. לעיל פ' בשלח קצ, ג. לקמן שעז, ג. אוה\"ת כאן ע' א'תשכג."],["5419","*35","<b>קרום. . דמחפיא על מוחא</b>: ראה זהר שם."],["5420","35","<b>י\"ג ת\"ד</b>: זהר (ספרא דצניעותא) תרומה קעז, א. ב."],["5421","36","<b>בצמיחת שערה</b>: ראה גם מאמרי אדה\"ז תקע\"א ע' קעב ואילך. תו\"ח ח\"ש קכג, סע\"ג ואילך."]]],[2300550221,"האילן הדומם<sup data-n=\"5422\">37</sup> בערך כח השכלי כו' וכמ\"ש במ\"א. וכך נמשך כח ומקור לאור אבא דאצי' מח\"ס דא\"א רק מבחי' המזל שבו והוא ונוצ\"ר חסד שבי\"ג תקוני דיקנא, ומזל לשון צמיחה הוא כענין מזל מכה ומגדל<sup data-n=\"5423\">38</sup> כו'. ואע\"פ שבהכרח לומר שיש בצמיחת שערות הללו בדיקנא מעין ודוגמא מבחי' החכמ' הסתומ', שהרי לא יצמחו שערות הזקן אלא בהיותו בן עשרים שנה<sup data-n=\"5424\">39</sup> שנשלמו המוחין שלו<sup data-n=\"5425\">40</sup> ולא קודם כי כל זמן שמזקין תרבה ותגדל החכמה ביותר כו' כמ\"ש בישישים חכמה<sup data-n=\"5426\">41</sup> כו', מ\"מ צמצום גדול <span data-k=\"pg\">1070</span> ּ הוא לגבי עצם כח החכ' ואין ערוך כלל ביניהם כידוע ועד\"ז כל פרטי הי\"ג תקוני' דדיקנא הכל באי' מבחי' שערות וצמצומי' מח\"ס דא\"א, אבל במצחא דא\"א מאיר האור בבחי' גילוי ממש כמו שהוא מבלתי צמצום והתלבשות בשערות כלל. וזהו שאמר דשערא לא קאים בהאי אתר כו' שהוא מקום פנוי מבחי' השערות דאע\"פ שאינו אלא הסכם בעלמא מבלתי טעם, אבל אותו ההסכם כל אור הרצון הפשוט נגלה גם למטה מטה ולא כמו בח\"ס שמתלבש בירידתו להאיר בנאצלי' כו' וד\"ל. ולהיות כי הסכם זה מבחי' רעוא דכל רעוין בא ומאיר ע\"כ אמר דבמצחא דא\"א גלי רצון דילי' דוקא מפני שיש בו יותר גילוי מבמוחין מטעם הנ\"ל, אך מ\"מ יש יתרון מעלה במוחין דא\"א מבמצחא על היות שהם בחי' המוחין שהם בחי' הפנימיות כמ\"ש חכמת אדם תאיר פניו<sup data-n=\"5427\">42</sup> מפני שהוא בחי' הפנימיות, והגם שהכח הנשפע מהם דרך השערות הוא ע\"י צמצום, אבל הוא בא ממקור וכח היותר פנימי משא\"כ במצחא שהוא בחי' חיצוניות כלי בלבד כעצם הראש שאינו אלא עצם כשאר עצמות הראש, אך שבו ישכון ויתגלה אור הרצון הפשוט כמו שיתגלה כח הראי' בכלי העין וכיוצא וכמ\"ש במ\"א, אבל בזאת יתרון מעלתו שהגילוי בו יותר כנ\"ל וד\"ל. וזהו הטעם שנראה בציור האדם שהמצח גבוה מן הזקן לפי שהזקן נמשך ממותרי מוחין שבראש והמצח הוא בחי' כלי לגילוי אור הרצון הפשוט הנק' רעוא דכל רעוין כנ\"ל וד\"ל.\n<b>ד</b><sup data-n=\"5428\">*43</sup> וזהו והי' על מצח אהרן כו' והי' על מצחו תמיד לרצון לפני הוי' כו', דהנה בחי' אהרן כהנא רבא הוא בחי' ז\"א כי הי' בעל שמונה בגדים<sup data-n=\"5429\">43</sup> וכו' וכל התיקונין שלו היו מבחי' א\"א וכמ\"ש כשמן הטוב היורד על הראש יורד על הזק\"ן זק\"ן אהר\"ן<sup data-n=\"5430\">44</sup> כו' והם מי\"ג תקוני' דא\"א שנמשכו והאירו בז\"א<sup data-n=\"5431\">45</sup> כידוע בספרי הקבלה. והנה הציץ שבמצח אהרן הי' שרשו כדי לחבר למעלה אסתכלותא דמצחא דא\"א במצחא דז\"א<sup data-n=\"5432\">46</sup>, כמבואר",[["5422","37","<b>האילן הדומם</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרעו וע' תרפא. לקו\"ת חוקת נז, ד."],["5423","38","<b>מזל מכה ומגדל</b>: ראה ב\"ר פ\"י, ו. לעיל פ' וארא ס, ב הערה 34."],["5424","39","<b>יצמחו שערות הזקן. . בן עשרים שנה</b>: ראה שו\"ע אדה\"ז הל' ברכות השחר סנ\"ג, סי\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380695\" data-slug=\"likkutei-torah\" data-id=\"4001380695\">לקו\"ת מסעי צב, ד</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תפח. וש\"נ. בראשית ע' רנד."],["5425","40","<b>בן עשרים שנה שנשלמו המוחין שלו</b>: ראה גם לעיל פ' תרומה שה, ב. וש\"נ."],["5426","41","<b>בישישים חכמה</b>: איוב יב, יב."],["5427","42","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["5428","*43","<b>ד</b>: אולי כאן צ\"ל פ\"ד."],["5429","43","<b>אהרן. . ז\"א. . שמונה בגדים</b>: ראה אוה\"ת כאן ע' א'תשכד."],["5430","44","<b>כשמן הטוב. . זק\"ן אהר\"ן</b>: תהלים קלג, ב [ושם: כשמן הטוב על הראש ירד על הזקן]."],["5431","45","<b>מי\"ג תקוני' דא\"א. . בז\"א</b>: ראה פע\"ח (שער הסליחות) שי\"ב, פ\"ח (למורינו האר\"י)."],["5432","46","<b>אסתכלותא דמצחא דא\"א במצחא דז\"א</b>: ראה זהר (אד\"ר) נשא קכח, ב. קלו, ב. פלח הרמון — לר\"ה מפאריטש — שמות ע' שסב בהערה."]]],[2300550253,"באד\"ר ואד\"ז דמצחא דז\"א מתערי' כ\"ד בתי דינין כו' ובשעתא דאתגליא מצחא דע\"ק בהאי מצחא כו' אקרי עת רצון וכל דינין דבז\"א אשתככו כו' וכל רעותא דז\"א לקבלא האי רעותא כו' שהוא גילוי האור מבחי' רעוא דכל רעוין שמאיר במצחא דע\"ק דוקא. כי הנה בחי' מצח אהרן הוא בחי' מצחא דז\"א שהוא בחי' ההסכם שנשאר אחר ההתבוננו' שבהעלם המוחין דז\"א נתעוררו הדינין יותר כנ\"ל הטעם, אמנם אמר דבהארת בחי' מצחא דע\"ק בהאי מצחא אשתככו' כו', לפי שבחי' ההסכם מרצון הפשוט אע\"פ שאינו אלא הסכם בעלמא אבל הוא בחי' גילוי רעוא דכל רעוין מבחי' מקור כל הרצונות מקורא דכולא, ובמקורא דכולא אע\"פ שמצחא זה דע\"ק הוא בהתעלמות החכ' הנק' ח\"ס מ\"מ אורו גדול מאד להיותו בא מבחי' מקור כל הרצונות כו'<sup data-n=\"5433\">47</sup>. ומה גם שיש בו יתרון מעלה מצד שהוא פנוי מן השערות והוא מאיר ובא בבחי' גילוי אור יותר מבמוחין דא\"א כנ\"ל<sup data-n=\"5434\">48</sup> וע\"כ גם בירידת אור זה ממצחא דע\"ק באסתכלותא שמסתכל גם במצחא דז\"א שמלא דינין כל הדינין נמתקין ואשתככו, כי מאיר שם בבחי' גילוי כמו שהוא כענין הנראה בחוש בצהבת <span data-k=\"pg\">תקלה</span> ּ הפנים כשמאירי', כענין צהבו פניו של רבי<sup data-n=\"5435\">49</sup> וכיוצא שאור זה מאיר כמו שהוא מבלתי התעלמות בלבושי', משא\"כ בהמשכת י\"ג ת\"ד דא\"א לז\"א בזק\"ן אהרן הגם שהם ממתיקי' הדינין ג\"כ באד\"ר ואדר\"ז מ\"מ אין ההמתקה כ\"כ כמו בהארת ואסתכלותא דמצחא דע\"ק במצחא דז\"א, וכמבואר בע\"ח דש\"ע נהורין מאירים מאסתכלותא זאת וק\"נ נהורין<sup data-n=\"5436\">50</sup> מקבלים או\"א וכמ\"ש כי יקרא ק\"ן צפו\"ר<sup data-n=\"5437\">51</sup> כו' וכללותם הוא תר\"ך עמודי אור<sup data-n=\"5438\">52</sup> כו', אבל עיקר האור מבחי' המצח בא בפנים<sup data-n=\"5439\">53</sup> ובפנים מתחלק לתרין תפוחין כו'. ולזה הטעם הי' כל עיקר ענין הציץ שהוא הארת ואסתכלו' מצחא דע\"ק במצח אהרן מבלתי התעלמות בלבושים וצמצומי' ולכך הי' על מצח אהרן תמיד לרצון, פי' להאיר שם מרעוא דכל רעוין שהוא מאיר בציץ, כי פי' ציץ מלשון יציץ נזרו<sup data-n=\"5440\">54</sup> וכן מציץ מן החרכים<sup data-n=\"5441\">55</sup> כמבואר שם והוא בחי' גילוי אור רצון הפשוט שבמצחא דע\"ק. ובכל זה מובן לשונות המאמרי' הנ\"ל באד\"ר ואדר\"ז כו' וד\"ל. ומ\"ש והי' על מצחו תמיד לרצון לפני הוי' ומבואר שם לפני הוי' דאצי' כו', הענין מבואר ע\"פ הנ\"ל דהנה שם הוי' שבעצמות המאציל הוא בחי' המוחין דא\"א יו\"ד בח\"ס וה\"א בבינה דא\"א, ומה שנאצלו האורות באצי' ג\"כ ע\"י שמות דהוי' יו\"ד באור אבא כו' הוא בחי' הוי' דאצי' ואין ערוך כלל ביניהם מפני שנמשכו האורות מא\"א בבחי' השערות וצמצום כנ\"ל, ע\"כ אמר בי\"ג מדה\"ר ויקרא הוי' הוי' ב\"פ ופסיק טעמא בינייהו<sup data-n=\"5442\">56</sup> לפי שאין ערוך כלל ביניהם אך שנק' אור ונמשך מן ההעלם לגילוי ע\"י צמצום וזהו ויקרא ה' ה' כו' כמבואר שם",[["5433","47","<b>מקור כל הרצונות כו'</b>: ראה אוה\"ת כאן ע' א'תשכה."],["5434","48","<b>מבמוחין דא\"א כנ\"ל</b>: ראה אוה\"ת כאן."],["5435","49","<b>צהבו פניו של רבי</b>: חולין ז, ב."],["5436","50","<b>בע\"ח דש\"ע נהורין. . וק\"נ נהורין</b>: ראה שם (שער א\"א) שי\"ג, פי\"ד."],["5437","51","<b>כי יקרא ק\"ן צפו\"ר</b>: תצא כב, ו. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370218\" data-slug=\"torah-or\" data-id=\"3901370218\">תו\"א ויחי מח, ב</a>. מאמרי אדה\"ז תקס\"ה ח\"א ע' קעה."],["5438","52","<b>תר\"ך עמודי אור</b>: ראה גם לעיל פ' שמות ח, א. וש\"נ."],["5439","53","<b>עיקר האור מבחי' המצח בא בפנים</b>: ראה אוה\"ת כאן ע' א'תשכו."],["5440","54","<b>יציץ נזרו</b>: תהלים קלב, יח."],["5441","55","<b>מציץ מן החרכים</b>: שה\"ש ב, ט."],["5442","56","<b>ויקרא. . ופסיק טעמא בינייהו</b>: תשא לד, ו. ראה זהר (אד\"ר) נשא קלח, רע\"א. לעיל פ' בשלח קנז, ב הערה 361."]]],[2300550283,"באריכות וד\"ל, וזהו והי' על מצחו תמיד לרצון לפני הוי' דאצי' ע\"י המשכת האור מהוי' שלפני האצי' בי\"ג תקוני דיקנא כנ\"ל וד\"ל.\n<b>ה</b> והנה אם הי' כוונת הכתוב באמרו והי' על מצחו תמיד לרצון כו' רק לענין המשכת י\"ג מדה\"ר בלבד בי\"ג תקוני דיקנא דא\"א כו' לזאת לא הי' צריך לתקן הציץ דוקא על מצחו כו', כי הרי י\"ג מדה\"ר נמשכי' בכל יוה\"כ וגם מעין ודוגמא של הארתם ביו\"כ מאירים בכל יום ע\"י ברכת כהנים קצת באמרם יאר ה' פניו אליך<sup data-n=\"5443\">57</sup> כו'. אך עיקר הענין של הציץ הי' להיות מאיר בחי' מקור ושרש לי\"ג מדה\"ר בתמידות והוא מ\"ש והי' על מצחו תמיד לרצון כו'. וביאור הדברים הנה יובן בהקדים תחלה ענין מעשה הכתב שהי' כתוב על הציץ קדש למ\"ד מלמטה והוי' מלמעלה<sup data-n=\"5444\">58</sup> כידוע, דהנה לכאורה ע\"ד הפשט יש להבין למה הי' נכתב קדש למ\"ד מלמטה והוי' מלמעלה שאין בזה שום משמעות ענין כלל שהוא פשט הענין דתיבות הללו קדש להוי' הוא שהקד\"ש נמשך לשם הוי' וא\"כ הי' ראוי שיכתב דוקא בשיטה אחת קדש לה' והי' כך משמעות הענין, אבל עכשיו שכתוב קדש למ\"ד למטה בשיטה בפ\"ע אין לזה משמעות כלל וכלל. אך הענין הוא דבאמת אם יהא הכוונה שהי' הקדש נמשך לשם הוי' הי' מהראוי שיהא נכתב בשיטה אחת, אבל הכוונה הוא בהיפוך ששם הוי' יומשך לקדש למ\"ד א\"כ בהכרח שיוכתב שם הוי' למעלה וקדש למ\"ד מלמטה ואזי במשמעותו שקדש למ\"ד נמשך אח\"כ כו', ועתה כל משמעות העיקרי שיש בלמ\"ד הוא שרצונו לומר מלמטה <span data-k=\"pg\">1072</span> ּ למעלה<sup data-n=\"5445\">59</sup> כמו נודה לאלקינ\"ו<sup data-n=\"5446\">60</sup> וכיוצא, והיינו שקדש למ\"ד מסתכלים כלפי שם הוי', שבשיטה עליונה מלמטה למעלה כו'.\n<b>וביאור</b> זה הנה ידוע דפי' קדש בכל מקום הוא בבחי' אור אבא<sup data-n=\"5447\">61</sup> דאצי' שנק' קדש עילאה כו', ושם הוי' סתם הוא בבחי' ז\"א<sup data-n=\"5448\">62</sup> דאצי' בכל מקום ואם היו כתובים קדש להוי' בשיטה אחת הי' משמעו שאור אבא נמשך ומתלבש בשם הוי' דז\"א כו', ובאמת כאן נהפוך הוא שאור אבא שמלובש בז\"א הנק' קדש למ\"ד בג' מוחין דצלם דז\"א כו' מקבל מלמעלה ממנו והוא מבחי' שם הוי' דבחכמ' סתימא' דא\"א ע\"י י\"ג תקוני' כו' ע\"כ נכתב שם הוי' למעלה והוא בחי' חב\"ד דא\"א וקדש למ\"ד מלמטה והציץ הוא בחי' ההסתכלות דא\"א בז\"א להאיר במצחו כנ\"ל. וזהו שהיו ב' תיבות הללו נכתבי' בציץ שעל מצח אהרן כדי להאיר בקדש למ\"ד שבז\"א מבחי' רעוא דכל רעוין והוא אסתכלותא דז\"א שמסתכל מלמטה למעלה,",[["5443","57","<b>יאר ה' פניו אליך</b>: נשא ו, כה."],["5444","58","<b>קדש למ\"ד מלמטה והוי' מלמעלה</b>: נסמן לעיל שנו, א."],["5445","59","<b>בלמ\"ד. . מלמטה למעלה</b>: ראה גם לעיל שנח, א."],["5446","60","<b>נודה לאלקינ\"ו</b>: נוסח תפלת שחרית (אין כאלקינו)."],["5447","61","<b>קדש. . אור אבא</b>: ראה זהר (רעיא מהימנא) בא מג, רע\"ב. אמור צד, ב. לעיל פ' וארא נח, ב. נד, ג. לקמן פ' ויקהל תלו, סע\"ד ואילך."],["5448","62","<b>הוי'. . ז\"א</b>: ראה זהר (אד\"ר) נשא קכט, א."]]],[2300550311,"כמאמר הנ\"ל דרעותא דז\"א לקבלא האי רעותא כמ\"ש והי' על מצחו תמיד לרצון כו' והוא אסתכלותא דקדש למ\"ד מלמטה כלפי שם הוי' שבשיטה העליונה שאח\"כ מאיר ומסתכל מרצון העליון הפשוט בשם הוי' הא' די\"ג מדה\"ר נמשכי' ממנו בצמצומים וכנ\"ל. וא\"כ נמצא שהציץ הזה הוא מקור ושרש לי\"ג מדה\"ר שנמשכי' משם הוי' זה שבשיטה העליונה כי מה שנמשכי' משם הוי' זה הוא רק ע\"י צמצום בלבד ואסתכלותא שבציץ הוא מאיר ובא בבחי' גילוי במצחא דא\"א כנ\"ל וד\"ל. וזהו כוונת הכתוב באמרו והי' על מצחו תמיד לרצון כו' לא בשביל המשכת י\"ג מדה\"ר בלבד משם הוי' דא\"א, אלא להיות מקור ושרש תמידי למציא' המשכת י\"ג מדה\"ר מחמת אסתכלותא דציץ במצחא דא\"א, והוא הי' מונח על מצח אהרן מפני שלא הי' בו שערות כלל, ולהיותו בחי' גילוי הרצון הפשוט יותר גם מבמוחין דא\"א ע\"כ מסיבתו נולד מקור למציאו' התפשטו' י\"ג מדה\"ר ממוחין דא\"א בי\"ג תקוני דיקנא כו', וזהו והי' על מצחו תמיד לרצון לפני הוי', פי' לרצון גילוי רצון לרצון והוא לפני הוי' דא\"א ג\"כ מטעם הנ\"ל וד\"ל. וזהו שמפרש הטעם ונשא אהרן את עון הקדשים<sup data-n=\"5449\">63</sup> כו', כי הנה מ\"ש בי\"ג מדה\"ר נושא עון ועובר על פשע<sup data-n=\"5450\">64</sup> כו' אין לו דמיון כלל עם מ\"ש כאן ונשא אהרן כו', שבי\"ג מדה\"ר לא נמשך האור ובא רק בבחי' צמצום גדול מח\"ס דא\"א כנ\"ל ואז הוא נק' מזל נושא עון כו', ולפי ערך העלאת מ\"ן בתשובה מלמטה כך נמשך האור להיות נושא עון כו'. אבל ונשא אהרן את עו\"ן כו', הענין הוא מפני שבחי' הארת רעוא דכל רעוין שנק' חנון המרב\"ה לסלו\"ח<sup data-n=\"5451\">65</sup> וכמ\"ש כי עמ\"ך הסליח\"ה<sup data-n=\"5452\">66</sup> כו' וכמ\"ש במ\"א, והוא נושא עון הקדשים בתמידות לפי שגם חשך לא יחשיך לפניו כו' והוא שרש מקור לסליחת העוונות בי\"ג מדה\"ר וכנ\"ל הטעם, לכך אמר ונש\"א אהרן כו' מפני הארת הציץ שמרצה בתמידות מאור רעוא דכל רעוין שמאיר במצחא דע\"ק כנ\"ל והיינו שמפרש הטעם שכדי שישא אהרן עון הקדשים בתמידות בהכרח שיהי' הציץ במצחו תמיד לרצון לפני הוי' וכנ\"ל וד\"ל.\n<span data-k=\"pg\">תקלו</span> ּ<b>ו</b> וזהו ועשית ציץ זהב טהור כו' משה הוא העושה את הציץ דוקא, והענין הוא כי הנה יש ב' מדרגות בתורה, הא' מ\"ש תורה צוה לנו משה<sup data-n=\"5453\">67</sup> דמשמע שמשה הוא המשפיע לנו את התורה, דהנה מבואר בספרי הקבלה דעיקר",[["5449","63","<b>ונשא אהרן את עון הקדשים</b>: תצוה כח, לח."],["5450","64","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח."],["5451","65","<b>חנון המרב\"ה לסלו\"ח</b>: תפלת שמו\"ע."],["5452","66","<b>כי עמ\"ך הסליח\"ה</b>: תהלים קל, ד. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'קב."],["5453","67","<b>תורה צוה לנו משה</b>: ברכה לג, ד. ראה גם לעיל שמו, ד."]]],[2300550336,"התורה והמצות הוא בע\"ס דז\"א<sup data-n=\"5454\">68</sup> דאצי' כי אורייתא מחכמה דאבא נפקת<sup data-n=\"5455\">69</sup> היינו להיות חכמה בז\"א ושית' סדרי משנה הן בחי' המדות<sup data-n=\"5456\">70</sup> וכו', וגם המצות שנק' רמ\"ח אברי'<sup data-n=\"5457\">71</sup> הכל בבחי' ז\"א כידוע. והגם שידוע בשרש המצות שהן בבחי' הכת\"ר והוא הנק' באד\"ר תרי\"ג ארחין דגלגלתא<sup data-n=\"5458\">72</sup> כו' זהו בבחי' ההעלם, אבל בבחי' גילוי שרשם בע\"ס דז\"א בבחי' הכלים שלהם והתורה בבחי' האור כמ\"ש כי נר מצוה ותורה אור<sup data-n=\"5459\">73</sup> כו'. ולהיות כן כאשר אור התורה והמצות שבבחי' האצי' מתגלי' ונמשכים לעולמות הנפרדי' מאין ליש ממש הוא ע\"י משה שהוא המשפיע התורה למטה וכמ\"ש בפסוק הזה בפירוש תורה צוה לנו משה כאלו משה ציוה מעצמו תורה זו הנגלית לנו, והענין הוא שע\"י משה נשפעת מאצי' לבי\"ע כו'. והב' הוא הנק' תורת משה<sup data-n=\"5460\">74</sup> שמשה הוא בחי' מקבל ממקור התורה כמ\"ש בכל פרשה וידבר ה' אל משה<sup data-n=\"5461\">75</sup> כו', והענין הוא בשרש המקור הראשון לאור התורה דאצי' שהוא בבחי' ח\"ס דא\"א והמצות נק' ארחין כו' שמשם נמשך אור הכתר בחכמה ולהיות התלבשות אור הכת\"ר בחכמה, הנה המביא והממשיך המשכה זאת הוא ג\"כ בחי' מש\"ה והרי הוא בחי' מקבל בלבד והוא ע\"י שהוא בחי' ביטול מעצמותו מכל וכל וכמ\"ש משה ונחנו מ\"ה<sup data-n=\"5462\">76</sup> כו', וכידוע בפי' ודברי אשר שמתי בפיך<sup data-n=\"5463\">77</sup> כענין לימוד משניות של הרב\"י שאמר לו המגיד אני הוא המשנה המדברת בפיך<sup data-n=\"5464\">78</sup> כו'. ובאמת אין הענין כמו שסוברין העולם שהמדבר בו הוא מלאך נפרד מעצם האדם אלא הענין הוא שמעצם כחות נפשו של האדם מדבר בו הדיבור הזה כשהוא בבחי' הביטול במציאות, וזהו מ\"ש רוח דיבר בי<sup data-n=\"5465\">79</sup> ב\"י ממש כלומר מעצמותו מדבר בו ולא דבר אחר נפרד. וכן כל השגת הנביאים הי' עד\"ז שמעצמותם הי' זה הרוח מדבר, אך שהי' נבדל במה שהי' גם הוא שומע מה שמדבר כמו ששומע זולתו, אבל מ\"מ רוח זה רוח מעצמותו ולא מלאך נפרד מעצמותו, והגם שנאמר המלאך הדובר בי<sup data-n=\"5466\">80</sup> דמשמע שהי' מלאך נפרד מעצמותו מ\"מ התלבשותו בנפש הנביא הי' בבחי' עצמיו' כמ\"ש הדובר בי בי ממש ע\"ד הנ\"ל, ועד\"ז כל השגו' רוה\"ק וגילוי אליהו וכיוצא. ומעין ודוגמא זו הוא הלימוד בתורה בבחי' הביטול הנ\"ל כמו רב יהודה שהתפלל רק מל' יום לל' יום<sup data-n=\"5467\">81</sup> מפני שלימודו הי' בבחי' ביטול זה, וזהו שנק' מי שתורתו אומנתו<sup data-n=\"5468\">82</sup> כלומר כמו כלי אומנות שבחי' האומן הפועל פועל בהם כך המשכת אור א\"ס בחכמה שעי\"ז נעשה מציא' התורה ה\"ז כעושה כלי בכח המשכה זו כו'. ולכך נק' תורת משה שמשה",[["5454","68","<b>התורה. . דז\"א</b>: ראה ע\"ח שער הכללים פ\"א. (שער המוחין) ש\"כ, פ\"ג. (שער דרושי הצלם) שכ\"ה, דרוש ח."],["5455","69","<b>אורייתא מחכמה דאבא נפקת</b>: נסמן לעיל פ' יתרו רסח, ד."],["5456","70","<b>ושית' סדרי משנה. . המדות</b>: ראה גם ת\"ז בהקדמה (ה, א). תכ\"א מג, ב. ובכסא מלך שם אות ב. טעמי המצות להאריז\"ל ואתחנן ד\"ה בענין מקרא משנה. לקמן פ' ויקהל תלט, ד. פקודי תמד, א."],["5457","71","<b>המצות שנק' רמ\"ח אברי'</b>: ראה ת\"ז ת\"ל (עד, סע\"א). שע\"ת עב, ג הערה 17."],["5458","72","<b>תרי\"ג ארחין דגלגלתא</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, א."],["5459","73","<b>כי נר מצוה ותורה אור</b>: משלי ו, כג."],["5460","74","<b>תורת משה</b>: יהושע ח, לא. לב. כג, ו. ועוד."],["5461","75","<b>כמ\"ש בכל פרשה וידבר ה' אל משה</b>: ראה גם לעיל פ' וארא נט, א ובהערה 30."],["5462","76","<b>ונחנו מ\"ה</b>: בשלח טז, ז. ח."],["5463","77","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא. ראה גם לעיל פ' יתרו רנג, ד."],["5464","78","<b>אני הוא המשנה המדברת בפיך</b>: ראה מגיד משרים פ' ויחי־ בא־ תשא־ ועוד (ירושלים תש\"ך מה, ב. נג, ב. סט, ב). לקמן פ' פקודי תמה, ד. תס, ד. מאמרי אדה\"ז תקס\"ב ח\"ב ע' שפז. שערי תשובה פ, ג ובהערה 26."],["5465","79","<b>רוח דיבר בי</b>: שמו\"ב כג, ב (בדילוג)."],["5466","80","<b>המלאך הדובר בי</b>: זכרי' א, ט. יג. יד. ועוד."],["5467","81","<b>רב יהודה שהתפלל רק מל' יום לל' יום</b>: ר\"ה לה, א."],["5468","82","<b>שתורתו אומנתו</b>: שבת יא, א."]]],[2300550361,"עושה אותה<sup data-n=\"5469\">*83</sup> לבנותה ממקור חוצבה בהמשכתו אור א\"ס בחכמה, וז\"ש והאלקים יעננו בקול בקולו של משה<sup data-n=\"5470\">83</sup> כו' וד\"ל.\n<b>וזהו</b> ג\"כ ענין עוסק בתורה לשמ\"ה<sup data-n=\"5471\">84</sup> <span data-k=\"pg\">1074</span> ּ לשם התורה לעשות התורה באצי' כו', והנה מתורה דאצי' לבי\"ע א\"א להמשכה בלתי העלאה במס\"נ והוא לקשר ולדבק המחשבה והדיבור כו', ואח\"כ ממשיך על נפשו אור התורה כו'. וכך בתורת משה ממאציל לאצי' ג\"כ א\"א להמשכה בלתי העלאה במס\"נ והוא בחי' הביטול בהעדר הרגשת עצמותו לגמרי, והוא דוקא כשאין לו רצון אחר כלל כמ\"ש מי לי בשמים<sup data-n=\"5472\">85</sup> כו' דהיינו בבחי' יחידה שבנפש כמבואר בענין וקב\"ל היהודים<sup data-n=\"5473\">86</sup> כו' דבשעת מ\"ת כתיב ויחן ישראל<sup data-n=\"5474\">87</sup> ל' יחיד כו' לפי שקבלת התורה א\"א כ\"א בבחי' מס\"נ עד שלא הי' בהם רק רצון א' כו'. וזהו מ\"ש משה ונתתי מטר ארצכם<sup data-n=\"5475\">88</sup> כו' כאלו הוא הנותן ח\"ו אין זה אלא לפי שאמר תחלה ולעבדו בכל נפשכם<sup data-n=\"5476\">89</sup> ואח\"כ ונתת\"י כי רוח ה' דיבר בו כנ\"ל וד\"ל. ובכ\"ז מובן שהציץ הנ\"ל לא הי' באפשרי להיות כ\"א ע\"י משה דוקא כי בחי' מ\"ה דמשה הוא הממשיך אור א\"ס בחכמה שבתורה ומצות והיינו שיהי' לו ית' רצון זה המלובש בתורה ומצות בפרט והרי המשיך בחי' רצון לרצון שהוא בחי' רעוא דכל רעוין הנ\"ל שהוא המאיר בציץ כמ\"ש באד\"ר שנק' טורנ\"א יא\"ה<sup data-n=\"5477\">90</sup> כנ\"ל וד\"ל. ושרש ענין המבואר שם שע\"י ציץ זה במצח אהרן הי' לעומת קליפת עמלק<sup data-n=\"5478\">91</sup> כי אחורי העורף נגד המצח הוא, וידוע דבג\"ר לא הי' שבירה<sup data-n=\"5479\">92</sup> ושרש הג\"ר דז\"א הוא בג\"ר דא\"א ששם נק' ח\"ס ובינה דא\"א נק' יין המשומר<sup data-n=\"5480\">93</sup> בענביו<sup data-n=\"5481\">94</sup> כחמרא דשקיט על דורדייא<sup data-n=\"5482\">95</sup> כו', פי' משומר ממג\"ע נכר\"י<sup data-n=\"5483\">96</sup> שאין נגיעה לחיצונים שם כלל, לפי שאין להם שם אפי' שרש לשרש להיות להם אחיזה ויניקה כו' ולכך ממילא אין לקליפת עמלק יניקה שם כלל, ואע\"פ שעומד נגד הדעת היינו לנגד מוח הדעת שבג' חללי גלגלתא<sup data-n=\"5484\">97</sup> אבל במצחא מאיר מבחי' רעוא דכל רעוין דכל ד' מאה בתי דינין משתככין כנ\"ל<sup data-n=\"5485\">98</sup>,",[["5469","*83","<b>שמשה עושה אותה</b>: ראה גם לקמן פ' ויקהל תכו, ג."],["5470","83","<b>והאלקים יעננו בקול בקולו של משה</b>: יתרו יט, יט. ברכות מה, א."],["5471","84","<b>עוסק בתורה לשמ\"ה</b>: ראה אבות רפ\"ו. ראה גם לעיל שנט, ג ובהנסמן שם."],["5472","85","<b>מי לי בשמים</b>: תהלים עג, כה."],["5473","86","<b>וקב\"ל היהודים</b>: מאמרי אדה\"ז תקס\"ו ע' קכה. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370437\" data-slug=\"torah-or\" data-id=\"3901370437\">תו\"א צז, סע\"ד</a>."],["5474","87","<b>ויחן ישראל</b>: יתרו יט, ב [ושם: ויחן שם ישראל — נסמן לעיל פ' שמות יד, א]."],["5475","88","<b>ונתתי מטר ארצכם</b>: עקב יא, יד."],["5476","89","<b>ולעבדו בכל נפשכם</b>: עקב שם, יג [בדילוג]."],["5477","90","<b>באד\"ר שנק' טורנ\"א יא\"ה</b>: ראה בריש המאמר ושם: אדר\"ז."],["5478","91","<b>ציץ. . עמלק</b>: ראה לעיל שנו, א ואילך. שנח, ד ואילך."],["5479","92","<b>דבג\"ר לא הי' שבירה</b>: ראה ע\"ח (שער דרושי הנקודות) ש\"ח, פ\"ב. מאמרי אדה\"א דברים ח\"א ע' ט. וש\"נ. לעיל פ' יתרו ער, ד ובהנסמן לשם."],["5480","93","<b>ובינה דא\"א נק' יין המשומר</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' סז. ח\"ד ע' א'תקיד. וש\"נ. לקמן הערות 94. 96."],["5481","94","<b>יין המשומר בענביו</b>: ראה ברכות לב, ב. מאמרי אדה\"א דברים ח\"א ע' סז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670064\" data-slug=\"torat-chaim\" data-id=\"2300670064\">תו\"ח לך צא, ג</a> הערה 32."],["5482","95","<b>כחמרא דשקיט על דורדייא</b>: ראה זהר חדש שה\"ש סד, ב."],["5483","96","<b>יין. . משומר ממג\"ע נכר\"י</b>: ראה זהר תרומה קמז, א ובאוה\"ח שם. מאמרי אדה\"א קונטרסים ע' תקמו. וש\"נ. ש\"א עד, ב ובהערה 11."],["5484","97","<b>שבג' חללי גלגלתא</b>: נסמן לעיל שנח, ב."],["5485","98","<b>ד' מאה בתי דינין משתככין כנ\"ל</b>: ראה בריש המאמר."]]],[2300550381,"והדינין אינן נמשכי' אלא מן הדעת שמחלק לח' חדרים והח' לל\"ב כנ\"ל, ומשה שהמשיך בדעת דז\"א מדעת דע\"י ע\"י הציץ לכך הי' הוא דוקא לעומת עמלק וכמ\"ש וכאשר ירי\"ם מש\"ה יד\"ו<sup data-n=\"5486\">99</sup> וגבר ישראל וד\"ל.",[["5486","99","<b>וכאשר ירי\"ם מש\"ה יד\"ו</b>: בשלח יז, יא [ושם: והי' כאשר]."]]],[2300550062,"<b>בעזר\"ה. פ' תצוה</b>\n<b>ועשית</b> ציץ<sup data-n=\"5487\">1</sup> זהב טהור<sup data-n=\"5488\">2</sup> ופתחת עליו פתוחי חותם קדש להוי' כו', וידוע דרז\"ל שהי' כתוב בב' שיטין קד\"ש ל' למטה והוי' למעלה<sup data-n=\"5489\">3</sup> (וראב\"י ראה ברומי<sup data-n=\"5490\">4</sup> והי' כתוב קדש לה' בשיטה א' וע' ברמב\"ם<sup data-n=\"5491\">5</sup> ). והנה להבין זה וג\"ל<sup data-n=\"5492\">6</sup> בעיקר ענין הציץ על מה הי' מכפר דלפי המבואר בכתוב הי' בו ב' ענינים, א' לכפר על עון הקדשים כמ\"ש והי' על מצח אהרן<sup data-n=\"5493\">7</sup> ונשא אהרן את עון הקדשי' כו'. והב' מ\"ש והי' על מצחו תמיד<sup data-n=\"5494\">8</sup> לרצון להם לפני ה' שענין זה הוא לרצון תמיד לפני ה' כמו שהי' על מצחו תמיד שזהו רק בשביל ישראל שיהי' מאיר עליהם הרצון העצמי מבחי' רעדכ\"ר דאתגליא במצחא<sup data-n=\"5495\">9</sup> כו' כמ\"ש בזהר, והוא מש\"א לרצון להם לפני ה' ממש וקאי אדסמיך לי' דהיינו שהי' על מצחו תמיד לרצון להם בלי הפסק כלל כו' (ורש\"י פי'<sup data-n=\"5496\">10</sup> שא\"א שיהי'<sup data-n=\"5497\">11</sup> על מצחו <span data-k=\"pg\">תקלז</span> ּ תמיד שהרי אינו עליו אלא בשעת עבודה<sup data-n=\"5498\">12</sup> אלא תמיד לרצות להם אפילו אינו על מצחו כגון שלא בשעת עבודה<sup data-n=\"5499\">13</sup> ויש מ\"ד<sup data-n=\"5500\">14</sup> כשאינו על מצחו<sup data-n=\"5501\">15</sup> אינו מרצה ומ\"ש תמיד<sup data-n=\"5502\">16</sup> לרצון כו' זהו<sup data-n=\"5503\">17</sup> בזמן<sup data-n=\"5504\">18</sup> שמשמש<sup data-n=\"5505\">*19</sup> בו שלא<sup data-n=\"5506\">19</sup> יסיח דעתו ממנו כמש\"א<sup data-n=\"5507\">20</sup> בתפילין<sup data-n=\"5508\">21</sup> כו'). ועכ\"פ מובן מזה ע\"ד הפשוט שמ\"ש והי' על מצחו תמיד לרצון להם כו', שמן הציץ דוקא שהי' על מצחו הוא שנמשך בחי' הרצה\"ע ברב חסד מטה כלפי חסד וטוב בתמידות בלי שינוי כלל כמו אך טו\"ב לישראל<sup data-n=\"5509\">22</sup> כו'. ובאמת אין זה מובן ע\"ד הפשוט מאין יבא ענין המשכות והתעוררות הרצון העליון למעלה ע\"י הציץ גשמי מן זהב גשמי שהי' על מצח כה\"ג כו'",[["5487","1","<b>ועשית ציץ</b>: מיוסד על מאמר ד\"ה זה שנדפס לעיל שנו, א. וש\"נ. ראה עוד ע\"ד המאמר לקמן ברשימות הכת\"י [ושם ג\"כ מפורט סימני האותיות הבאות להלן בהמראי מקומות]."],["5488","2","<b>ועשית ציץ זהב טהור</b>: תצוה כח, לו."],["5489","3","<b>קד\"ש ל' למטה והוי' למעלה</b>: נסמן לעיל שנו, א."],["5490","4","<b>וראב\"י ראה ברומי</b>: שבת סג, ב. לקו\"ש שבהערה הבאה הערה 4."],["5491","5","<b><a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261200\" data-slug=\"likkutei-sichot\" data-id=\"1300261200\">וע' ברמב\"ם</a></b>: רפ\"ט מהל' כלי המקדש. ראה גם לקו\"ש תצוה כרך כו ע' 200."],["5492","6","<b>זה וג\"ל</b>: א: כ\"ז וגם י\"ל. כא: זה וגם להבין."],["5493","7","<b>והי' על מצח אהרן</b>: תצוה כח, לח."],["5494","8","<b>והי' על מצחו תמיד</b>: סיום הכתוב והי' על מצח אהרן."],["5495","9","<b>רעדכ\"ר דאתגליא במצחא</b>: ראה זהר (אד\"ר) נשא קכט, א. קלו, ב."],["5496","10","<b>ורש\"י פי'</b>: תצוה כח, לח (בשינויים — כדלהלן)."],["5497","11","<b>שא\"א שיהי'</b>: שם: אי אפשר לומר שיהא."],["5498","12","<b>עבודה</b>: שם העבודה."],["5499","13","<b>כגון שלא בשעת עבודה</b>: שם: שלא הי' כה\"ג עובד באותה שעה."],["5500","14","<b>ויש מ\"ד</b>: יומא ז, ב."],["5501","15","<b>ויש מ\"ד כשאינו על מצחו</b>: שם: ולדברי האומר עודהו על מצחו מכפר ומרצה ואם לאו."],["5502","16","<b>ומ\"ש תמיד</b>: שם: נדרש על מצחו תמיד."],["5503","17","<b>לרצון כו' זהו בזמן</b>: שם: מלמד."],["5504","18","<b>בזמן</b>: איגכג: ליתא."],["5505","*19","<b>שמשמש</b>: ב: שממשמש."],["5506","19","<b>בו שלא</b>: ברש\"י: בו בעודו על מצחו שלא."],["5507","20","<b>כמש\"א בתפילין</b>: שם: ליתא."],["5508","21","<b>כמש\"א בתפילין</b>: ראה יומא שם."],["5509","22","<b>אך טו\"ב לישראל</b>: תהלים עג, א."]]],[2300550094,"וגם מ\"ש לרצון להם דוקא לפני ה' דוקא והי' זה ג\"כ מסיבת כתיבת ב' תיבות הללו שנכתב על הציץ קדש לה' בפתוחי חותם כו' וקדש ל' מלמטה כו' וד\"ל. אך הנה מ\"ש ועשית ציץ כו' והי' על מצח אהרן כו' מובן מזה שיש כאן ב' תנאים, א' שיהי' מעשה הציץ ע\"י משה דוקא כמ\"ש ועשית ציץ כו' (וכך הי' כל בגדי אהרן שאמר הציווי במעשה למשה דוקא כמו במעשה חשן ומעשה האפוד א' ועשית חשן משפט<sup data-n=\"5510\">23</sup> כו' ועשית את מעיל האפוד<sup data-n=\"5511\">24</sup> כו'). והב' והי' על מצח אהרן דוקא, דמשמע דזה בלא זה אינו כלום משום דמשה שושבינא דמלכא<sup data-n=\"5512\">25</sup> ואהרן שוש' דמטרוניתא<sup data-n=\"5513\">26</sup> וע\"כ אינו מועיל זה בלא זה כלום כו' דאם לא עשי' דמשה לא יועיל הלבשת אהרן את הבגדים בציץ על מצחו להיות לרצון כו', ובעשי' דמשה בלא הלבשת אהרן ג\"כ אינו לרצון להם כלל כו' וד\"ל.\n<b>והנה</b> י\"ל בפי' ציץ שיתפרש בג' אופנים א' כפשוטו מלשון הארת אור וזיו כמו ועליו יציץ נזרו<sup data-n=\"5514\">27</sup> כו', והכוונה בזה בענין התחלת יציאת ובקיעת האור כמו כאשר יתנוצץ אור השמש בזריחתו בבוקר אור שנק' נץ החמה<sup data-n=\"5515\">28</sup> כידוע וכה\"ג. והב' מענין צמיחה ופריחה שנק' הנצה, כמו הבאים ישרש יעקב<sup data-n=\"5516\">29</sup> יציץ ופרח ישראל, וכן א' הנצו הרמונים<sup data-n=\"5517\">30</sup>, וכמו והיא כפורחת עלתה נצה<sup data-n=\"5518\">31</sup> כו' וכה\"ג, וג\"ז על הרוב מדבר בענין התחלת הפריחה והנצה כו'. והג' מענין הבטה והסתכלות<sup data-n=\"5519\">32</sup> כמו מציץ מן החרכים<sup data-n=\"5520\">33</sup> וכה\"ג. ולכאורה ג' אלה הפי' אין ענינם דומה זל\"ז כלל דהיינו ענין אור וזיו עם ענין [התחלת ה]פריחה והנצה וענין הסתכלות והבטה כו' שאין להם חיבור ושייכות זע\"ז כלל, ועכ\"ז בענין הציץ יש כל אלה הפי' וכולם אמת ([ו]כמשי\"ת). אך ה[נה] ת[חלה] י\"ל בתנאי שיהי' הציץ על מצח אהרן דוקא כנ\"ל, ויש להבין תחלה בשרש בחי' אהרן כה\"ג שהתורה נצחי' היא<sup data-n=\"5521\">34</sup> וגם יש עכשיו בחי' אהרן כה\"ג וענין הציץ שעל מצחו להיות לרצון תמיד כו'.\n<b>דהנה</b> ידוע דאהרן הוא מז'<sup data-n=\"5522\">35</sup> הרועים<sup data-n=\"5523\">36</sup> כמ\"ש והקימותי עליו ז' רועים<sup data-n=\"5524\">37</sup> כו' שהן נק' רועים לישראל שנק' צא\"ן קדשי\"ם<sup data-n=\"5525\">38</sup> וכידוע בכדו\"ד<sup data-n=\"5526\">39</sup>, וענין הרועה צאן בגשמיות היינו שהוא מוליך [את] הצאן במקום מרעה טוב ומשגיח עליהם לזונם <span data-k=\"pg\">1076</span> ּ ולפרנסם תמיד במרעה טוב ושמן ולקבץ הנדחות ולהשקותם כו'. וכך הוא למעלה שנק' רועה ישראל [כ]אהרן שממנו נמשך",[["5510","23","<b>ועשית חשן משפט</b>: תצוה כח, טו."],["5511","24","<b>ועשית את מעיל האפוד</b>: שם שם, לא."],["5512","25","<b>דמשה שושבינא דמלכא</b>: נסמן לעיל פ' יתרו רסג, ב."],["5513","26","<b>ואהרן שוש' דמטרוניתא</b>: נסמן לעיל רסט, ד."],["5514","27","<b>ועליו יציץ נזרו</b>: תהלים קלב, יח."],["5515","28","<b>נץ החמה</b>: ברכות ח, ב. ט, ב. ועוד."],["5516","29","<b>הבאים ישרש יעקב</b>: ישעי' כז, ו."],["5517","30","<b>הנצו הרמונים</b>: שה\"ש ו, יא. ז, יג."],["5518","31","<b>והיא כפורחת עלתה נצה</b>: וישב מ, י."],["5519","32","<b>ציץ. . הבטה והסתכלות</b>: ראה גם לעיל שנו, א. וש\"נ."],["5520","33","<b>מציץ מן החרכים</b>: שה\"ש ב, ט."],["5521","34","<b>שהתורה נצחי' היא</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310022\" data-slug=\"tanya\" data-id=\"3401310022\">תניא</a> פי\"ז. לעיל פ' שמות א, א. וש\"נ."],["5522","35","<b>דאהרן הוא מז' הרועים</b>: נסמן לעיל שנו, א."],["5523","36","<b>מז' הרועים</b>: נסמן לעיל פ' משפטים רפב, ב."],["5524","37","<b>והקימותי </b>[א: כבפנים. כא: והקימנו]<b> עליו ז' רועים</b>: מיכה ה, ד."],["5525","38","<b>לישראל שנק' צא\"ן קדשי\"ם</b>: ראה יחזקאל לו, לח ובת\"י שם. מאמרי אדה\"א דברים ח\"ב ע' תקעא."],["5526","39","<b>ז' הרועים. . בכדו\"ד </b>[אכא: בכל דוד ודור]: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שצח. מאמרי אדה\"א שמות ח\"ב ע' שטו."]]],[2300550126,"פרנסה ושפע טובה לנש\"י בכל דור ודור כמ\"ש ה' רועי לא אחסר<sup data-n=\"5527\">40</sup> בנאות דשא ירביצני<sup data-n=\"5528\">41</sup> על מי מנוחות ינהלני כו', וכך [בחי' אהרן] למעלה [הוא] הרועה [ל]ישראל שזן ומפרנס לנש\"י במרעה טוב<sup data-n=\"5529\">42</sup> בנאות דשא ומי מנוחות כו' שהוא כח המע[לה] מ\"נ בנשמות ע\"י בחי' עשב<sup data-n=\"5530\">43</sup> העליון, והוא בחי' התעוררות האה\"ר שלמעלה מן השכל והטעם שמתעורר אדם פתאום בלי הכנה מעצמו כלל שהוא בא בבחי' מקיף בהעלם על נפשו שאין המשכה וגילוי התעוררות אה\"ר זו תלוי' באדם כלל זהו כמו המרעה [ה]טוב לצאן שיומשך בהן כח ועוז לפרנסם ולהשקותם (שזהו בחי' המשכת מ\"ד מבחי' מ\"י מנוחו\"ת שהוא מה שישתוקק האדם בהמשכת גילוי אלקות בנפש[ו] ע\"י תו\"מ בבחי' שוב, שזהו כמו מים קרים על נפש עיפה<sup data-n=\"5531\">44</sup> להשיב את הנפש כו' שזהו ג\"כ בא מלמעלה למטה ע\"י הרועה שישקה לנש\"י תמיד אחר צמאונם ואחר [שזנם ומפרנסם] שהוא בחי' הע[לאת] מ\"נ שמעורר בלבו<sup data-n=\"5532\">45</sup> אה\"ר הנ\"ל). אך לכאו' אין זה מובן דאיך יתכן שיבוא לאדם התעוררות אה\"ר מלמעלה<sup data-n=\"5533\">46</sup> הלא אמר דהכל בידי שמים<sup data-n=\"5534\">47</sup> חוץ מיראת שמים כו' וכמו שיראת שמים אינה אלא בידי אדם דוקא כך אה' אלקי' אינה תלוי רק בבחירה שבאדם כמ\"ש ראה נתתי לפניך<sup data-n=\"5535\">48</sup> החיים והטוב והמות והרע ובחרת בחיים<sup data-n=\"5536\">49</sup> כו' וכך א' ועתה ישראל<sup data-n=\"5537\">50</sup> כו' וכן מצוה על אהבה כמ\"ש ואהבת את ה'<sup data-n=\"5538\">51</sup> לאהבה את<sup data-n=\"5539\">52</sup> ה'<sup data-n=\"5540\">53</sup> כו' וכה\"ג רבים בכתובים.\nאמנם הנה ידוע שיש ב' מיני אהבה א' האהבה שתלוי' בבחירה שבאדם דוקא דהיינו מה שביכולת האדם להגיע אליו ביגיעתו באמת במוחו ולבו כמו שיתן לבו ודעתו היטיב בגדולת ה' ונפלאותיו והשגחותיו כו' שיתפעל בלבו מזה באהבה ותשוקה לידבק בה' אחד, וזהו הציווי ואהבת שתייגע עצמך לבא לידי תולדות<sup data-n=\"5541\">54</sup> התפעלות האהבה אלקי' בכל לבבך ובכל נפשך כו' שזהו שנק' בזהר פולחנא דרחימותא<sup data-n=\"5542\">55</sup> שנק' עבודה [עכ\"פ] עד שנצרך ציווי ואזהרה ע\"ז שבלתי עבודה לא יגיע אלי' ויתקרר לבו מעט מעט עד שיפול הנופל ויתרחק מאלקים חיים לגמרי כו'. אך באמת הרי עיקר מהות האהבה האלקי' שהיא בחי' ההתקשרות דנה\"א בעצם באלקים חיים זהו כבר מוטבע כמו טבעי' ממש בה ונק' אהבה טבעית המסותרת בלב האדם בהעלם גדול, ולפרקים תתגלה כמו בנסיון כאשר יבא עליו צרות ויסורים בביטושים גדולים בבני חיי ומזוני וכה\"ג",[["5527","40","<b>ה' רועי לא אחסר</b>: תהלים כג, א."],["5528","41","<b>בנאות דשא ירביצני</b>: שם שם, ב."],["5529","42","<b>טוב</b>: כא: נאה."],["5530","43","<b>עשב</b>: כא: משה[!]."],["5531","44","<b>מים קרים על נפש עיפה</b>: משלי כה, כה."],["5532","45","<b>בלבו</b>: א: בהם."],["5533","46","<b>אה\"ר מלמעלה</b>: יגכאכג: אהב' אלקי' בלא בחירה שלו כלל."],["5534","47","<b>דהכל </b>[כא: הכל]<b> בידי שמים</b>: ברכות לג, ב."],["5535","48","<b>ראה נתתי לפניך</b>: נצבים ל, טו [בשינוי — ראה גם הנסמן לעיל פ' בשלח קמו, ד]."],["5536","49","<b>ובחרת בחיים</b>: נצבים שם, יט."],["5537","50","<b>ועתה ישראל</b>: עקב י, יב."],["5538","51","<b>ואהבת את ה'</b>: ואתחנן ו, ה."],["5539","52","<b>לאהבה את ה'</b>: נסמן לעיל שנו, ב"],["5540","53","<b>לאהבה את ה'</b>: א: ליתא."],["5541","54","<b>תולדות</b>: כא: ליתא."],["5542","55","<b>פולחנא דרחימותא</b>: ראה זהר בשלח נה, ב. ואתחנן רסז, א. מאמרי אדה\"א בראשית ע' צח. שמות ח\"ב ע' תעט. קונטרסים ע' נה וע' פה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380482\" data-slug=\"likkutei-torah\" data-id=\"4001380482\">לקו\"ת שלח מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151121\" data-slug=\"likkutei-sichot\" data-id=\"1300151121\">לקו\"ש וירא כרך טו ע' 121</a> הערה 28."]]],[2300550158,"וכמ\"ש בצר לך<sup data-n=\"5543\">56</sup> כו', שאז נגלה מן ההעלם בחי' נקוד' אה\"ר<sup data-n=\"5544\">57</sup> המסותרת הטבעי' הזאת שהיא נטוע ומושרש בנש\"י בבחי' ירושה מאבות<sup data-n=\"5545\">58</sup> שהן המרכבה<sup data-n=\"5546\">59</sup> והעיקר אברהם<sup data-n=\"5547\">60</sup> שהוא השרש הראשון לנש\"י והוא הרועה הראשון<sup data-n=\"5548\">61</sup> כידוע. ולפ\"ז אינו מובן מה שציוה ה' באזהרה לעבוד [ב]עבודת האהבה האלקי' ע\"י יגיעה במוח ולב כו' כנ\"ל דלמה צריך לציווי זה, או שלא יועיל היגיעה אם כבר נעקר מלבו נקודת ההתקשרות אה\"ר העצמית <span data-k=\"pg\">תקלח</span> ּ ע\"י חטאים וכה\"ג, או שא\"צ לעבודה כי ישנה במציאות נטוע ומושרש בלבו מתולדתו בבטן שהוא הנק' עצם נקודת יהדותו המוטבע כמו טבעית ממש כו'<sup data-n=\"5549\">62</sup>.\n<b>אך</b> הענין הוא דבאמת אין עיקר הציווי על האה' באמרו ואהבת או ובחרת כו' שתלוי' בבחירת האדם שבוחר בטוב ולא ברע אינו רק להביא לגילוי אור נקודת האה\"ר המסותרת הנ\"ל, שכאשר יתעורר האדם בבחירת עצמו בחיים וטוב לדרוש את ה' בכל לבו ודעתו להעמיק בגדולת ה' וכו' עד שיתפעל בלבו לאהבה ותשוקה לדבקה בו ית', אזי ממילא נתעוררה האה\"ר העצמי' הטבעי' המסותרת הנ\"ל בגילוי מהעלמה בנקודת הלב שהיא בלתי מוגבלת כלל, שהרי יכול למסו\"נ על קדה\"ש ולקבל באהבה כל הצרות והיסורים כו' שאין זה בכח אהבה הנולדה מן השכל וטעם בגדולת ה' כמו בק\"ש לפי שעה לבד שחולפת ועוברת כו', והיא באה בשיעור ומדה בלב עכ\"פ רק לפ\"ע שיאיר<sup data-n=\"5550\">63</sup> השכל והשגה אלקי' בכל חד וחד לפום שיעורא דילי' שמכוין בדעתו והשגתו כו'. אך בהתעוררות אהבה זו מתעורר לפי ערך באה\"ר העליונה<sup data-n=\"5551\">64</sup> ממש המסותרת שתבא לגילוי בבחי' בלי גבול כלל, וכמו שרואה אדם בנפשו שמיד אחר הטעם והשכל שהוליד האהבה בק\"ש יתעורר בלבו באה\"ר בלתי גבול שלמעלה מהשכל והטעם שהתחיל בתחלה, ואמנם רק לפ\"ע התעוררות שלו באהבה הנולד מן השכל שנק' דו\"ר שכליים כך מתעורר אהבה הטבעית שז\"ש בכל לבבך ובכל נפשך למעלה מן השכל. אבל ג\"ז אינו בא רק לפ\"ע התעוררות עבודתו ולא יותר כאשר רואה אדם בנפשו שגם אה\"ר הטבעי' לא תבוא בכל עת בשוה כ\"א בשינויים וחילופים כו', והיינו לפי העת והזמן שלא כל העיתים שוות בכשרון לב האדם בעבודתו ויגיעתו במוח ולב כך יתעורר בנקודת הרצון שבלב שנק' רעותא דלבא<sup data-n=\"5552\">65</sup> בבחי' טבעי' ועצמי' באופנים שונים כו' וד\"ל (וכמו שאם יתעורר אדם באהבה",[["5543","56","<b>בצר לך</b>: ואתחנן ד, ל."],["5544","57","<b>אה\"ר</b>: כא: אהב'."],["5545","58","<b>אהב'. . ירושה מאבות</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>."],["5546","59","<b>מאבות שהן המרכבה</b>: נסמן לעיל פ' יתרו רנא, ג."],["5547","60","<b>אהב'. . ירושה. . והעיקר אברהם</b>: ראה גם סידור שער הסוכות רנט, ג [נדפס גם במאמרי אדה\"ז תקס\"ב ח\"א ע' כד]. שע\"ת יח, ד ובהערה 34. אמ\"ב שער התפילין קלז, ד. מאמרי אדה\"א שמות ח\"ב ע' שמט. הנחות תקע\"ז ע' קפז. לעיל פ' וארא סה, ג. לקמן פ' ויקהל תיא, ג. לקו\"ת סוכות עו, ד. שמ\"ע פט, ב."],["5548","61","<b>אברהם. . הרועה הראשון</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' שלח. וש\"נ."],["5549","62","<b>כו'</b>: כא: כנ\"ל."],["5550","63","<b>שיאיר</b>: אכא: שיעור."],["5551","64","<b>העליונה</b>: שם: העצמי'."],["5552","65","<b>רעותא דלבא</b>: זהר וירא ק, א."]]],[2300550190,"בחדוה ושמחה מהתבוננו' הפלאת ערך הגדולה של הבורא ית' המהווה כל העולמות בבחי' מו\"ס<sup data-n=\"5553\">66</sup> כו' אזי גם התפעלות נקודת עצמות הרצון באה\"ר הטבעית הנ\"ל ג\"כ באה בבחי' שמחה וחדוה בה' אחד למעלה מן השכל והטעם שבלתי מוגבל כו', ואם באה התעוררות האהבה שמצד השכל בבחי' ריחוק ושפלות והכנעה שהוא באימה ויראה בבחי' שמאל דוחה כו', כך יתעורר בנקודת עצמות הלב הנ\"ל ג\"כ בבחי' מרירות ושפלות ברוח נשברה בעצם נקודת הלב מצד ריחוק[ו] מה' אחד שזהו ג\"כ כמו טבעי' ממש מוסתר בהעלם נקודת הלב ומתגלה רק לפרקים כנ\"ל). אך כ\"ז הוא שמתעורר אדם בנפשו מצד עצמו שתלוי לפי אופן בחירתו ועבודתו כו' (שזהו שנק' אתעדל\"ת שגורם אתעדל\"ע<sup data-n=\"5554\">67</sup>, ובחי' אתעדל\"ע היינו מה שאה\"ר זו המסותרת מצד הירושה מאברהם שהוא הרועה הראשון שהמשיך אה\"ר הטבעי' המסותרת הנ\"ל בלב כאו\"א מישראל בכל דור ואהבה זו מעורר אתעדל\"ע באה\"ר העליונה כמו אה\"ע אהבתיך<sup data-n=\"5555\">68</sup> וכן אה\"ר אהבתנו<sup data-n=\"5556\">69</sup> וכה\"ג. וידוע דאתעדל\"ע אינה באה רק לפ\"ע אתעדל\"ת<sup data-n=\"5557\">*70</sup> דוקא דרוח אייתי רוח<sup data-n=\"5558\">70</sup> כו' והיינו כפי מעשה עבודת האדם ביגיעתו באוי\"ר שכליי' שלפ\"ע [זה יתעורר] <span data-k=\"pg\">1078</span> ּ בחי' אתעדל\"ע נקודת אה\"ר הירושה מאברהם אוהבי<sup data-n=\"5559\">71</sup> וד\"ל).\n<b>אך</b> הנה בחי' המשכה דאה\"ר דאהרן כה\"ר<sup data-n=\"5560\">72</sup> שנק' ג\"כ רועה ישראל כנ\"ל היינו אה\"ר הנמשכת מלמעלה פתאום על האדם שאינה תלוי' לפ\"ע התעוררות האדם רק<sup data-n=\"5561\">73</sup> נמשכת עליו מלמעלה בדרך מתנה כמ\"ש עבודת מתנה<sup data-n=\"5562\">74</sup> כו', והיינו רק לעורר את האהבה בכנס\"י כמ\"ש עד יערה עלינו<sup data-n=\"5563\">75</sup> רוח ממרום להיות לבנ\"י התעוררות האהבה בין מצד השכל והטעם כו'<sup data-n=\"5564\">76</sup> בין באה\"ר הטבעית הנ\"ל (וכמו בענין הדלקת נרות המנורה שאמר בהעלותך את הנרות<sup data-n=\"5565\">77</sup> שהן כללות נש\"י בכ\"ד<sup data-n=\"5566\">78</sup> שנק' נרות הוי'<sup data-n=\"5567\">79</sup> ממש כי חלק ה' עמו<sup data-n=\"5568\">80</sup> כו', ואהרן כה\"ג הוא המעלה לנש\"י שיתעוררו באה\"ר לה' א' ממילא ומאליו כניצוץ שהוא נמשך אחר השלהבת מצד [ש]השלהבת מקרוב שמושך את הניצוץ ליכלל בה, כך א' אל מול פני המנורה<sup data-n=\"5569\">81</sup> כו' שהוא להעלות [ו]לימשך לב נש\"י שיוכללו במאור שהוא אוא\"ס<sup data-n=\"5570\">82</sup> ב\"ה שזהו מול פני המנורה יאירו כמו כי אתה נרי<sup data-n=\"5571\">83</sup> כו' כי אתה תאיר נרי<sup data-n=\"5572\">84</sup> שאהרן אותיות נראה<sup data-n=\"5573\">85</sup> כו', כמבואר במ\"א שז\"ש משכני אחריך נרוצה<sup data-n=\"5574\">86</sup> לשון רבים ולא א' ארוצה, כי בהעלות אהרן כה\"ר",[["5553","66","<b>מו\"ס</b>: אכא: ממלא וסובב."],["5554","67","<b>אתעדל\"ת. . אתעדל\"ע</b>: נסמן לעיל פ' יתרו רנט, ב."],["5555","68","<b>אה\"ע אהבתיך</b>: ירמי' לא, ב [ושם: ואהבת — נסמן לעיל פ' וארא סב, ג]."],["5556","69","<b>אה\"ר אהבתנו</b>: ברכת ק\"ש שחרית (נוסח אשכנז)."],["5557","*70","<b>דאתעדל\"ע. . לפ\"ע אתעדל\"ת</b>: ראה שע\"ת קלד, סע\"ג ואילך ובהנסמן במ\"מ לשם."],["5558","70","<b>דרוח אייתי רוח</b>: נסמן לעיל פ' יתרו רנא, א."],["5559","71","<b>מאברהם אוהבי</b>: ישעי' מא, ח."],["5560","72","<b>כה\"ר</b>: אכא: כה\"ג."],["5561","73","<b>רק</b>: כא: מלמטה כלל אלא."],["5562","74","<b>עבודת מתנה</b>: קרח יח, ז."],["5563","75","<b>עד יערה עלינו</b>: ישעי' לב, טו."],["5564","76","<b>כו'</b>: א: כנ\"ל. כא: הנ\"ל."],["5565","77","<b>בהעלותך את הנרות</b>: בהעלותך ח, ב. ראה גם לעיל פ' יתרו רסט, ב הערה 10."],["5566","78","<b>בכ\"ד</b>: אכא: בכל דור."],["5567","79","<b>נש\"י. . נרות הוי'</b>: ראה לקמן שסח, ב. פ' ויקהל שצח, ג. משלי כ, כז. ש\"א כב, א."],["5568","80","<b>כי חלק ה' עמו</b>: האזינו לב, ט."],["5569","81","<b>אל מול פני המנורה</b>: בהעלותך שם."],["5570","82","<b>אוא\"ס</b>: אכא: עצמו' א\"ס."],["5571","83","<b>כי אתה נרי</b>: שמו\"ב כב, כט."],["5572","84","<b>כי אתה תאיר נרי</b>: תהלים יח, כט."],["5573","85","<b>שאהרן אותיות נראה</b>: ראה זהר אמור קג, א במק\"מ ובהרמ\"ז שם. מאמרי אדה\"א ויקרא ח\"ב ע' תשסז. וש\"נ. שמות ח\"ב ע' שמ. וש\"נ."],["5574","86","<b>משכני אחריך נרוצה</b>: שה\"ש א, ד. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380085\" data-slug=\"likkutei-torah\" data-id=\"4001380085\">לקו\"ת ויקרא ב, ד</a>. מאמרי אדה\"ז אתהלך לאזניא ע' קסט. כתובים ח\"ב ע' כט."]]],[2300550222,"לנש\"י לעוררם בהע[לאו'] מ\"נ שנק' כח ה[מ]ע[לה] מ\"נ כו'<sup data-n=\"5575\">87</sup> זהו משכני שתמשיך לבבות דכנ\"י כאב המושך ל[ב] בנו אחריו מצד שנמשך לשרשו כו', ואז אחריך נרוצה ב' אהבות הנ\"ל אהבה זוטא שנולדה מן השכל דנשמה ואה\"ר הטבעי' שיבאו שניהם יחד מן ההעלם לגילוי. וזהו יפה את רעייתי כתרצה<sup data-n=\"5576\">88</sup> או<sup data-n=\"5577\">89</sup> כאשר יתחברו ב' הרצונות יחד שהוא רצה\"ע דאה\"ר [ד]כה\"ג המעורר לרצה\"ת שבנש\"י בנקודת הלב כו' כמבואר במ\"א וד\"ל). וזהו פי' לאהבה את ה' כו' בתוס' ה' דאם הי' או' לאהוב הי' משמע רק כפי התעוררות אהבה באדם שבא מכח עצמו כנ\"ל באה\"ר הטבעי' ואה' השכלי', אבל לאהבה בה\"[א] היינו ענין פועל יוצא להפעיל ולעורר את האהבות הנ\"ל בלב כנס\"י שאינה נגבלת בכלי הלב והמוח כלל, וזהו הה\"[א] שהוא בחי' מקיף דהבל הלב שהוא בא בהעלם גדול רק לעורר את האהבה שנמשכת מלמעלה בלב (וכענין משכנ\"י והשיבנו ה' אליך<sup data-n=\"5578\">90</sup> כענין ב\"ק מכרזת בכ\"י שובו בנים שובבים<sup data-n=\"5579\">91</sup> כו' שעושה בחי' התעוררות התשובה בהעלם בלב כ\"א<sup data-n=\"5580\">92</sup> למעלה מן הבחירה לגמרי כו' וכנ\"ל<sup data-n=\"5581\">93</sup> ).\n<b>והנה</b> בפסוק ואהבת א' ג' מדרגות בכל לבבך ובכל נפשך ובכל מאדך, והיינו ג' מיני אהבה הנ\"ל, א' אהבה שנולדה מצד השכל וההשגה אלקית הנ\"ל, והב' אה\"ר הטבעי' המסותרת שלמעלה מן השכל והטעם שזהו בכל נפשך כו', והג' אה\"ר העליונה שבאה מלמעלמ\"ט לעורר את האהבה והתשוקה בלב כאו\"א למעלה מן הבחירה ורצון שבלב מצד עצמו כנ\"ל ז[הו] שא' בכל מאד\"ך למעלה מהכלי המוגבל ברצון שבלב שמצד עצמו כלל. והוא מ\"ש בפ' שני' לאהבה את ה' בכל לבבכם<sup data-n=\"5582\">94</sup> כו' אע\"פ שלא נז' שם בכל מאדכם, כי נמשך מאה\"ר דכה\"ג בלב כאו\"א לענין מעהמ\"צ בפו\"מ שזהו הה\"[א] דאהבה כנ\"ל וד\"ל. וההפרש בין ג' מיני אהבות הללו היינו מה שהאהבה את הוי' אלקיך בכל <span data-k=\"pg\">תקלט</span> ּ לבבך ובכל נפשך זהו בשם הוי' ואלקים שהוא בחי' ממכ\"ע וסוכ\"ע<sup data-n=\"5583\">95</sup>, כידוע דשם הוי' הוא בסובב ומקיף לעולמות דבי\"ע שלמעלה מן הגבלת כלי ההשגה דמלאכים ונשמות דבי\"ע וע\"כ או' קדוש הוי'<sup data-n=\"5584\">96</sup> כו' שקדוש ומובדל בערך מכל השגה ותפיסא אבל בחי' ממכ\"ע זהו הבא בגדר ותפיסא והשגה איך שהוא מקור כל התהוות בריאה מאין ליש כו' (והתפעלות האהבה שבא מהשגה ותפיסא זו באה בגבול ומדה",[["5575","87","<b>כו'</b>: אכא: כנ\"ל."],["5576","88","<b>יפה את רעייתי כתרצה</b>: שה\"ש ו, ד. ראה גם מאמרי אדה\"ז תקס\"ד ע קלה. שע\"ת מה, ג ובהערה 16. לקמן פ' ויקהל תלד, ב."],["5577","89","<b>או</b>: א: פי'. כא: ליתא."],["5578","90","<b>והשיבנו ה' אליך</b>: איכה ה, כא."],["5579","91","<b>ב\"ק. . שובו בנים שובבים</b>: ירמי' ג, יד. כב. ראה זהר נשא קכו, א. הנסמן לעיל פ' וארא עח, ג."],["5580","92","<b>כ\"א</b>: א: כאו\"א."],["5581","93","<b>וכנ\"ל</b>: כא: וד\"ל."],["5582","94","<b>לאהבה את ה' בכל לבבכם</b>: עקב יא, יג [בדילוג]."],["5583","95","<b>הוי' ואלקים. . ממכ\"ע וסוכ\"ע</b>: ראה גם לעיל עג, ב. וש\"נ."],["5584","96","<b>קדוש הוי'</b>: ישעי' ו, ג. ראה גם לעיל פ' וארא נח, ב."]]],[2300550254,"לפ\"ע ההשגה, אבל בחי' סוכ\"ע שמקיף לעולמות המוגבלי' שם אין תפיסא והשגה משיג<sup data-n=\"5585\">97</sup> בבחי' או\"פ רק מרחוק הוי' נראה לי<sup data-n=\"5586\">98</sup> וע\"כ התפעלות האהבה מזה כך<sup data-n=\"5587\">99</sup> היא בלי גבול ומדה. וזהו האה\"ר מסותרת הנ\"ל שבלתי מוגבלת כלל לפי שבאה ממקום ומדרגה שלמעלה מן הגבול והשכל והשגה כו' וכמאמר דלמחת\"ב כלל<sup data-n=\"5588\">100</sup> וכתי' אני הוי' לא שניתי<sup data-n=\"5589\">101</sup> כו' דאין שינוי לפני שם הוי' דבחי' סובב הנ\"ל בין קודם שנבה\"ע לאחר שנברא כמ[ו] שאו' אתה הוא<sup data-n=\"5590\">102</sup> כידוע, לפי שאין כל ההשתל' העולמות תופס מקום כלל דכולא קמי' כלא חשיבא<sup data-n=\"5591\">103</sup> ומהתבוננות זאת תבוא בנפש האדם התפעלות אה\"ר למעלה מן השכל וההשגה לגמרי והוא מה שמתעורר אה\"ר המסותרת הנ\"ל בבחי' טבעי' ועצמי' לשם הוי' דוקא, וזהו ואהבת את הוי' אלקיך שזהו ירושה מאברהם אוהבי שהאמין בה'<sup data-n=\"5592\">104</sup> כו' ויקרא בשם הוי' אל עולם<sup data-n=\"5593\">105</sup> כו'. אך האהבה הג'<sup data-n=\"5594\">106</sup> בכל מאדך זהו בחי' מקיף למקיף דאה\"ר ואה\"ע הנ\"ל שלמעלה גם מבחי' סוכ\"ע, כי גם בחי' סוכ\"ע בערך הגבלה דמקיף וסובב לעלמין עכ\"פ שהן ג' עולמות כו', כמקיף דחומה לעיר וכמו הכלל אל הפרט כענין מח' א' שצופה ומביט<sup data-n=\"5595\">107</sup> בכלל לכל וא\"ש דהוי עלמא<sup data-n=\"5596\">108</sup> כו' כידוע, אבל מהו\"ע ית' ממש כמו שהוא לבדו מרומם ומתנשא לגמרי גם מהיות בחי' מקור כללי בבחי' סובב כו'. והיינו מ\"ש מי כהוי' אלקינו בכל קראנו<sup data-n=\"5597\">109</sup> אליו ולא למדותיו<sup data-n=\"5598\">110</sup> אפי' לע\"ס הגנוזות<sup data-n=\"5599\">111</sup> בעצמות המאציל אלא למהו\"ע א\"ס ב\"ה ממש כמ\"ש אם ישים אליו לבו<sup data-n=\"5600\">112</sup> אליו דוקא וכן אליך ה' נפשי<sup data-n=\"5601\">113</sup> כו', והוא עיקר מצות מס\"נ באה\"ר לאח\"פ לבדו כמו מי לי בשמים ועמך<sup data-n=\"5602\">114</sup> כו' בגעה\"ע ועוה\"ב ולא בארץ כ\"א לבדך במהו\"ע ית' ממש למחתב\"כ אפי' מחשבה ורצון דאה\"ר הנ\"ל, כ\"א בבחי' אה\"ר הבאה מלמעלה פתאום לעורר את האהבה בכנס\"י בבחי' מקיף בהעלם כו' שמזה יבאו לבחי' מס\"נ באח\"פ ממש לפי שבאה\"ר זו אין הדביקות האמיתי רק במהו\"ע ית' ממש דוקא וד\"ל (וזשארז\"ל דכנ\"י שאלה שלא כהוגן<sup data-n=\"5603\">115</sup> ויבא כגשם לנו<sup data-n=\"5604\">116</sup> שזהו אה\"ר העליונה שבאה לפ\"ע אתעדל\"ת כו' באה\"ר ואה\"ע בהע[לאת] מ\"נ ביגיעה במוח ולב בהשגה דיחו\"ע ויחו\"ת ממו\"ס כו', אבל הקב\"ה השיבם כהוגן אהי' כטל לישראל<sup data-n=\"5605\">117</sup> דטל לא פסיק לעלמין<sup data-n=\"5606\">118</sup> כו' שזהו כח האה\"ר דאהרן כה\"ג העליון שנותן כח [ועוז] לנש\"י להתעורר באה\"ר ואה\"ע הנ\"ל שנק' כח ה[מ]ע[לה] מ\"נ [כנ\"ל] וד\"ל).",[["5585","97","<b>תפיסא והשגה משיג</b>: כא: ההשגה מושג."],["5586","98","<b>מרחוק הוי' נראה לי </b>[אכא: לו]: ירמי' לא, ב."],["5587","99","<b>כך</b>: שם: גם."],["5588","100","<b>דלמחת\"ב כלל</b>: ת\"ז בהקדמה (יז, א)."],["5589","101","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["5590","102","<b>אתה הוא </b>[אכא: ניתוסף: (קודם) כו']: ראה תפלת השחר. של\"ה ג, ב."],["5591","103","<b>דכולא קמי' כלא חשיבא</b>: נסמן לעיל פ' משפטים רעז, ב."],["5592","104","<b>מאברהם. . שהאמין בה'</b>: לך טו, ו."],["5593","105","<b>ויקרא בשם הוי' אל עולם</b>: וירא כא, לג [בדילוג]."],["5594","106","<b>הג'</b>: א: הג' בחי'. כא: הנ\"ל בבחי'."],["5595","107","<b>מח' א' שצופה ומביט</b>: ראה ברכת זכרונות. לעיל פ' שמות מח, ב הערה 207."],["5596","108","<b>וא\"ש דהוי עלמא</b>: ראה ר\"ה לא, א. הנסמן במאמרי אדה\"א בראשית ע' נג."],["5597","109","<b>מי. . בכל קראנו אליו</b>: ואתחנן ד, ז [בדילוג]."],["5598","110","<b>אליו </b>[כא: ניתוסף: אליו]<b> ולא למדותיו</b>: ראה גם לעיל פ' וארא עז, רע\"א ובהערה 314."],["5599","111","<b>לע\"ס הגנוזות</b>: נסמן לעיל פ' יתרו רסה, ד."],["5600","112","<b>אם ישים אליו לבו</b>: איוב לד, יד."],["5601","113","<b>אליך ה' נפשי</b>: תהלים כה, א (פו, ד)."],["5602","114","<b>מי לי בשמים ועמך</b>: תהלים עג, כה. ראה גם לעיל שנו, ב. וש\"נ."],["5603","115","<b>דכנ\"י שאלה שלא כהוגן</b>: ראה תענית ד, א."],["5604","116","<b>ויבא כגשם לנו</b>: הושע ו, ג."],["5605","117","<b>אהי' כטל לישראל</b>: שם, יד, ו."],["5606","118","<b>דטל לא פסיק לעלמין</b>: תענית ג, א."]]],[2300550284,"<b>והנה</b> ארז\"ל משחרב בהמ\"ק מחיצה של ברזל<sup data-n=\"5607\">119</sup> מפסקת בין ישראל לאביהם שבשמים <span data-k=\"pg\">1080</span> ּ כמו עוונותיכם מבדילים ביניכם<sup data-n=\"5608\">120</sup> כו', ויש לדקדק מש\"א בין ישראל לאביהם כו' ולא א' בין אביהם שבשמים לישראל, דמשמע מזה דמחיצה של ברזל זו היא נעשית מישראל דוקא מצד עוונותיכם<sup data-n=\"5609\">121</sup> שלהם שעשו הסתר והעלם לעצמם שא\"א שיאיר אור ה' בנשמתם. וזהו הנה עומד אחר כתלינו<sup data-n=\"5610\">122</sup> כותל שעשינו לעצמינו מצד העוונות המבדילים כו', וע\"כ אין מחיצה [זו] מפסקת רק בין ישראל לאביהם שבשמים אבל א\"א ל[ומר] שמחיצה זאת מפסקת בין אביהם שבשמים לישראל דקמי' עצמותו ית' [הרי א'] גם חשך<sup data-n=\"5611\">123</sup> לא יחשיך ממך כלל, וגם מחיצה של ברזל אינה קרוי' בשם מחיצה מפסקת לו (שאע\"פ שא' עומד אחר כתלינו זהו רק לגבי דידן כו') דלא שייך לומר מחיצה מפסקת רק בין ישראל לאביהם כו' שמחיצה זו מפסקת ומבדלת בעדם, אבל לא יתכן לומר שמחיצה זו יסתיר לאור שם הוי' בעצמו ח\"ו לבלי יראה אורו למטה שהרי אין דבר חוץ ממנו ח\"ו<sup data-n=\"5612\">124</sup>, ואין שינוי וגרעון אור או הסתלקות וצמצום [ב]אור האלקי מצד עצמו ומהותו ח\"ו כי הרי א' אני הוי' לא שניתי כלל וכלל, רק השינוי הוא לגבי המקבלים מצד העדר הכלי שלהם שנפגם ונעשה עי\"ז בחי' מחיצה מפסקת לבלתי יכנס ויאיר אור האלקי בהם בבחי' גילוי אור וחיות ממש מפני המחיצה המפסקת [עליהם] כו' וד\"ל (וזהו עד\"מ הארת אור דנפש בגוף שאין גרעון האור בעצם כאור הראי' בעין רק בהעדר הכלי כשנתקלקל העין שלא נמשך בחומר העין מאור הראי', אבל באור הראי' עצמה אין שינוי וגרעון כלל. אך עכ\"ז אין המשל [הזה] דומה לנמשל שבמחיצה של ברזל שנעשה מן העוונות אינו נק' כיסוי או קלקול כלל לגבי אור האלקי שמאיר גם בחושך כמו באור ממש כנ\"ל<sup data-n=\"5613\">125</sup> וד\"ל) (ועכ\"ז עומד אחר כתלינו משגיח מן החלונות מציץ מן החרכים דוקא ולא שיוסר הכותל והמחיצה לגמרי כי השגחתו דרך [בחי'] חלונות וחרכים הללו הוא שמאיר להיות התעוררות תשובה בכנ\"י להחזירם אליו כו').\n<b>והנה</b> מש\"א [ל'] מחיצה של ברזל דוקא שכוונתו בזה שהוא חזק וקשה כברזל דוקא, הענין הוא שמרמז בזה על בחי' הקליפה דעמלק שחזק וקשה כברזל ממש יותר מכל הז\"מ דק\"נ כמו הכנעני והחיתי<sup data-n=\"5614\">126</sup> כו', כי הנה בעמלק אמר ראשית גוים עמלק<sup data-n=\"5615\">127</sup> שנק' ראשית ומקור לז\"מ דק\"נ כו' (והוא מלך הא' בל\"ע בן<sup data-n=\"5616\">128</sup> בעו\"ר<sup data-n=\"5617\">129</sup> שמבלי\"ע לקד\"ש<sup data-n=\"5618\">130</sup> כו' בחי' דעת<sup data-n=\"5619\">131</sup> דק\"נ, שזהו בחי' הרגשת עצמו ביותר עד שלא יוכל לזוז ממקומו כלל",[["5607","119","<b>משחרב בהמ\"ק מחיצה של ברזל</b>: נסמן לעיל שנו, ב."],["5608","120","<b>עוונותיכם מבדילים ביניכם</b>: ישעי' נט, ב [בדילוג — ראה לקמן שסט, א. שערי אורה מה, א הערה 13. ושם צ\"ל: נט, ב]."],["5609","121","<b>עוונותיכם</b>: אכו: עו[ו]נות."],["5610","122","<b>הנה עומד אחר כתלינו</b>: שה\"ש ב, ט. ראה גם לעיל שלט, ב. מאמרי אדה\"א נ\"ך ע' תח."],["5611","123","<b>גם חשך</b>: תהלים קלט, יב."],["5612","124","<b>ח\"ו</b>: כא: ית'."],["5613","125","<b>כנ\"ל</b>: א: כו'."],["5614","126","<b>הז\"מ דק\"נ כמו הכנעני והחיתי</b>: נסמן לעיל פ' יתרו ער, ג."],["5615","127","<b>ראשית גוים עמלק</b>: נסמן לעיל שנו, ג."],["5616","128","<b>עמלק. . בל\"ע בן בעו\"ר</b>: ראה לקו\"ת להאריז\"ל בלק כד, כ. מאמרי אדה\"א נ\"ך ע' יב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670489\" data-slug=\"torat-chaim\" data-id=\"2300670489\">תורת חיים בראשית טז, ב</a>."],["5617","129","<b>מלך הא' בל\"ע בן בעו\"ר</b>: וישלח לו, לב."],["5618","130","<b>בל\"ע. . שמבלי\"ע לקד\"ש</b>: ראה הנסמן לעיל פ' שמות מב, ב הערה 247."],["5619","131","<b>בל\"ע בן בעו\"ר. . דעת</b>: ראה גם לעיל פ' שמות מב, ב. וש\"נ."]]],[2300550312,"וכלל שהוא מקור לכל התאוות הרעות בבחי' מדות דחו\"ג דק\"נ כו' כמו מי הגיד לך<sup data-n=\"5620\">132</sup> כי עירום אתה כו'<sup data-n=\"5621\">133</sup> המ\"ן הע\"ץ כו' שזשארז\"ל המן מן התורה מנין<sup data-n=\"5622\">134</sup> כו' שהוא קליפה דעמלק שהוא רק החוצפא וההתנשאות (כמשי\"ת). דהנה עיקר קליפה דעמלק אינו רק החוצפה ועזות קשה שהוא תוקף הנצחון ועקשות קשה ביותר, דהיינו רק מצד גסות רוחו וגובה לבו הרמה עליו הוא תקיף גדול בדעתו ולבו בעקשות ונצחון ביותר עד שיעיז פני הגדול ממנו הרבה כמלך ושר גדול ולא יפול לבו כלל וכלל לפי שקשה <span data-k=\"pg\">תקמ</span> ּ הוא כארז ממש לבלי יכנע לבבו מכל כו'. וזהו החוצפא שבלא טעם כלל רק התנשאות יתירה בלתי מוגבלת כלל, כי גם שיודע באמת פחיתות ערכו השפל מאד ויודע ומשיג רוממות המלך ושר וכה\"ג עכ\"ז בחוצפא יתירה מצד עוצם גסות רוחו יעיז פני הגדול ולא יפול לבבו כלל (וזהו רק מעוצם הרגשת עצמו ביותר כנ\"ל). וכך הי' בעמלק כשיצא ללחום עם ישראל כמ\"ש ויבא עמלק<sup data-n=\"5623\">135</sup> כו', הגם שידע ושמע כל האותות ומופתים שהי' במצרים [ו]אשר נטבעו פרעה וחילו בי\"ס והי' גילוי [אלקו'] כ\"כ בישראל כשיצא[ו] ממצרים בעמוד אש וענן כו' עד שנמוגו כל יושבי כנען כו' ועמלק לא נפל לבו מזה כלל ויצא ללחום, שזהו רק חוצפא והתנשאות יתירה שבאה בתוקף ועקשות ונצחון עד שקשה כארז לבלי יפול לבבו מכל וכל כו' ומלבד שלא נפל לבו כלל אלא התחזק בעצמו ביתר מכפי מדתו למס\"נ ועמו במלחמה זו אולי יוכל לעמוד נגד ישראל עם רב וחזק הרבה יותר ממנו<sup data-n=\"5624\">136</sup>, שזהו רק מצד עוצם שנאתו וקנאתו בוער בו על עוצם גילוי אור האלקי בישראל בהתנשאות גדולה כזו שיצאו ממצרים ביד רמה ובעמוד אש וענן ה' הולך לפניה\"ם כו' שלא הי' יכול לסבול התנשאות אלקי הזאת. כי זהו טבע הגיאות וגסה\"ר בחוצפא ועזות קשה ביותר שלא יכלו לסבול כלל התנשאו' של זולתם יהי' מי שיהי' אף שראוי לזה כמלך ושר ואדם חשוב וגדול בעצם, אך לא יוכל לסבול כל בחי' התנשאות אמיתי' מזולתו עד שיחרה לו ויגיע ד\"ז<sup data-n=\"5625\">137</sup> לעצם נקודת חיותו עד אשר יוכל למס\"נ וכל כחו יאבד בכל אשר יוכל להפיל [ל]זולתו שמתנשא ביותר כאלו נגע בעצם חיותו להמיתו בפו\"מ ויותר מזה, שזהו באמת פלא גדול בטבעית בנ\"א שאינו מצוי בטבע איש שירדוף לחבירו לחייו כ\"א כאשר נגע לו בחייו או בבנו ואביו ואשר לו גזל ורצח וכה\"ג. אבל כאשר לא חטא לו חבירו ולא עשה לו מאומה, הגם שטבע האיש רוצח ואיש דמים ואכזרי ושארי מדות רעות לא יבא לרדוף לחיי חבירו בחנם על לא דבר אע\"פ שרואה בו התנשאות בעושר וגדולה יתירה שיקנא בו כאבימלך ביצחק<sup data-n=\"5626\">138</sup> עכ\"ז לא יבא לידי",[["5620","132","<b>מי הגיד לך</b>: בראשית ג, יא."],["5621","133","<b>כו'</b>: כ\"ה גם באכא."],["5622","134","<b>המן מן התורה מנין</b>: חולין קלט, ב."],["5623","135","<b>ויבא עמלק</b>: בשלח יז, ח."],["5624","136","<b>ישראל עם רב וחזק הרבה יותר ממנו</b>: ראה גם מושב זקנים בשלח יז, ט. ולהעיר מספר הישר (שם)."],["5625","137","<b>ד\"ז</b>: אכא: דבר זה."],["5626","138","<b>שיקנא בו כאבימלך ביצחק</b>: תולדות כו, יד ואילך."]]],[2300550337,"שנאה כ\"כ לרודפו ולהפילו כלל. אך ורק מי שיש לו מדה זו דגסה\"ר וחוצפא יתירה כמו בחי' עמלק הנ\"ל הוא שיתפעל בקנאה ושנאה גדולה ועצומה על זולתו כשמתנשא כמו כשנעשה ראש ושר ועשיר גדול וכה\"ג, עד שיצא בכל כחו להפילו במס\"נ ממש אעפ\"י שלא עשה לו מאומה כו' מפני שמאד לא יוכל לסבול כל דבר המתנשא חוץ ממנו כו' (ומטעם הנ\"ל שלא יוכל לסבול חוץ מעצמו מצד תוקף הרגשת עצמו ביותר שמפ[ני] ז[ה] הוא קשה כארז וחצוף גדול). משא\"כ מי שאין לו מדה זו דגסות וחוצפא יתירה שלמעלה מן הטעם, אף שגרוע יותר משאר מדות רעות בתאוות חומריות וכעס ורציחה כו' עכ\"ז לא יתפעל כ\"כ מענין התנשאו' של זולתו כאשר לא עש[ה] לו מאומה כו' אף שמתקנא בו כו' כנ\"ל. וזהו עיקר האות והסימן לקליפה דעמלק שנק' ראשית גוים למעלה מקליפה דעשו וישמעאל חו\"ג דק\"נ<sup data-n=\"5627\">139</sup>, שאע\"פ שהן מדות רעות לא יהי' בהם <span data-k=\"pg\">1082</span> ּ החוצפא והגסות להיות שונא כ\"כ להמתנשא זולתם כמו בישמעאל שלא יצא ללחום עמהם במס\"נ כ\"כ רק בחי' קליפה דעמלק דוקא, מפני שזהו טבע הגיאות וגסה\"ר שמאד לא יוכל לסבול כ[ל] ד[בר] המתנשא זולתו. ומה גם שהתנשאות דישראל הי' בבחי' גילוי אלקות, שהוא בבחי' שם מ\"ה דתו\"מ בבחי' הביטול לאין האלקי בתכלית שזהו היפוך גמור המנגד לקליפה דעמלק ע\"כ הי' לו קנאה ושנאה יתירה לעמוד לנגדם כו' (כמשי\"ת) וד\"ל.\n<b>וזש\"א</b> כי יד על כס י\"ה<sup data-n=\"5628\">140</sup> מלחמה לה' בעמלק כו', שקליפה זו דעמלק הוא בכל דור ודור ומלחמה לה' בעמלק בתמידות בכ\"ד. ומה שנק' כ\"ס י\"ה כמ\"ש כי יד על כ\"ס י\"ה זהו ענין מחיצה של ברזל הנ\"ל שמפסקת בין ישראל כו' שנק' כ\"ס י\"ה שמכסה ומסתיר ומפסיק על שם י\"ה דשם הוי' [ש]לא יוכל להאיר בנש\"י מלמעלה למטה, מפני שענין מחיצה זו של ברזל זהו [בחי'] קליפה קשה דעמלק ששם<sup data-n=\"5629\">141</sup> גם בכאו\"א מישראל ביצה\"ר שבנה\"ט בלב החומרי שנק' לב האבן<sup data-n=\"5630\">142</sup> שקשה כאבן וכברזל, דגם שיודע את רבונו כו' ומכיר את בוראו היטב בהשגות והתבוננו' בגדולת ה' כמו ביחו\"ע ויחו\"ת ונפלאות ה' וחסדיו הרבים בהשגחה פרטי' עליו ועל כל האדם בכלל ובפרט כאילו רואה בראי' חושי' ממש, עכ\"ז לא ניזוז לבו ממקומו כלל להיות בבחי' ביטול ממש לאלקים חיים ברצון ומדות ומדו\"מ אלא הוא במקומו ומעמדו בתוקף וגסה\"ר בבחי' יש נפרד בפר\"ע ממש. כי זהו רק מצד הגסות וחוצפא יתירה בלא טו\"ד גם שיודע פחיתת ערכו השפל שהוא",[["5627","139","<b>דעשו וישמעאל חו\"ג דק\"נ</b>: ראה מאמרי אדה\"א הנחות תקע\"ז ע' שדמ. וש\"נ."],["5628","140","<b>כי יד על כס י\"ה</b>: בשלח יז, טז."],["5629","141","<b>ששם</b>: אכא: שישנו."],["5630","142","<b>לב האבן</b>: יחזקאל יא, יט. לו, כו."]]],[2300550362,"עפר וסופו רמה ותולעה ולא יכול להכנ[י]ע לבבו לפני קונו באמת, כי מצד הרגשת עצמו בגסות ביותר לא יזוז ממקומו מכל כו' כנ\"ל. ולא עוד אלא ששונא מאד לכל אשר לבבו נשא לעבודת ה' בהתפעלות ודביקות אמיתי' ובגילוי אור האלקי בנפשו בתו\"מ בהתנשאות אלקות ממש כו', שמאד לא יוכל לסבול דבר המתנשא ובפרט בבחי' אלקות כמו בק\"ש ותפלה ובתו\"מ שהוא בבחי' אין האלקי שהוא מנגד לקליפה זו דעמלק שנזרע גם בנש\"י בגופי' בכל דור ודור (והיינו שנק' עזי פנים וגסה\"ר כהמן ועמלק כו' ששתלן בכל דור<sup data-n=\"5631\">143</sup> ונק' חוצפא דרא<sup data-n=\"5632\">144</sup> שקשים כארז ונק' ג\"כ אבירי לב הרחוקים מצדקה<sup data-n=\"5633\">145</sup> שהוא בחי' המל'<sup data-n=\"5634\">146</sup> בגילוי אור האלקי כו'. והוא האות והסימן שרואים באותן אנשים שהן שונאים לכל איש מישראל שגבה לבו בדרכי ה' והולך בתמידות<sup data-n=\"5635\">147</sup> בבחי' פנימי' הלב והמוח בעבודה תמה בהתלהבות הלב בתפלה ובתו\"מ שלא יוכל לסבול כלל וכלל, ובפרט לנשברי לב בתשובה ואשר הן בבחי' הביטול לאין האלקי שונאים מאד עד שכל מגמתם להאבידם בכל אשר יוכלו כמעט במס\"נ כמ\"ש אמרו אחיכם<sup data-n=\"5636\">148</sup> שונאיכם מנדיכם כו', וזהו שנק' מואס באחרים שעושין<sup data-n=\"5637\">149</sup> כו'. ואמנם אין בחי'<sup data-n=\"5638\">150</sup> זו רק בבחי' זרע עמלק, שזהו בחי' החוצפא וגסות שנגע לחייו ממש מה שיש בחי' גילוי אלקות בהתנשאות זולתו כנ\"ל שמהן הן בחי' הערב רב<sup data-n=\"5639\">151</sup> שבישראל <span data-k=\"pg\">תקמא</span> ּ ובאוה\"ע הן שונאי ישראל בתכלית לומר לכו ונכחידם מגוי<sup data-n=\"5640\">152</sup> ולא יזכר כו', ומטעם הנ\"ל כהמן ממש שא' ישנו עם אחד<sup data-n=\"5641\">153</sup> מפוזר כו' ודתיהם שונות כו'. משא\"כ מי שאין בו מבחי' עמלק כלל, הגם שהוא מלא תאוות רעות כעריות וש\"ד וכל שאר העבירות לא יגע לנפשו לשנוא כ\"כ לאותן שהן יראי ה' ועובדי' בקדושה וטהרה יתירה, אדרבה יכנע לבבו לפניהם כו' כי לא איכפת לו כלל מזה כנ\"ל ) (ומ\"ש אחיכם שונאיכם כו' לפי ששנאה עצומה זו אינה רק מחמת קנאה גדולה כקנאת נחה\"ק<sup data-n=\"5642\">154</sup>, וכן קנאת השטן תמיד על גילוי אלקות בהתנשאות ופרהסיא בבחי' יש גדול כמו במ\"ת שהי' גילוי אלקות ביותר בבחי' פב\"פ כו' נתקנא השטן<sup data-n=\"5643\">155</sup> מאד והחטיאם בעגל להפילם כו', וכן נתן עיניו במקדש ראשון ושני<sup data-n=\"5644\">156</sup> כו'. וכ\"ז בא דוקא מצד שיש לו קירוב הערך ויחוס לענין זה שהוא גילוי אלקות כו', שאם הי' רחוק מזה לגמרי לא הי' מתקנא כ\"כ כענין כלום מתקנא<sup data-n=\"5645\">157</sup> אלא חכם בחכם דוקא וכן עשיר בעשיר כו', וא\"כ זהו הוראה על שרשם שקרובים יותר לאלקות ע\"כ מתקנאים ושונאים ביותר לכל עובדי ה' בגילוי ביותר כו'. וז\"ש אחיכ\"ם שונאיכ\"ם",[["5631","143","<b>עזי פנים. . ששתלן בכל דור</b>: ראה חגיגה יד, רע\"א. וראה גם לעיל פ' וארא פב, ג."],["5632","144","<b>חוצפא </b>[א: תקיפי. כא: חצפי]<b> דרא</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' ו. וש\"נ. שע\"ת י, ד הערה 12."],["5633","145","<b>אבירי לב הרחוקים מצדקה</b>: ישעי' מו, יב. ראה גם שע\"ת סג, ד ובהערה 26."],["5634","146","<b>מצדקה. . המל'</b>: ראה זהר אחרי עב, א. שע\"ת י, ד ובהערה 14."],["5635","147","<b>בתמידות</b>: אכא: בתמימות."],["5636","148","<b>אמרו אחיכם</b>: ישעי' סו, ה."],["5637","149","<b>מואס באחרים שעושין</b>: רש\"י בחוקותי כו, טו מתו\"כ שם."],["5638","150","<b>בחי'</b>: כא: מדה."],["5639","151","<b>עמלק. . הערב רב</b>: ראה זהר בראשית כח, ב. כז, ב. ת\"ז סתס\"ט (קיט, ב). מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שצא."],["5640","152","<b>לכו ונכחידם מגוי</b>: תהלים פג, ה."],["5641","153","<b>ישנו עם אחד</b>: אסתר ג, ח."],["5642","154","<b>כקנאת נחה\"ק</b>: ראה סנהדרין נט, ב. שעה\"י קמז, ב ובהערה 25."],["5643","155","<b>במ\"ת. . נתקנא השטן</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תעח ואילך. הנחות תקע\"ז ע' צז. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670480\" data-slug=\"torat-chaim\" data-id=\"2300670480\">תו\"ח בראשית טז, א</a> ובהערה 4."],["5644","156","<b>נתן עיניו במקדש ראשון ושני</b>: סוכה נב, סע\"א. ראה גם מאמרי אדה\"א בראשית ע' צח. וש\"נ."],["5645","157","<b>כלום מתקנא</b>: ע\"ז נה, א."]]],[2300550382,"מנדיכם אחיכ\"ם ממש כו' וכן עשו א\"ח ליעקב<sup data-n=\"5646\">158</sup> בן יצחק כו' ע\"כ קנאתו ושנאתו יותר כו' עד שלאום מלאום כו' ולא נתמלא צור<sup data-n=\"5647\">159</sup> כו') (וכמבואר במ\"א<sup data-n=\"5648\">160</sup> ) שזהו כמו ענין השליא של הולד<sup data-n=\"5649\">161</sup> שנעשה מפסולת הדמים דמ\"ן כו') וזש\"א למען שמי דוקא יכבד ה'<sup data-n=\"5650\">162</sup> וזהו שעתיד לעשות סוכה<sup data-n=\"5651\">163</sup> כו' אלו מבעטי' ויוצאי' שעיקרם רק לגרמי' כו' (כמבואר במ\"א). וזהו כי יד על כ\"ס י\"ה שנק' מחיצה זו של ברזל בשם כיסוי והעלם גמור לאותיות די\"ה כי תועבת ה' כל גבה לב<sup data-n=\"5652\">164</sup> בחוצפא ועזות יש נפרד שהוא היפך בחי' הקדושה שהוא בביטול דבחי' מ\"ה ממש היפך בחי' ההרגשה בעצמו, דאדרבה הוא בהעדר הרגשת עצמו בתכלית בחי' מ\"ה ואי\"ן בעצם כמו משה שא' ונחנו מ\"ה<sup data-n=\"5653\">165</sup> והוא בחי' ו\"ה<sup data-n=\"5654\">166</sup> דחו\"ב שלא יוכל להאיר כ\"א בבחי' אי\"ן ולא בבחי' יש וגסות כו').\n<b>והנה</b> כמו שיש בחי' קליפה דעמלק הנ\"ל בבחי' הפנימי' שהוא בבחי' הרוחניות שהוא בחוצפא וגסות הלב כיש גמור כו' כנ\"ל, כך יש מדה זו גם בבחי' החיצוני' (בבחי' המקיף ששורה על לבושים<sup data-n=\"5655\">167</sup> ) והוא מש\"א<sup data-n=\"5656\">168</sup> בכמה בנ\"א שכל עיקר תשוקתם וזה כל חיותם להתגדל בעיני הבריות שירוממו וישבחו ויפארו אותם ויהי' לשם ולתהלה בארץ<sup data-n=\"5657\">169</sup> ומושל ורודה ושיהיו הכל טפלים אליו ומשכימים לפתחו ובעצתו והדרכתו יעשו לא ירים איש<sup data-n=\"5658\">170</sup> את ידו ורגלו בלעדו, וזהו הטבע בגסות וחיצוניות שזהו בחי' התפשטו' בחיצוניות ביתר מכפי המדה שזהו מחמת גובה וגסה\"ר שבלבו בפנימי' בחוצפא והתנשאות יתירה, ע\"כ כל תשוקתו להתגדל על הכל ברוממות והתנשאות יתירה (וכהמן שנתמלא חימה<sup data-n=\"5659\">171</sup> על מרדכי כו' והוא שא' למי יחפוץ המלך<sup data-n=\"5660\">172</sup> לעשות יקר יותר ממנו<sup data-n=\"5661\">173</sup> כו'). והאות והסימן לזה הוא מה שיש בטבע בנ\"א הללו להתנהג במלבושי כבוד וגדולה במעשה רוקם [לכבוד] ולת\"ת דוקא <span data-k=\"pg\">1084</span> ּ בכמה מיני מלבושים של הוד שאין כמוהם בזולתם, וכה\"ג בכלי כסף וזהב יקרים ונאים ומרגליות ואבני יקר להלביש לנשיהם ובנותיהם שיהי' ברוממות וגדולה יתירה על הכל שזהו כל חיותם ממש, ו[מ]כ\"ש בהיכלות ודיר[ו]ת פלטרין נאים ועגלות צב וכה\"ג עד שיפזר כל הון ע\"ז יותר מצרכי גופו ההכרחיים. וכך הוא טבעם בפיזור על הוצאות קטנים ביד מלאה ורחבה ביותר עד שאין הכסף נחשב למאומה<sup data-n=\"5662\">174</sup> כו', כ\"ז אינו בא רק מבחי' הגסות והתנשאות דחוצפא דעמלק הנ\"ל שבאה בחיצוניות שזהו ההנהגה ברוממות כמו במלבושי משי ומרגליות ודירות נאים כו', ושארי הוצאות פיזור בדרך השרים וגדולי ארץ דוקא.",[["5646","158","<b>עשו א\"ח ליעקב</b>: תולדות כה, כב ואילך."],["5647","159","<b>שלאום מלאום. . ולא נתמלא צור</b>: נסמן לעיל שנב, ג."],["5648","160","<b>במ\"א)</b>: אכא: במ\"א."],["5649","161","<b>השליא של הולד</b>: ראה גם שע\"ת נ, ד. הנסמן לעיל פ' שמות ט, ד."],["5650","162","<b>למען שמי. . יכבד ה'</b>: המשך הכתוב אמרו אחיכם — ראה גם לעיל פ' וארא פד, א."],["5651","163","<b>שעתיד לעשות סוכה</b>: ע\"ז ג, א. ראה גם מאמרי אדה\"א קונטרסים ס\"ע קמה ואילך. שע\"ת עז, ב ובהערה 8."],["5652","164","<b>תועבת ה' כל גבה לב</b>: משלי טז, ה."],["5653","165","<b>ונחנו מ\"ה</b>: בשלח טז, ז. ח."],["5654","166","<b>ו\"ה</b>: אכא: י\"ה."],["5655","167","<b>המקיף ששורה על לבושים</b>: ראה גם לעיל פ' בשלח קפ, ג. וש\"נ."],["5656","168","<b>מש\"א</b>: אכא: מה שאנו רואים."],["5657","169","<b>לשם ולתהלה בארץ</b>: ע\"פ צפני' ג, כ."],["5658","170","<b>לא ירים איש</b>: ע\"פ מקץ מא, מד."],["5659","171","<b>וכהמן שנתמלא חימה</b>: אסתר ג, ה."],["5660","172","<b>למי יחפוץ המלך</b>: אסתר ו, ו."],["5661","173","<b>ממנו</b>: אכא: ממני."],["5662","174","<b>שאין הכסף נחשב למאומה</b>: ע\"פ מל\"א י, כא. דהי\"ב ט, כ."]]],[2300550399,"<b>ויש</b> בנ\"א ששונאים מאד מדה זאת והנהגה כזאת להתנהג בגדול[ו]ת ורוממות אלא רק כדי מחסורו לבד ולא יחשוק להיות גדול ורב בעיני הבריות כלל ויסתפקו במ[י]ע[ו]ט למעט ההוצאה רק לצרכיו ההכרחיים לבד, ואע\"פ שא\"ז מצד יראתו אלקי' או שפלות וענוה יתירה אלא כך הוא הטבע שלהם מפני שאינם מבחי' ההתנשאו' וגסות וחוצפא הנ\"ל אף לא בחיצוניות כלל וכלל כו', דודאי מי שאין בו בחי' קליפה דמדה דעמלק בפנימי' בגסות וגובה הלב כ\"כ מסתמא אין לו מדה זאת גם בחיצוניות שהוא ההנהגה וההתפשטו' בלבושים והיכלות וכסף וזהב ופיזור הנ\"ל דהא בהא תליא שהחיצוני' נגרר אחר הפנימי' (ויוכל להיות פנימי' דעמלק בלא חיצוני' כמו גם בעניים ודלים ושפלים שחוצפא שלו בפנימי', ויש בנ\"א שעיקר מדה זו דעמלק רק בחיצוניות דוקא כו') (ובאמת כל זה שנמצא בישראל מבחי' עמלק הוא שא' ויזנב בך<sup data-n=\"5663\">175</sup> כל הנחשלים אחריך כו', שמקר[ר] לב ההולכים בעבודת ה' בביטול והכנעה ובדביקות והתלהבות כי כל תשוקתם רק לעצמם להתגדל לבד כו' היפך בחי' הביטול לאלקי', ע\"כ מהם יבא מניעת גילוי האור דשם הוי' בנש\"י. וגם אשר מתנהגים רק ברוממות בהתפשטות חיצוניות כו' עד שלא יספיק לו כל הון לפי צרכו בהנהגת הרוממות והתרחבו' כו' (וכמו שרואים ד\"ז [ב]רוב ההמון גם בקטני הערך מאד שיחפצו להתגדל בשם כשם הגדולים להתנהג במלבושי כבוד ודירה נאה ושיכובד בעיני הבריות כו', וזהו כל עיקר אריכות הגלות כידוע) (וגם בעובדי ה' באמת ותמים נמצא ב' מיני טבעיות הפכיים כו', שיש מהן חפצם ותשוקתם להתנהג ברוממות והרחבה דוקא, כמו במזון ולבוש ודירה וכסף וזהב כו' ולא מצד הגסות והתנשאו' דקליפה דעמלק ח\"ו<sup data-n=\"5664\">176</sup> כי הלא עובדים ה' באמת בביטול והכנעה בקבלת עומ\"ש באמת ואמונה שלימה כו' וכל חפצ[ם] הוא בגילוי אלקות בתו\"מ באהוי\"ר שלימה דוקא כו'. אך שהן מרגישים בעצמם התפעלות אלקות וזה כל חפצם דוקא שיהי' בלבם במורגש אור וחיות האלקי עד שמזה הן חיים ממש, וכשאין בלבם במורגש ידמה להם [כ]נופלים בעבודת ה' ומצערים<sup data-n=\"5665\">177</sup> בנפשם ע\"ז מאד, ואע\"פ שזהו בבחי' הקדושה ממש אבל זהו בבחי' גסות ויש דקדושה שלעומת גסות דעמלק. והוא מש\"א שיש בעובדי ה' אלה בחי' התוקף וחוזק ועקשות קשה כארז בעבודה <span data-k=\"pg\">תקמב</span> ּ שבלב ומוח בתפלה ותורה וגם גבהות והתנשאו' הלב באוי\"ר בתפלה כמו ויגבה לבו בדרכי ה'<sup data-n=\"5666\">178</sup> דוקא וכמבואר במ\"א בענין המ\"ן מן התורה מנין שיש בחי' המ\"ן בקדושה האלקי' והוא חלק שמיני' שבשמינית<sup data-n=\"5667\">179</sup> מגסה\"ר שבת\"ח שהוא רק חלק ס\"ד, אבל חלק ס\"ג נק' גסות הרוח דקליפ' עמלק כו' ולא מעטרא לי' כסאסאה דשבולתא<sup data-n=\"5668\">180</sup> כו' שא[ם] ל[א] יהי' [בו]",[["5663","175","<b>ויזנב בך</b>: תצא כה, יח."],["5664","176","<b>ח\"ו</b>: א: הנ\"ל ח\"ו. כא: כו'."],["5665","177","<b>ומצערים</b>: שם: ומצירים."],["5666","178","<b>ויגבה לבו בדרכי ה'</b>: דהי\"ב יז, ו."],["5667","179","<b>שמיני' שבשמינית</b>: ראה גם לעיל פ' משפטים שג, א. וש\"נ."],["5668","180","<b>מעטרא לי' כסאסאה דשבולתא</b>: ראה סוטה ה, א."]]],[2300550416,"תוקף וח[ו]זק בגסות וגבהות הלב בעבודת ה' יפול מיד מעבודתו ונק' איש חלש ולא גבור וא' הוי גבור כארי<sup data-n=\"5669\">181</sup> כו'). וזהו המעלה דישראל שנק' קשה עורף<sup data-n=\"5670\">182</sup> בתוקף וחוזק באמונתם ועבודתם שכל רוחות שבעולם לא יזיזו אותם כארז קשה ביותר כו' וכמאמר ג' עזין הן<sup data-n=\"5671\">183</sup> ישראל עזין שבאוה\"ע<sup data-n=\"5672\">184</sup> כו', אך מצד בחי' ההרגשה יתירה שמרגיש בעצמו בהתפעלות עבודתו תומשך<sup data-n=\"5673\">185</sup> ונסתעף ממנו להיות בבחי' גסות דעמלק, שהוא בחי' התפשטות החיצוני' בהנהגה ברוממות בהרחבה גדולה בצרכי ביתו<sup data-n=\"5674\">186</sup> כמו במלבושי יקר וכסף וזהב וידו רחבה בכל<sup data-n=\"5675\">187</sup>, ונדמה לו שהכל לש\"ש כי נצרך לכך להרחיב לבו ודעתו בעבודת ה' וגם לבנ[י]ו ואשתו ינהיג כן, ולא באלה חפץ ה' כי לא ישכון כ\"א בבחי' אין ומ\"ה בעצם והן עובדי הוי' בשפלות וענוה יתירה שאינם מרגישים בעצמם כלום, אדרבה כ\"מ<sup data-n=\"5676\">188</sup> שעובד ועושה אינו רואה לכלום ומוצא בזה התחייבות ע\"ע עד שנפשו כעפר לכל בלב נשבר כו' (ושפלות בעצם נישטקייט בעצם) וממילא לא יחפוץ בטבעו כלל בהנהגת ברוממות בהרחבה, ואדרבה ישנא מאד להתנהג בכאלה וכגון רחב\"ד שהי' די לו בקב חרובין<sup data-n=\"5677\">189</sup> כו' לפי שהוא כמותר בעולם וכל אשר לו יפזר לעניים ואורחים כאברהם<sup data-n=\"5678\">190</sup> אבינו וכה\"ג כידוע וד\"ל).\n<b>והנה</b> כתיב ראשית גוים עמלק דעמלק אינו נמנה בכלל הז' אומות הכנעני והחיתי כו' כי הוא ראשית ומקור להם, דהנה באמת הגם שכל הז\"מ רעות דק\"נ הם רעים וחטאים לה' מאד<sup data-n=\"5679\">191</sup> כמו התאוה רעה כחם אבי כנען<sup data-n=\"5680\">192</sup> וכרציחה וכעס בש\"ד וכה\"ג בפרטי התועבות שהי' במצרים ובכנען שכולם רעים מאד. אבל שרש כולם הוא קליפה דעמלק משום דשאר המדות המגונות הן רק תולדות המסתעפי' רק מן הגסות וחוצפא דעמלק הנ\"ל, שא[ם] ל[א] בחי' הגסות וחוצפא יתירה כזו לא הי' בא לכלל תאוות ומדות הרעות כלל, לפי שכל מה שיתאוה תאוה גופני' בחום הטבעי' הקשה עד שבוער כאש ממש זהו רק מצד הרגשת עצמו ביותר בבחי' יש עד שהוא צריך למלאות תאותו בכל אשר תשאל נפשו לא ישבע, כמו בתאות המאכל א' ובטן רשעים תחסר<sup data-n=\"5681\">193</sup> שלא ימלא כריסו כענין הלעיטני נא<sup data-n=\"5682\">194</sup> כו'. וכמו\"כ בכל תאוה [כ]תאוות חמדת הממון להרבות הון כו' לא ישבע כסף<sup data-n=\"5683\">195</sup> וכמו הגיהנם שנק' עלוקה<sup data-n=\"5684\">196</sup> שאו' הב הב<sup data-n=\"5685\">197</sup> כו' רק לגרמי' לפי שאין לו שיעור לעצ[ו]ם הרגשת ישותו וגסותו הנפרד כו', וכמו\"כ יבא לכלל תאוות זנות וכל הרהורים רעים",[["5669","181","<b>הוי גבור כארי</b>: ראה אבות פ\"ה, מ\"כ."],["5670","182","<b>דישראל שנק' קשה עורף</b>: תשא לב, ט. לג, ג. ה. לד, ט. עקב ט, ו. יג."],["5671","183","<b>ג' עזין הן</b>: ביצה כה, ב. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקז. ע' תקט ואילך."],["5672","184","<b>עזין שבאוה\"ע</b>: כא: באומו'."],["5673","185","<b>תומשך</b>: אכא: (ש)נמשך."],["5674","186","<b>ביתו</b>: כא: גופו."],["5675","187","<b>בכל</b>: א: ניתוסף: כנ\"ל. כא: ניתוסף: כו'."],["5676","188","<b>כ\"מ</b>: שם: כל מה."],["5677","189","<b>רחב\"ד. . בקב חרובין</b>: תענית כד, סע\"ב."],["5678","190","<b>כמותר בעולם. . כאברהם</b>: ראה גם לעיל פ' בשלח קע, ב. וש\"נ."],["5679","191","<b>רעים וחטאים לה' מאד</b>: לך יג, יג."],["5680","192","<b>התאוה רעה כחם אבי כנען</b>: נח ט, כב. יח. ראה גם מאמרי אדה\"א שמות ח\"ב ס\"ע תקנז ואילך (ובנסמן שם ע' תקנח). במדבר ח\"ה ע' א'תשלט. תו\"ח ח\"ש קלט, ב ובהערה 25."],["5681","193","<b>ובטן רשעים תחסר</b>: משלי יג, כה."],["5682","194","<b>הלעיטני נא</b>: תולדות כה, ל."],["5683","195","<b>לא ישבע כסף</b>: קהלת ה, ט."],["5684","196","<b>הגיהנם שנק' עלוקה</b>: ראה ע\"ז יז, א ובתוס' שם. ערכי הכנויים לבעל סדר הדורות מערכת עלקה. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרלט."],["5685","197","<b>עלוקה. . הב הב</b>: משלי ל, טו."]]],[2300550433,"וחטאים כו' הכל רק מצד גסותו והתנשאותו שאם הי' שפל בעיניו ומכיר מקומו לא הי' נוגע ולא הי' מתאוה כלל במה שאינו <span data-k=\"pg\">1086</span> ּ שלו ולא למלאות כל תאוותו בי[ו]תר מכפי הנצרך לו והראוי לו, וגם בעניני פרנסתו הי' מספיק במיעוט ושמח בחלקו ולא הי' מתאוה להשיג הון ולהתנהג ברוממות והרחבה כלל כו'. ונמצא דכל המדות המגונות המביאות לכל מיני רע במדות הרעות דז\"מ דק\"נ מקורם הראשון אינו רק קליפה דעמלק הנ\"ל, ולכך נק' ראשית גוים וע\"כ גם אחר שיניח ה' מכל אויביך שהן ז' אומות לבררם מצוה למחות זכר עמלק כמ\"ש ואחריתו עדי אובד<sup data-n=\"5686\">198</sup> כו' כמ\"ש והי' בהניח ה' כו' תמחה את<sup data-n=\"5687\">199</sup> כו', ובפ' בשלח א' כי יד על כס י\"ה שיד ה' נלחם בעמלק שהוא גורם להיות [כס ו]נרתק לי\"ה מדור דור ומלחמה זו בעמלק לה' היא (ואע\"פ שא' תמחה<sup data-n=\"5688\">200</sup> כו' כמבואר במ\"א) (וכמשי\"ת).\n<b>והנה</b> ארז\"ל [על מ\"ש] כי יד על כ\"ס י\"ה כו' שאין השם שלם<sup data-n=\"5689\">201</sup> ואין הכסא שלם עד שימחה זכר עמלק כו', והיינו פי' על כ\"ס י\"ה כו', דהנה פי' מ\"ש שאין השם שלם שהוא שם הוי' לא ע\"י פגם באותיות דשם הוי' אלא במה שנחלק אותיות ו\"ה מאותיות י\"ה והוא שנק' כ\"ס י\"ה שהוא נרתק ופרגוד מחיצה המפסקת ומבדלת בין ו\"ה לי\"ה (שנק' ג\"כ ת\"ק ו\"ה<sup data-n=\"5690\">202</sup> כו' כמבואר במ\"א). וזש\"א שאין השם שלם שאין בו שלימות וחיבור כי בבחי' פירוד דו\"ה שהן מדות ודבור מחו\"ב שהן י\"ה אין האור מאיר מי\"ה לו\"ה יחו\"ע ויחו\"ת כו' זהו שאין השם דהוי' שלם כו'), ומ\"ש ואין הכסא שלם היינו מה שגם באותיות די\"ה יש בחי' כיסוי והעלם שמכסה אור די\"ה עצמו<sup data-n=\"5691\">203</sup>, והוא הסיבה שנסתלק אוה\"כ<sup data-n=\"5692\">204</sup> מחו\"ב שהן י\"ה והיינו אות האל\"ף דכ'<sup data-n=\"5693\">*205</sup> שנחסר אורו בי\"ה, ולזאת אינו נק' כס\"א באל\"ף כ\"א כ\"ס י\"ה לבד, לפי שבחי' אלף דכסא<sup data-n=\"5694\">205</sup> היינו בחי' אלופו ש\"ע שהוא השורה על הכסא. משא\"כ כשאין הכסא שלם מצד בחי' הכיסוי והעלם שמכסה ומסתיר לי\"ה, אזי הוא הסתלקות אות הא' דכ[תר] שבכסא ונק' כ\"ס חסר א' ונק' כ\"ס י\"ה להסתיר על י\"ה. וזהו כי יד על כ\"ס י\"ה כלומר בחי' נרתק וכ\"ס די\"ה בהסתלקות אות הא' דכסא הנ\"ל שזהו שאין הכסא שלם, לפי שע\"י בחי' מחיצה ש\"ב דקליפת עמלק הנ\"ל הוא המכסה גם [על] בחי' י\"ה שבנפש כל א' מישראל שזש\"א שמפסיק בין ישראל לאביהם שבשמים דוקא, שהוא מה שאין הכסא ג\"כ שלם עד שימחה זכר עמלק שיוסר המחיצה ש\"ב<sup data-n=\"5695\">206</sup> ואז לא יהי' מסך",[["5686","198","<b>ואחריתו עדי אובד </b>[כא: ליתא]: בלק כד, כ."],["5687","199","<b>והי' בהניח. . תמחה את</b>: תצא כה, יט."],["5688","200","<b>ומלחמה זו בעמלק לה'. . תמחה</b>: ראה מאמרי אדה\"ז תקס\"ה ח\"א ע' שפו. ע' שצו ואילך. תו\"א תצוה פה, ב. ד. דרמ\"צ צט, ב. מאמרי אדה\"א שמות ח\"ב ע' (תלה) תמ. ע' (תקמג) תקסג ואילך."],["5689","201","<b>שאין השם שלם</b>: נסמן לעיל שנו, ג."],["5690","202","<b>ת\"ק ו\"ה</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' שסח־ הנחות תקע\"ז ע' רלא ובהנסמן בהנ\"ל."],["5691","203","<b>עצמו</b>: כא: דאצי'."],["5692","204","<b>אוה\"כ</b>: אכא: אור הכת\"ר."],["5693","*205","<b>דכ'</b>: א: דכסא. יגכאכג: דכתר."],["5694","205","<b>דכסא</b>: איגכג: כבפנים. כא: דכתר."],["5695","206","<b>ש\"ב</b>: א: ניתוסף: הזה. כא: ניתוסף: הנ\"ל."]]],[2300550449,"מבדיל כלל בין ו\"ה לי\"ה וממילא לא יהי' כ\"ס ונרתק על י\"ה כו' ויהי' השם שלם והכסא שלם. אבל כ\"ז שלא נמחה זכר עמלק ולא הוסר בחי' המחיצה זו של ברזל בכאו\"א מישראל אין השם שלם ואין הכסא שלם, וזהו כי יד על כו' [מלחמה] לה' בעמלק מדור דור כו' כנ\"ל וד\"ל.\n<b>להבין</b> ביאור הענין איך הוא ענין כס י\"ה למעלה [ו]איך הוא בנפש כ\"א מישראל ה[נה] י[ש] להק[דים] ביאור מ\"ש עזי וזמרת י\"ה<sup data-n=\"5696\">207</sup> [דוקא] אז ויהי לי לישועה מהו ענין זמרת י\"ה דוקא [כו'], דהנה ארז\"ל עמ\"ש כי בי\"ה ה' צור עולמים<sup data-n=\"5697\">208</sup> ביו\"ד נברא העוה\"ב ובה\"א נברא העוה\"ז<sup data-n=\"5698\">209</sup> וידוע דעוה\"ז נק' עלמא דאתגלי' דבה\"א בראם<sup data-n=\"5699\">212</sup> בה' מו[צאות] הפ[ה] שבדב[ור] הע[ליון] דיו\"[ד] מ[א'] כידוע, וביו\"ד נברא העוה\"ב שזהו בחי' עלמא<sup data-n=\"5700\">211</sup> דאתכסי'<sup data-n=\"5701\">210</sup> דמח'<sup data-n=\"5702\">213</sup> בהעלם שנמשך <span data-k=\"pg\">תקמג</span> ּ בבינה מנקו' דחכ'<sup data-n=\"5703\">*214</sup> שנק' יו\"ד ובכלל הן ב' מדרגות דסוכ\"ע וממכ\"ע<sup data-n=\"5704\">214</sup> שז\"ש ברוך ה' מן העולם<sup data-n=\"5705\">215</sup> ועד העולם כו' וד\"ל.\n<b>וביאור</b> הדברים, הנה תחלה י\"ל במהות ענין דב' אותיות הללו די' וה' כו', דהנה בציור תמונת האותיות ע\"פ ס' הקבלה א\"א לה' בלא יו\"ד<sup data-n=\"5706\">216</sup> בתחלה, לפי שיו\"ד מורה תמונתו ענין ובחי' צמצום כנקודה<sup data-n=\"5707\">217</sup> והה\"א בציור תמונתו מורה בחי' ההתפשטו' לאו\"ר<sup data-n=\"5708\">218</sup> דוקא וא\"כ הרי הן ב' הפכים לכאורה שהצמצום דבחי' נקודה הוא העדר ההתפשטות דוקא, והה\"[א] הוא בבחי' ההתפשטו' לאו\"ר דוקא. ולפ\"ז הי' ראוי שי[ו]קדם וי\"ו לה' שהוא בחי' הקו כידוע בענין נקודה קו שטח<sup data-n=\"5709\">219</sup>, דא\"א ל[היות] מנקוד[ה] שטח כ\"א ע\"י אמצעות הוי\"ו שהוא בחי' הקו שנעשה מנקודה שהוא בחי' הירידה והמשכה מלמעלה למטה עכ\"פ ואז מן הקו נעשה בנין השטח כדלי\"ת באורך [וברוחב], וכל ציור ותמונה שטח[י'] הכל מן הקו דוקא ולא מן הנקודה די' שהוא מורה בחי' העדר ההתפשטו' דוקא, ואיך יומשך ממנו ה' שהוא ההתפשטו' היפוכו דוקא. אך הענין הוא לפי שביו\"ד עצמו כלול קו ושטח שהן מילוי דאותיות ו\"ד שביו\"ד (שהן בחי' המדות ודבור שבחכמה<sup data-n=\"5710\">220</sup> בהעלם ויוצא לגילוי מן ההעלם בה' דבינה כו'). ואמנם בחי' הגילוי מן ההעלם דקו ושטח הכלול ביו\"ד זהו שנמשך בציור ותמונה דאות היו\"ד עצמו שאינו נקודה פשוטה קטנה אלא נמשך בדרך ציור ברוחב מעט, רק שמקצר בו",[["5696","207","<b>עזי וזמרת י\"ה</b>: בשלח טו, ב."],["5697","208","<b>כי בי\"ה ה' צור עולמים</b>: ישעי' כו, ד."],["5698","209","<b>ביו\"ד נברא העוה\"ב. . העוה\"ז</b>: ראה מנחות כט, ב."],["5699","212","<b>דבה\"א בראם</b>: ראה מנחות כט, ב. ב\"ר פי\"ב, ב. לעיל פ' שמות לד, א. וש\"נ."],["5700","211","<b>עלמא דאתגלי'. . עלמא דאתכסי'</b>: נסמן לעיל שנו, ד."],["5701","210","<b>דעוה\"ז נק' עלמא דאתגלי'. . העוה\"ב. . עלמא דאתכסי'</b>: ראה גם לעיל שנו, ד."],["5702","213","<b>עלמא דאתגלי'. . שבדב[ור]. . עלמא דאתכסי' דמח'</b>: ראה גם לעיל פ' בשלח קמג, ד. וש\"נ."],["5703","*214","<b>וביו\"ד נברא העוה\"ב. . בבינה מנקו' דחכ'</b>: ראה גם לקמן פ' פקודי תמג, ב. וש\"נ."],["5704","214","<b>דסוכ\"ע וממכ\"ע</b>: זהר (רע\"מ) פינחס רכה, א."],["5705","215","<b>ברוך ה' מן העולם</b>: ראה גם לעיל פ' שמות יח, ג. וש\"נ."],["5706","216","<b>א\"א לה' בלא יו\"ד</b>: ראה בסמוך בפנים ד\"ה וזהו הטעם."],["5707","217","<b>שיו\"ד. . תמונתו. . כנקודה</b>: ראה אנציק' תלמודית (כרך כא) אות יוד הערה 4."],["5708","218","<b>לאו\"ר</b>: אכא: לאורך ורוחב."],["5709","219","<b>נקודה קו שטח</b>: ראה גם לעיל פ' בשלח קפה, א. וש\"נ."],["5710","220","<b>ו\"ד שביו\"ד. . המדות ודבור שבחכמה</b>: ראה גם מאמרי אדה\"א בראשית ע' ח. וש\"נ."]]],[2300550464,"ומושך ממנו קו קטן בצדו הימנית<sup data-n=\"5711\">221</sup>, שמבחי' קו הזה הוראות ציור ההתפשטו' לאו\"ר דה\"א. והרי בציור ותמונה זאת דיו\"ד הנכתב אינו ענין צמצום לגמרי כנקוד' דיו\"ד קטנה בלא תג כלל אלא אדרבה מורה ענין המשכה להבא שעתיד להמשיך ממוח<sup data-n=\"5712\">222</sup> קו ושטח, והוא משך הציור די' משמאל לימין בק[ו] דרוחב והתג הנמשך ממנו מימין<sup data-n=\"5713\">223</sup> לשמאל שמורה על שעתיד להמשיך ה' באורך [ורוחב] ממש (והוי\"ו הוא הרגל הקצר בתוך הה\"א<sup data-n=\"5714\">225</sup> כו' שהן<sup data-n=\"5715\">224</sup> המדות הכלולים בבינה שלמעלה מזה הוא הוי\"ו שבמילוי היו\"ד שהן המדות דחכ' כו'), וזהו עיקר ענין אות הי' דשם הוי' שמורה ענין עתיד ולשון הוה<sup data-n=\"5716\">226</sup> תמידות שתמיד יהוה מאין ליש וד\"ל. והיינו מה שתמיד מוכן ועומד להיות בחי' הגילוי והשגה דבינה מאין דחכמה שע\"ז מורה אות היו\"ד בציור תמונתו, כמו המעיין<sup data-n=\"5717\">228</sup> הנובע בהעלם שממנו נמצא תמיד מציאות התגלות דהתפשטות הנהר<sup data-n=\"5718\">227</sup> וא\"א לנהר בלא מעיין כלל וא\"א למעיין בלא נהר הנמשך ממנו לאורך [ורוחב]. וכך הוא גם בבחי' היו\"ד שגם שהוא בבחי' צמצום, מ\"מ תמונתו מורה המשכה נעלמת כמעיין הנובע בהעלם באופן שיתגלה והוא ע\"י בחי' קול<sup data-n=\"5719\">229</sup> התחתון שבו שמביא מן ההעלם דחכ' לגילוי בבחי' בינה שהוא הה\"א באורך [ורוחב] כנהר כו', שזהו מאין ליש דהשגה דבינה כידוע עד שנק' כמו תרין ריעין דלא מתפרשין<sup data-n=\"5720\">230</sup> לעלמין כך הוא בבחי' או\"א שהן אותיות י\"ה<sup data-n=\"5721\">231</sup> כידוע וד\"ל.\n<b>וזהו</b> הטעם שאנו מוצאים בס' הקבלה שבתמונת אותיות גם כשכותבין אות ה' ראשונה דשם הוי' צריך לעשות ולכתוב כמו אות היו\"ד<sup data-n=\"5722\">232</sup> בתחלה ואח\"כ ממשיך ממנו עצמו באורך בציור ה' כו'. <span data-k=\"pg\">1088</span> ּ והענין הוא מטעם הנ\"ל לפי שא\"א ל[היות] בחי' התפשטות דאורך [ורוחב] דהשגה דבינה שנק' נהר בבחי' יש כ\"א בהקדים תחלה בחי' הצמצום דאות היו\"ד דוקא, מפני שאחר בחי' הצמצום דאות היו\"ד הוא שמורה ענין המשכה והתפשטות שעתיד להיות ממנו דוקא, כמו שמציירים בנקודה דיו\"ד [מ]בחי' ההעלם שיבא לגילוי אע\"פ שעדיין לא בא בגילוי ממש. וזהו אות היו\"ד דשם הוי' שהוא הצמצום בתחלה שממנו דוקא יבא בחי' ההתפשטו' דה' שממשיך אח\"כ שכ\"מ<sup data-n=\"5723\">233</sup> שממשיך אח\"כ בה' אינו נמשך רק מכחו של יו\"ד שבתחלה מטעם הנ\"ל כמשל מעיין בנהר, וע\"כ גם בתמונת הה' כותבים יו\"ד בתחלה",[["5711","221","<b>היו\"ד. . קו קטן בצדו הימנית</b>: ראה שו\"ע אדה\"ז הל' תפילין סל\"ו אות יו\"ד."],["5712","222","<b>ממוח</b>: א: הימנו. כא: ממנו."],["5713","223","<b>מימין</b>: כא: ליתא."],["5714","225","<b>הרגל הקצר בתוך הה\"א</b>: ראה ביאוה\"ז בלק קג, ג. לעיל פ' שמות יט, א. וש\"נ."],["5715","224","<b>(והוי\"ו. . שהן</b>: אכא: והוי\"ו. . (שהן."],["5716","226","<b>הי'. . עתיד ולשון הוה</b>: ראה שער היחוה\"א פ\"ד. לעיל פ' בשלח קנ, א. וש\"נ."],["5717","228","<b>דחכמה. . המעיין</b>: ראה זהר בא מב, ב. שער האמונה צ, א ובהערה 12."],["5718","227","<b>דבינה. . הנהר</b>: ראה זהר (אדרא דמשכנא) משפטים קכג, ב."],["5719","229","<b>קול</b>: אכא: קוץ."],["5720","230","<b>תרין ריעין דלא מתפרשין</b>: נסמן לעיל שמז, ב."],["5721","231","<b>או\"א שהן אותיות י\"ה</b>: נסמן לעיל פ' משפטים רפז, א."],["5722","232","<b>ה' ראשונה דשם הוי'. . היו\"ד</b>: ראה גם לעיל שנו, ג. וש\"נ."],["5723","233","<b>שממשיך אח\"כ שכ\"מ</b>: אכא: ליתא."]]],[2300550479,"שממנו ממשיך אח\"כ אורך [ורוחב] דה' שא[ם] ל[א] היו\"ד אין מקור ושרש לה', לפי שאחר הצמצום די' יבא ההתפשטו' והא בהא תליא אע\"פ שהן ב' הפכים [כ]אין ויש שמאין דוקא נמשך בחי' יש והיו לאחדים ממש וד\"ל (וז\"ש בזהר דאו\"א זיווגייהו תדיר<sup data-n=\"5724\">234</sup> ונק' תרין ריעין דלא מתפרשין כחדא שריין<sup data-n=\"5725\">235</sup> כו' שהוא בשביל שפע העולמות בתמידות מאין ליש (ולא כריב\"נ כשמן שצף ע\"ג היין<sup data-n=\"5726\">237</sup> שזהו שמן בחכמה שצף ע\"ג היין דבינה<sup data-n=\"5727\">238</sup> שאינם חיבור לטומאה<sup data-n=\"5728\">236</sup> כו'). וכך יובן למעלה במ\"ש כי בי\"ה ה' צור עולמים שהן העוה\"ב והעוה\"ז כו' שנק' עלמא דאתכסייא ועלמא דאתגלייא בכלל, ובד\"כ כל ההשתלשלו' זהו בחי' סוכ\"ע ובחי' ממכ\"ע בכלל ותוכל<sup data-n=\"5729\">239</sup>. כי בחי' סוכ\"ע הכללי היינו בחי' ההעלם דמח' ורצון הפשוט הכללי כמו שעלה ברצונו ומח' הפשוטה טרם שנמשך לבחי' גילוי מאין ליש בחו\"ב זהו בחי' הצמצום די' דחכ' כמו שהוא בבחי' האין וההעלם כו', ואח\"כ נמשך ממנו [ב]בחי' גילוי בבחי' ההתפשטות דבינה באורך [ורוחב] כנ\"ל זהו בחי' ממכ\"ע בכללות שנמשך בבחי' שטח כמו מעומ\"ט וד' רוחות שנק' עולם ומקום כו'. ודוקא אחר בחי' הצמצום די' בהעלם הוא שבא לבחי' התפשטות, וכנ\"ל בתמונת אות הה' שתחלתו כותבים יו\"ד דוקא מטעם שא\"א לבחי' התפשטו' דה' בלא צמצום די' בתחלה וד\"ל.\n<b>והנה</b> מבואר במ\"א עמ\"ש בזהר בענין ועבד הלוי הוא<sup data-n=\"5730\">240</sup> דא הוא עתיקא כו', ויש בי' ג' קוצין<sup data-n=\"5731\">241</sup> קוץ העליון וקוץ התחתון וגופו של יו\"ד עצמו, בחי' קוץ העליון שלו הוא בחי' כ[תר] דחכמה שהוא בחי' אי\"ן ממש ע\"כ תג [זה] פונה כלפי מעלה להורות על בחי' ההעלם והצמצום ליכלל בעצמו' המאציל, וגופו של יו\"ד שאינו אלא העלם שיבא לגילוי שע\"ז מורה תמונתו כו' הוא בחי' אין דחכ' שמוכן ועומד להתמשך בבינה [ב]השגה [ב]התפשטות, וקוץ התחתון די' זה הוא כח המביא וממשיך לבחי' העלם דנקודה די' דחכ' מאין ליש בהשגה דבינה והוא שנק' פנים מסבירות<sup data-n=\"5732\">242</sup> שיכול להביא העלם ותמצית החכמה לידי הסבר בהשגה לאורך [ורוחב] כו'. וזהו הב\"ן בחכמה וחכ\"ם בבינה<sup data-n=\"5733\">243</sup> דקוץ התחתון דיו\"ד זה היינו בינה שבחכמה ס\"ג דע\"ב וחכ\"[ם] בבינ\"ה ע\"ב דס\"ג שנק' עומק המושג כו' (כמבואר במ\"א באריכות), וז\"ש ועבד הלוי הוא דא הוא ע\"י כו' שזהו בחי' קוץ התחתון די' שיכול להביא לנקוד' דחכ' עילאה<sup data-n=\"5734\">244</sup> מאין ליש בהשגה דבינה שגדול כחו מגוף נקודה",[["5724","234","<b>דאו\"א זיווגייהו תדיר</b>: ראה זהר (אד\"ז) האזינו רצ, ב. הנסמן לעיל פ' יתרו עדר, ד הערה 49."],["5725","235","<b>דאו\"א. . כחדא שריין</b>: ראה זהר שם."],["5726","237","<b>כשמן שצף ע\"ג היין</b>: טבול יום פ\"ב, מ\"ה. ראה גם לעיל פ' בא קכ, ג. וש\"נ."],["5727","238","<b>שמן בחכמה. . היין דבינה</b>: ראה לעיל פ' בא קכ, ג הערה 286."],["5728","236","<b>כריב\"נ </b>[א: ליתא. יגכאכג: כבפנים]<b>. . שאינם חיבור לטומאה</b>: כ\"ה גם במאמרי אדה\"א נ\"ך ע' רפג."],["5729","239","<b>בכלל ותוכל</b>: אכא: בכללות כנ\"ל."],["5730","240","<b>ועבד הלוי הוא</b>: קרח יח, כג. ראה זהר שם קעח, ב. לעיל פ' שמות לד, א. וש\"נ."],["5731","241","<b>ג' קוצין</b>: ראה גם לעיל שם. וש\"נ."],["5732","242","<b>פנים מסבירות</b>: ראה גם לעיל פ' שמות י, ג. וש\"נ."],["5733","243","<b>הב\"ן בחכמה וחכ\"ם בבינה</b>: ס\"י פ\"א, מ\"ד. ראה שער היחוד קט, ב."],["5734","244","<b>עילאה</b>: כא: ליתא."]]],[2300550494,"די' דחכ', והוא בבחי' פנימי' הכתר שלמעלה מן החכ' שזהו בחי' קוץ העליון שפונה למעלה כו' שלמעלה מב' מזלות דונוצר ונקה שרש <span data-k=\"pg\">תקמד</span> ּ החו\"ב<sup data-n=\"5735\">245</sup> כו', והיינו שאמר דא הוא ע\"י עצמו ששם הוא בחי' עצמות אור א\"ס ממש<sup data-n=\"5736\">246</sup> ששוין לפניו העלם וגילוי ע\"כ נעשה מהעלם גילוי כו' (ולפי\"ז הרי יובן שבשרש ומקור בהעלם דחו\"ב יש שרש לבינה למעלה משרש החכ'<sup data-n=\"5737\">247</sup> אע\"פ שבגילוי בחי' החכ' מקור לבינה ומחכ' שנק' אין נמשך לבינה שנק' יש, אבל בשרש ומקור הנעלם בעצמות אור הכתר הרי בחי' קוץ התחתון דחכ' שממנו נמשך להתפשטות דבינה מגיע לקוץ העליון שהוא ע[צמו'] הכתר שלמעלה משרש החכ', דמ\"ה שהחכ' מאין תמצא זהו רק בחי' נקודה לבד כמו שהוא נמשך ממזל ונוצר חסד דא\"א בחי' צומח כו'<sup data-n=\"5738\">248</sup> דכ[תר] כו', ושרש [ד]בינה מאחר שיש בכחה להמשיך לנוק'<sup data-n=\"5739\">249</sup> דחכמ' בהתפשטו' יותר ממדתה בעצמה שבלתי מתפשטת ה\"ז מוכרח ששרשה באור הכתר במדרגה עליונה יותר משרש החכ' בכ[תר], והיינו מבחי' כת\"ר שבכת\"ר שלמעלה מחכ' שבכתר כו' וז\"ש בזהר דא הוא ע\"י ממש וד\"ל. וזהו דפנים מסבירות דתושבע\"פ כמו שדרש על כל קוץ וקוץ דתושב\"כ תלי תלים של הלכות<sup data-n=\"5740\">251</sup> גדול שרשה יותר משרש דתושב\"כ שהוא החכ' שמאין דכתר תמצא שנק' פנים מאירות<sup data-n=\"5741\">250</sup> שמאיר לבינה שהיא תושבע\"פ<sup data-n=\"5742\">252</sup> כידוע דתושב\"כ ושבע\"פ נק' ספר וסיפור<sup data-n=\"5743\">253</sup> וזהו שאמר דבינה יתירה ניתנה באשה<sup data-n=\"5744\">254</sup> שהיא תושבע\"פ יותר מבאיש תושב\"כ וד\"ל (וזהו ענין נבונים דגדולים מחכמים כידוע שזהו המבין דבר מתוך דבר<sup data-n=\"5745\">255</sup> כמו בחי' פנים מסבירות לנקוד' דחכ' להביא' בהשגה ששרשה יותר עליון מגוף הדבר החכ' שנמשך בנקוד' ממקורה מטעם הנ\"ל).\n<b>והנה</b> ע\"ד כ\"ז יובן ג\"כ בענין כללות של<sup data-n=\"5746\">256</sup> כל ההשתל' ברום המעלות גם בבחי' עצמות אוא\"ס ממש שלפני בחי' הצמצום דקו\"ח שבוקע ועובר כל אצי' עד סיום סוף עולם העשי' כו', כי הנה ידוע בע\"ח בתחלתו בשרש הצמצום הראשון דהיינו שבתחלה הי' אוא\"ס עצמו ממלא כל החלל<sup data-n=\"5747\">257</sup> הזה כו' ואח\"כ נתצמצם אור העצמי' ונכלל במאור ונעשה מק\"פ כו' ולא נשאר רק בחי' רושם כנקוד' די'<sup data-n=\"5748\">258</sup> בלבד כו', ואח\"כ מן הנקודה ורושם הזה הוא שנמשך בחי' הקו ומן הקו הזה נעשה מקור או\"כ פנימי ומקיף כו'. וביאור ענין זה היינו ע\"ד הנ\"ל בב' אותיות די\"ה שבחי' הנקודה דרושם הנשאר למעלה אחר",[["5735","245","<b>מב' מזלות דונוצר ונקה שרש החו\"ב</b>: נסמן לעיל שס, ב."],["5736","246","<b>ממש</b>: כא: ליתא."],["5737","247","<b>שרש לבינה למעלה משרש החכ'</b>: ראה מאמרי אדה\"ז על מארז\"ל ע' ז. תקע\"א ע' עה (ובהנסמן בהנ\"ל). מאמרי אדה\"א דברים ח\"א ע' רכט, סה\"מ תרמ\"ז ע' תכו ואילך."],["5738","248","<b>כו'</b>: אכא: ליתא."],["5739","249","<b>לנוק'</b>: שם: לנקוד'."],["5740","251","<b>על כל קוץ. . תלי תלים של הלכות</b>: ראה מנחות כט, ב."],["5741","250","<b>דפנים מסבירות. . מאירות</b>: ראה גם לעיל פ' שמות יא, ב. וש\"נ."],["5742","252","<b>דתושב\"כ שהוא החכ'. . לבינה שהיא תושבע\"פ</b>: ראה הנסמן לעיל פ' בא צד, ד הערה 387."],["5743","253","<b>דתושב\"כ ושבע\"פ נק' ספר וסיפור</b>: ראה גם לעיל פ' שמות ט, ג. וש\"נ."],["5744","254","<b>דבינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. לעיל פ' שמות י, ב. וש\"נ."],["5745","255","<b>נבונים. . המבין דבר מתוך דבר</b>: חגיגה יד, א. ראה גם לעיל פ' בשלח קצב, ב, וש\"נ."],["5746","256","<b>של</b>: אכא: ליתא."],["5747","257","<b>בע\"ח בתחלתו. . ממלא כל החלל</b>: ראה ע\"ח (דרוש עגו\"י) ש\"א ענף ב. הנסמן לעיל פ' יתרו רסב, א הערה 267."],["5748","258","<b>די'</b>: כא: ליתא. ראה סה\"מ תרנ\"ט ע' עז ובהערה שם."]]],[2300550508,"הצמצום הראשון זהו ממש כנקודה די' בלתי תמונת אות עדיין שמורה שנסתלק ונתצמצם הכל ולא נשאר רק כנקודה א' לבד בשביל מקור השפע (כמו שמצמצם הרב המשפיע כל עצמות שכלו הרחב ולא נשאר רק כנקודה ממנו כדי הנצרך להשפיע למקבלים לבד כו'. ואח\"כ מנקודה זו נעשה הקו שהוא בחי' כח המביא להיות גילוי אור א\"ס אחר הצמצום די' לבא בהתפשטו' באו\"כ בע\"ס דאצי' כו'. וזהו ע\"י בחי' הקו דוקא שהוא כמו הממוצע בין נקודה דיו\"ד לשטח שבלתי הקו לא יבא הצמצום שנתעלם בי' לגילוי לעולם וכמו קוץ התחתון די' או כגופו של תמונת אות ה' שמורה ע\"ש העתיד כנ\"ל), וכידוע שגם מקור אור האצי' אין לו ערך כלל לגבי עצמו' המאציל דלאו מכא\"מ כלל<sup data-n=\"5749\">259</sup> והי' יכול להאציל עד אין שיעור שלא במהו' ע\"ס ברצון וחכ' ומדות כו', ע\"כ הוצרך להיות ע\"י צמצום הראשון עד שנעשה <span data-k=\"pg\">1090</span> ּ רק בחי' רושם כנקודה די', שעז\"א ישת חשך סתרו<sup data-n=\"5750\">260</sup> שהוא בחי' העלם דעצמו' שלפני גילוי דנקודה די' שאין אור זה דנקודה די' נחשב רק כטפה בים אוקיינוס לבד ולכך אינו אלא כנקודה א'<sup data-n=\"5751\">261</sup> די' לבד כו'. ואמנם מבחי' יו\"ד זה (שבוקע בטה\"ע כמ\"ש בס' עמק המלך<sup data-n=\"5752\">262</sup> ) הוא שנמשך להיות בבחי' ה' באורך [ורוחב באו\"כ] בכל בנין עולם אצי' (ע\"י בחי' הקו\"ח שנק' קו המדה בכלל שמודד כל או\"כ פנימי ומקיף בעגולים ויושר כו' (וזהו ממש בדוגמא שכותבים ה' בציור יו\"ד בתחלה דוקא ואח\"כ נמשך ממנו או\"ר כו' וד\"ל) (וזהו עזי וזמרת י\"ה אחר שנזמר ונקצר ב' אותיות די\"ה צמצום והתפשטות מעצמו' אור א\"ס שיבא מן ההעלם לגילוי בהתפשטותם כו', אזי ממילא ויהי לי לישועה מכח עצמות א\"ס דוקא במה שגברו החסדי' על הגבורות שנק' ישוע\"ה<sup data-n=\"5753\">263</sup> כידוע (והוא כנ\"ל בשרש התפשטות דחסדי' דבינה גבוה מצמצום די' והיינו בפנימית הכת\"ר ששם עצמות א\"ס ממש וע\"כ יש בכחה להביא ולהמשיך מצמצום די' להתפשטות כענין קוץ התחתון די'<sup data-n=\"5754\">264</sup> כו' ) וזהו ויהי לי לישועה מעצמות אוא\"ס שבכת\"ר דאגברי ימינא על שמאלא<sup data-n=\"5755\">265</sup> כו' גם בכת\"ר<sup data-n=\"5756\">266</sup> עצמו כמבואר במ\"א, וזהו יהי רצון מלפניך<sup data-n=\"5757\">267</sup> שיכבשו רחמי\"ך את כעסך כו').\n<b>אך</b> הנה כ\"ז כאשר בחי' אותיות דשם הוי' מאירים כסדרן בלי שום דבר חוצץ ומבדיל כלל (וכמו בשעת קי\"ס שא' זה אלי<sup data-n=\"5758\">268</sup> לנוכח וע\"כ א' [א]שירה להוי'<sup data-n=\"5759\">269</sup> כמו שהוא ממש, עזי וזמרת י\"ה כו' דזמרה זו ע\"ד הפשוט הוא בחי' שיר כמ[ו] שא'",[["5749","259","<b>דלאו מכא\"מ כלל</b>: ראה ת\"ז בהקדמה (יז, ב)."],["5750","260","<b>צמצום. . ישת חשך סתרו</b>: תהלים יח, כב. ראה גם לעיל פ' בא קכג, ג. וש\"נ."],["5751","261","<b>כנקודה א'</b>: א: אות. כא: כנקודה."],["5752","262","<b>יו\"ד. . שבוקע בטה\"ע. . עמק המלך</b>: ראה גם לעיל קנ, ב. וש\"נ."],["5753","263","<b>שגברו החסדי' על הגבורות שנק' ישוע\"ה</b>: ראה גם מאמרי אדה\"א בראשית ע' רפא ואילך."],["5754","264","<b>והיינו בפנימית. . די'</b>: כא: ליתא. וכנראה נשמט מפני תיבות הדומות די'. . די'."],["5755","265","<b>דאגברי </b>[אכא: דאגברא]<b> ימינא על שמאלא</b>: ראה זהר וישלח קסה, ב. קצח, ב. וארא לב, סע\"א. יתרו סז, א. אמור צב, ב."],["5756","266","<b>דאגברא. . בכת\"ר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670295\" data-slug=\"torat-chaim\" data-id=\"2300670295\">תו\"ח וירא קא, ב</a> ואילך."],["5757","267","<b>יהי רצון מלפניך</b>: סדר תקיעת שופר בסידור האריז\"ל [בדילוג]."],["5758","268","<b>זה אלי</b>: בשלח טו, ב."],["5759","269","<b>[א]שירה להוי'</b>: שם שם, א."]]],[2300550522,"אשירה להוי', רק שבבחי' אותיות י\"ה דשם הוי' א' וזמרת י\"ה שזה[ו] בחי' שיר פשוט דת[ענוג] הפ[שוט] וע[צמי'] שבפנימי' הכתר שמאיר בחו\"ב דאצי' מן ההעלם לגילוי שאז הוא שנק' שיר כפול<sup data-n=\"5760\">270</sup>, בחי' שיר שכפול בחו\"ב באי\"ן וי\"ש די\"ה כנ\"ל, והוא עונג המורכב [ב]נקודה דחכ' והשגה דבינה [וכמשי\"ת]. ופי' עזי בחי' מקיף דכת\"ר שלמעלה מחו\"ב הוא בחי' שיר פשוט דעצמות התענוג עליון<sup data-n=\"5761\">271</sup> (שז[הו] ש[א'] דא הוא ע\"י כו' ) ואח\"כ וזמרת י\"ה אז ויהי לי לישועה לפי שבזה נמתקו בחי' הגבורות דאבא בחסדי' דאימא מטעם הנ\"ל) (שעיקר הישועה הי' לפי שטענה מדה\"ד מה נשתנו אלו מאלו<sup data-n=\"5762\">272</sup> כו' וגבר עלינו חסדו להיות לישועה להצילם ממדה\"ד, והוא ע\"י הארת אור הע[צמי] דא\"ס בפנימי' הכתר דוקא כו'. וכך דוד א' פ' זה דעזי וזמרת י\"ה<sup data-n=\"5763\">273</sup> להמתיק הדינים קשי' שהי' עליו כמש\"א דחה דחיתני לנפול וה' עזרני<sup data-n=\"5764\">274</sup> עזי וזמרת י\"ה כו'. וכן ישעי' א' הנה אל ישועתי<sup data-n=\"5765\">275</sup> אבטח ולא אפחד ממדה\"ד כי עזי הוא<sup data-n=\"5766\">276</sup> כו' (ורק במ\"ש ישעי' הוסיף שם הוי' בא' כי עזי וזמרת י\"ה הוי' ויהי לי לישועה כו'<sup data-n=\"5767\">277</sup>, לפי ששרש הנביאי' בנו\"ה דבריאה<sup data-n=\"5768\">278</sup> שצריך שיומשך עד למטה מאצי' לבריאה עד עולם העשי' ממש ע\"כ א' י\"ה הוי' שנמשך מי\"ה זה<sup data-n=\"5769\">279</sup> להוי' בו\"ה שהן מדות ודבור. משא\"כ בדוד שלא הוצרך לזה כידוע דכתובים נאמרו ברוה\"ק<sup data-n=\"5770\">280</sup> שהוא בחי' המל'<sup data-n=\"5771\">281</sup> כמו שהוא למעלה בבחי' [ה]אצי' ממש קודם הצמצום המסך<sup data-n=\"5772\">282</sup> כו' כמו שרש תושב\"כ כו' וד\"ל). אבל הנה כאשר יש בחי' כיסוי ומסך מבדיל כמו בחי' מחיצה ש\"ב הנ\"ל [הנה] זה העושה בחי' כס ונרת\"ק לאותיות י\"ה דשם הוי' והוא בב' אופנים, א' שלא <span data-k=\"pg\">תקמה</span> ּ יאיר אור הא\"ס שבבחי' פנימי' הכתר באותיות די\"ה שהן חו\"ב דאצי' כו', והב' מה שלא יומשך מאותיות י\"ה לאותיות ו\"ה דשם הוי' (שזהו מש\"א דמחיצה ש\"ב מפסקת בין ישראל לאביהם שבשמים שהוא המפסיק בין י\"ה לו\"ה וגם בין כת\"ר לחו\"ב כו') שז\"א<sup data-n=\"5773\">283</sup> שאין השם שלם ואין הכסא שלם כו', והיינו מחמת קליפה דעמלק הנ\"ל שהוא המסך המבדיל ומעלים לאור [ד]י\"ה דחו\"ב וגם מונע הארת אור י\"ה דחו\"ב במדות ודבור שהן ו\"ה כו'.\n<b>ולהבין</b> זה בנש\"י שנק' נר הוי' וחלק הוי' ממש כמו כי אתה נרי הוי' כו', הנה תחלה י\"ל מהו בחי' י\"ה בנה\"א בד\"פ<sup data-n=\"5774\">284</sup>, דהנה ידוע שבחי' ההשגה והתפיסא בהתבוננו' דסוכ\"ע איך שנמשך להיות מקור לעולמות בבחי' ממלא (כמו שמן הי[ו\"ד] נמשך ה\"א בהתפשטות אור[ך ורוחב] כנ\"ל) [מ]זה",[["5760","270","<b>שיר פשוט. . כפול</b>: ראה זהר (רע\"מ) פינחס רכז, ב. לעיל פ' בא קו, ד. וש\"נ."],["5761","271","<b>עליון</b>: אכא: ליתא."],["5762","272","<b>מה נשתנו אלו מאלו</b>: שבת נה, א. ראה גם לעיל פ' בא פח, ד הערה 89."],["5763","273","<b>דוד. . דעזי וזמרת י\"ה</b>: תהלים קיח, יד."],["5764","274","<b>דחה דחיתני. . עזרני</b>: תהלים שם, יג."],["5765","275","<b>הנה אל ישועתי</b>: ישעי' יב, ג."],["5766","276","<b>הוא</b>: כא: ליתא."],["5767","277","<b>כו'</b>: כא: ליתא."],["5768","278","<b>הנביאי' בנו\"ה דבריאה</b>: ראה גם לעיל פ' בא קיד, ג. וש\"נ."],["5769","279","<b>זה</b>: כא: ליתא."],["5770","280","<b>דכתובים נאמרו ברוה\"ק</b>: ראה מו\"נ ח\"ב פמ\"ה. פרדס (שער עה\"כ) שכ\"ג מערכת כתובים. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181284\" data-slug=\"likkutei-sichot\" data-id=\"1300181284\">לקו\"ש בלק כרך יח ע' 275</a> הערה 31."],["5771","281","<b>ברוה\"ק שהוא בחי' המל'</b>: ראה פרדס (שער עה\"כ) שכ\"ג מערכת רוח."],["5772","282","<b>הצמצום המסך</b>: א: הצמצום והמסך. כא: צמצום המסך."],["5773","283","<b>שז\"א</b>: א: שזש\"א. כא: (וז\"ש."],["5774","284","<b>בנה\"א בד\"פ</b>: כא: בנפש האדם בדרך פרט."]]],[2300550535,"נולד בלב אוי\"ר<sup data-n=\"5775\">285</sup> שהן ו\"ה שנמשכים מה[\"א] עילאה דבינה כמו שבמילי דעלמא א\"ר<sup data-n=\"5776\">286</sup> בחוש שבהעמקת השגה ותפיסא באיזה דבר מה יולד בלב אהבה ותשוקה אוי\"ר לאותו הדבר כו', וכך הוא במצות האהבה והדביקות באלקים חיים אינו רק ע\"י ההתבוננות במוח בינה בפ' שמע ישראל<sup data-n=\"5777\">287</sup> שהוא<sup data-n=\"5778\">288</sup> ה' אחד<sup data-n=\"5779\">289</sup> ואז ואהבת את ה\"א דוקא כו' וד\"ל. וזהו בחי' אות הה[\"א] שבנשמה<sup data-n=\"5780\">290</sup> אבל אות הי[ו\"ד] הוא בחי' נקודה דחכ' שנק' אין בהעלם שלמעלה מן השגה דבינה עדיין כו', הנה זהו בבחי' סוכ\"ע שלמעלה עדיין מבחי' אור ושפע להיות מקור לעולמות כו' (וכמו במקיף וסובב הכללי הנ\"ל שלמעלה מבחי' קו\"ח כו') שמזה לא יולד עדיין התפעלות אוי\"ר בגילוי בלב מאחר שהוא למעלה מבחי' השגה עדיין, אלא הוא בבחי' ההעלם בבחי' נקודה די[ו\"ד] עדיין שהוא בחי' אה\"ר העצמי'<sup data-n=\"5781\">291</sup> שבכתר שלמעלה מן השכל והטעם לגמרי רק בבחי' רצ\"פ וע'<sup data-n=\"5782\">292</sup> עדיין, רק שמזה מסתעף בחי' התפעלו' השגה דבינה מן ההעלם די[ו\"ד] דחכ' מאין ליש ממש כו' [ב]ענין ו\"ה<sup data-n=\"5783\">293</sup> למעלה, שמבחי' צמצום די[ו\"ד] דוקא הוא שנמשך בחי' ההתפשטות דבינה וז\"ש כל הנשמה תהלל י\"ה<sup data-n=\"5784\">294</sup> דוקא וד\"ל (שזהו י\"ה דחו\"ב בכלל שהוא בחי' סו[בב ו]ממ[לא] בכלל כנ\"ל במ\"ש ביו\"ד נברא העוה\"ב כו' היינו בחי' י\"ה שבכ\"א מישראל בהתפעלותם מבחי' סו[בב ו]ממ[לא] בב' מדרגות הנ\"ל כמו בחי' י\"ה שלמעלה).\n<b>והנה</b> ידוע שיש ד' מדרגות דחילו ורחימו רחימו ודחילו<sup data-n=\"5785\">295</sup> ובכלל הן ב' מדרגות דחילו ורחימו עילאין ודחילו ורחימו תתאין<sup data-n=\"5786\">296</sup>, דחילו עילאה הוא בחי' י' דחכ' בהעלם כו'<sup data-n=\"5787\">297</sup> והוא בחי' ביטול הרצון בעצם כמו שהוא למעלה מן הטעם, ורחימו עילאה זהו בחי' התפעלות האהבה בשכל והשגה עצמי' בעונג נפלא ונק' אהבה בתענוגי' וזהו וזמרת י\"ה כו'. ודחילו ורחימו תתאין היינו בחי' האהבה זוטא שנולדה מן השכל בהתפעלות הלב דוקא שזהו וי\"ו דשם הוי' בנה\"א וה[\"א] אחרונה היינו בחי' קבלת עומ\"ש ביראה בביטול הישות וגסות כו'. וזהו תשובה תשוב ה'<sup data-n=\"5788\">298</sup> עילאה לגבי ו'<sup data-n=\"5789\">299</sup> למדות שבלב מלמעלה למטה או תשוב ה' תתאה לוי\"ו כו' שנק' תשו\"ת, אבל תשו\"ע<sup data-n=\"5790\">300</sup> היינו בפנימי' בינה<sup data-n=\"5791\">301</sup> דה' עילאה שזהו תשוב ה' שהוא ביטול השגה <span data-k=\"pg\">1092</span> ּ לגבי היו\"ד<sup data-n=\"5792\">302</sup> דחכ' כמו מה פשפשת<sup data-n=\"5793\">303</sup> כו' וד\"ל.\n<b>אך</b> הנה ידוע כאשר יש כיסוי ומסך מפסיק על בחי' י\"ה שבנפש שזהו כאשר בחי' קליפה דעמלק גובר באדם שהוא",[["5775","285","<b>אוי\"ר</b>: כא: אהבה או יראה."],["5776","286","<b>א\"ר</b>: אכא: אנו רואים."],["5777","287","<b>שמע ישראל</b>: ואתחנן ו, ד."],["5778","288","<b>שהוא</b>: א: שבאמרו. כא: ליתא."],["5779","289","<b>ה' אחד</b>: כא: שהוי' אלקינו כו'."],["5780","290","<b>שבנשמה</b>: כא: שבנש\"י."],["5781","291","<b>העצמי'</b>: א: העליונה."],["5782","292","<b>רצ\"פ וע'</b>: אכא: רצון פשוט ועצמי."],["5783","293","<b>ו\"ה</b>: שם: י\"ה."],["5784","294","<b>כל הנשמה תהלל י\"ה</b>: תהלים קנ, ו."],["5785","295","<b>דחילו ורחימו רחימו ודחילו</b>: ראה זהר (רע\"מ) נשא קכג, סע\"א. מאמרי אדה\"א בראשית ע' לד. וש\"נ. שע\"ת כו, א ובהערה 4."],["5786","296","<b>דחילו ורחימו עילאין. . תתאין</b>: ראה גם לעיל פ' בא קב, ד. וש\"נ."],["5787","297","<b>כו'</b>: א: כנ\"ל. כא: ליתא."],["5788","298","<b>תשובה תשוב ה'</b>: ראה זהר (רע\"מ) נשא קכב, סע\"א."],["5789","299","<b>תשוב ה' עילאה לגבי ו'</b>: ראה גם מאמרי אדה\"א דברים ח\"א ס\"ע רצג."],["5790","300","<b>תשו\"ת. . תשו\"ע</b>: ראה גם לעיל פ' בשלח רל, א."],["5791","301","<b>תשו\"ע. . בינה</b>: ראה אגה\"ת פ\"ח ופ\"ט ובליקוט פי' שם."],["5792","302","<b>תשו\"ע. . דה'. . לגבי היו\"ד</b>: ראה גם לעיל פ' בשלח רל, א."],["5793","303","<b>מה פשפשת</b>: זהר בהקדמה א, ב."]]],[2300550548,"ענין גסה\"ר וחוצפא דאפי' כלפי שמיא מהניא<sup data-n=\"5794\">304</sup>, דהיינו שגם שרואה בעין השכל בחו\"ב בנפשו בהשגה האלקי' בהתבוננות ביחו\"ע ויחו\"ת<sup data-n=\"5795\">305</sup> בק\"ש אף שמעמיק דעתו עד שיכיר הכרה שלימה במוחו איך שהוא ית' סוכ\"ע וממכ\"ע (שזהו בי\"ה שבנפש כו' ), עכ\"ז לא תתפעל נפשו כלל ולא יזוז ממקומו ומהותו הראשון אפילו כמלא נימא בפר\"ע כו' ל[א]מר שלום יהי' לי כי בשרירות לבי אלך<sup data-n=\"5796\">306</sup> כו'. שזהו רק מצד גסה\"ר שבנה\"ב החומרי' שקשה כאבן ונק' לב האבן, שאע\"פ שלבבו יבין האמת, מ\"מ יתעקש בעקשות קשה ובנצחון גדול בנפשו להיות בבחי' נפרד לילך שובב בדרך לבו למלאות כל תאוות[י]ו הרעים ולא יפול בלבבו כלל מכל אשר נראה אור האלקי במוחו ולבו, לבלתי שום לב לזה כלל רק מחמת חוצפא ועזות קשה כו'. ולא עוד שמורד שאינו שם לב לזה, אלא שעומד במרדו ומקשה את לבו הגס לעמוד לנגד לבלבל במח\"ז שונות עד שיוסר ממוחו ולבו מכל אשר נגע במוחו ולבו השגה האלקי', וכל כח הרע שבנה\"ט יעמוד לנגד זה, כמו שישים נפשו במס\"נ במלחמה לעמוד על המנגד לו לנקו[דת] חייו כי זהו מטבע הגסות והחוצפא לשנוא מאד לכל אשר עולה לה' באהבה האלקי בהתנשאו' כו'. וע\"כ בהעלות הנשמה האלקי' בהתלהבו' ותשוקת הלב בהתפעלות ההשגה האלקי' להדבק באלקים חיים, הנה טבע קליפה דעמלק שבנה\"ט לעמוד לנגד לבטל ולהסתיר האור הזה בכמה מיני תחבולות שונות בריבוי מחשבות זרות וכה\"ג עד שיפול למטה וד\"ל.\n<b>והנה</b> מחיצה של ברזל זו עושה בזה מניעת האור בב' דברים, א' שיחש[י]ך האור דב' אותיות י\"ה שבנפש לבלתי יאיר אור האלקי בנקודה די[ו\"ד] שהוא החכמה כח הביטול בעצם ולא יאיר גם בבינה שהוא הה[\"א] בהשגה האלקי' שלא יתפעל באהבה בתענוגים שנק' רחימו עילאה כלל<sup data-n=\"5797\">307</sup> (ונק' טמטום<sup data-n=\"5798\">308</sup> הלב והמוח<sup data-n=\"5799\">309</sup> שהן י\"ה חו\"ב שבנה\"א). והב' במניעת האור האלקי מי\"ה לו\"ה שזהו מה שגם מן החיצוני' השגה שבמוח ביחו\"ע ויחו\"ת לא יתפעל בלבו כלל וכלל מזה ולא ירגיש לבו בהשגה זו כלל (ונק' טמטום הלב<sup data-n=\"5800\">310</sup> ) לפי שלבו כלב האבן ונבדל מן י\"ה שבנפש כו' (ובמ\"א מבואר שזהו טומאת הנפש עצמה שעזה וקשה היא בטבעה ומהותה (והוא בחי' עורף לנגד הפגם<sup data-n=\"5801\">311</sup> שהוא עקשות ונצחון שברצון הע[צמי] ע\"כ יחשיך גם אור הכת\"ר דחו\"ב כו'), וזהו שנק' מחיצה ש\"ב דוקא שקשה ביותר לבלתי ירך וימס גם מפני אש האלקי שבי\"ה שנק' שלהבת י\"ה<sup data-n=\"5802\">312</sup>,",[["5794","304","<b>וחוצפא דאפי' כלפי שמיא מהניא</b>: סנהדרין קה, א."],["5795","305","<b>ביחו\"ע ויחו\"ת</b>: זהר בהקדמה יב, א."],["5796","306","<b>ל[א]מר שלום. . אלך</b>: נצבים כט, יח."],["5797","307","<b>כלל</b>: א: ליתא. כא: כנ\"ל)."],["5798","308","<b>טמטום. . והמוח</b>: ראה גם לעיל פ' שמות ב, ב. וש\"נ."],["5799","309","<b>הלב והמוח</b>: אכא: המוח."],["5800","310","<b>טמטום הלב</b>: ראה גם לעיל פ' שמות ב, ב. וש\"נ."],["5801","311","<b>לנגד הפגם</b>: א: לנגד הפנים. כא: לגבי הפנים."],["5802","312","<b>שלהבת י\"ה</b>: שה\"ש ח, ו."]]],[2300550561,"אע\"פ שא' ברזל קשה אש מפעפעו<sup data-n=\"5803\">313</sup> אבל אין האור האלקי מאיר בי\"ה שבנפש מטעם הנ\"ל (ומחיצה זו קשה יותר ממחיצה שנעשה ע\"י העוונות גמורים שבאים מן הז\"מ רעות דק\"נ כחום התאוה רעה ורציחה וגזל כו'. דאע\"פ שא' עוונותיכם מבדילים ביניכם לבין אלקיכם היינו שמבדיל רק בין ו\"ה לי\"ה שאין האור האלקי שבי\"ה שבנפש מאיר <span data-k=\"pg\">תקמו</span> ּ בו\"ה שהוא הלב ומעשה (כמו ע\"י הסייף שנלקח הראש מן הגוף כו'), אבל זהו רק ע\"י פגם במדות דחו\"ג ולא בחו\"ב ורצון ותענוג, ויכול להיות שיוסר מסך מבדיל זה ע\"י סליחת ומחילת העון כמו ביו\"כ שאמר אנכי הוא מוחה פשעיך למעני<sup data-n=\"5804\">314</sup> עד שחטאיכם כשלג ילבינו<sup data-n=\"5805\">315</sup> כו', ויוסר המבדיל הזה ממילא והי' כלא הי' כמ\"ש לפני הוי' תטהרו<sup data-n=\"5806\">316</sup>. אבל מחיצה זו של ברזל שמבחי' קליפה דעמלק שהוא בעצם הנפש ממש בבחי' טבעית וע[צמי'] שהוא ענין החוצפא ועזות קשה בעצם שנק' ראשית גוים כנ\"ל לא יועיל גם מחילת העוונות ביוהכ\"פ כו').\n<b>והנה</b> ענין התיקון לב' דברים המונעי' הנ\"ל במחיצה זו ש\"ב הוא להסיר המניעה ע\"י ב' דברים, א' שצריך לעשות פרצות רבות במחיצה זאת ש\"ב שיוכל האור האלקי להאיר דרך הפרצות. והב' שאח\"ז יומשך האור האלקי בפרצות הללו בכל האותיות דשם הוי' [ש]בנש\"י, דהיינו שיאיר תחלה באותיות די\"ה בבחי' חו\"ב שבנפש ואח\"ז יומשך מי\"ה לו\"ה ולא יסתיר מחיצה זו כלל. אך האיך יוכל להיות פרצות וסדקים רבים במחיצה [זו] ש\"ב שקשה [היא] ביותר כנ\"ל, הענין הוא כמבואר למעלה דאין מחיצה זו מפסקת רק בין ישראל לאביהם כו' ולא בין אביהם שבשמים לישראל. דהנה ענין בחי' אור העצמות דא\"ס ב\"ה ממש שלפני הצמצום הראשון הנ\"ל (שלמעלה מסו[ובב] וממ[לא] כנ\"ל והוא קודם שצמצם אור העצמי להיות מק\"פ וחלל כו' שקדם לבחי' חשך סתרו כו') קמי' ממש גם חשך לא יחשיך כלל כו', וכאשר יאיר קצת אור מן העצמות יבקע את ההעלם וצמצום הראשון ויאיר בנקוד' וקו\"ח שהוא צמצום והתפשטו' די\"ה בכלל כנ\"ל, עי\"ז נבקע ונפרץ גם בחי' מסך המבדיל דקליפת עמלק שלמטה המסתיר ומכסה על י\"ה שלמעלה וי\"ה שלמטה בנש\"י. כי גם בחי' החושך נעשה אור ואינו מסתיר כלל וכלל שאין מחיצה זו מפסקת כלל לגבי עצמות אור א\"ס ב\"ה דקמי' כחשיכה כאורה<sup data-n=\"5807\">317</sup> כו', וכמ\"ש הנה הוא עומד אחר כתלינו<sup data-n=\"5808\">318</sup> מציץ מן החרכים כו' שנעשה חרכים וסדקים מפולשים במחיצה וכותל זה הנ\"ל, וע\"י בחי' הפרצים וסדקים הללו שנעשה כאשר בא האור מקרוב כמו כאשר יבא אור השמש בבוקר [ב]סמוך בעובי הרקיע שיבקע את העלם עובי הרקיע ויזרח אורו בדרך",[["5803","313","<b>ברזל קשה אש מפעפעו</b>: ב\"ב י, א (ובהגהת הב\"ח). קה\"ר פ\"ז, כו (ב)."],["5804","314","<b>אנכי הוא </b>[אכא: ליתא]<b> מוחה פשעיך למעני</b>: ישעי' מג, כה."],["5805","315","<b>שחטאיכם כשלג ילבינו</b>: ישעי' א, יח."],["5806","316","<b>לפני הוי' תטהרו</b>: אחרי טז, ל."],["5807","317","<b>כחשיכה כאורה</b>: תהלים קלט, יב."],["5808","318","<b>הנה הוא </b>[א: זה]<b> עומד אחר כתלינו</b>: שה\"ש ב, ט. ראה גם לקמן הערה 434."]]],[2300550574,"בקיעה כו', אזי יאיר אור א\"ס בכל שם הוי' שבנש\"י בלי דבר חוצץ כלל דהיינו שיאיר באותיות די\"ה גם מן ההעלם וכסוי דמחיצה ש\"ב הנ\"ל הנק' כס י\"ה בדרך בקיעת אור מן החושך והעלם כנ\"ל, ומבחי' י\"ה דחו\"ב יומשך אור הא\"ס שבי\"ה גם בו\"ה בלי שום מונע ומפסיק כלל כי נפרק<sup data-n=\"5809\">319</sup> פרצות וסדקים במחיצה זאת (ונעשה רך כהמס דונג מפני אש<sup data-n=\"5810\">320</sup> ממש). וראי' לזה מאשר נשבר לב האבן דרשעים גמורים בעשי\"ת לפי שקרוב מאיר אור כ\"ע<sup data-n=\"5811\">322</sup> דא\"ס ב\"ה כמ\"ש בהיותו קרוב<sup data-n=\"5812\">321</sup> (כמו עומד אחר כתלינו) וכמו ביצ\"מ שנגלה עליהם כו'<sup data-n=\"5813\">323</sup> ונשבר כל תוקף וקושי הלב בפר\"ע<sup data-n=\"5814\">324</sup> בהגלות נגלות אור [מעצמי'] א\"ס ממש כמ\"ש ועברתי<sup data-n=\"5815\">325</sup> כו' (כמ\"ש הדו\"ך רשעים תחתם<sup data-n=\"5816\">326</sup> ) וכמבואר במ\"א בפסוק<sup data-n=\"5817\">327</sup> <span data-k=\"pg\">1094</span> ּ הם המדברים אל פרעה<sup data-n=\"5818\">328</sup> הוא משה שושבינא דמלכא כו' דפרעה עור\"ף<sup data-n=\"5819\">329</sup> קשה כברזל ונשבר רק ע\"י משה דוקא שהי' בבחי' אי\"ן ומה ממש שבו שורה עצמות א\"ס בחי' אי\"ן האמיתי כו' ([ו]כמשי\"ת בענין הציץ). וזהו כי יד על כס י\"ה מלחמה לה' בעמלק כו', שאין מלחמה הזאת למחות זכר עמלק להסיר את המחיצה ש\"ב הנ\"ל או לשבור אותו, הוא רק לה' לבדו שידו על כס י\"ה להאיר מן ההעלם דכיסוי זה מטעם הנ\"ל כדי להיות השם שלם והכסא שלם כנ\"ל וד\"ל.\n<b>והנה</b> כללות כל ענין הנ\"ל בתיקון להסיר המסך המבדיל דקליפת עמלק הנ\"ל שזהו ע\"י הארת האור דעצמות א\"ס ב\"ה דוקא שבוקע ויאיר גם בחושך כו' הנה זה הי' בענין מעשה הציץ שהי' על מצח אהרן כה\"ג כו', דהנה מבואר למעלה בפי' ציץ שיש בזה ג' ענינים, א' ענין הארת האור וזיו המתנוצץ כפשוטו כמו עליו יציץ נזרו וכה\"ג כו'. והב' ענין הסתכלות והבטה מלשון מציץ מן החרכים כו'. והג' ענין הנצה ופריחה יציץ ופרח<sup data-n=\"5820\">330</sup> כו' הנצו הרמונים כו', וכל ג' אלה הפי[רושי'] באים בענין א' והוא רק מה שיאיר אור וזיו בדרך בקיעה, כמו במסך באריגה שבוקע האור דרך נקבים וסדקים מפולשים, וכן בכותל ומחיצה שנק' חרכים קטנים כמ\"ש מציץ מן החרכים כו', וכמו בקיעת אור השחר בעובי הרקיע כו' שזהו ענין הנצה דנץ החמה בעובי הרקיע, וכך הוא בענין הג' דפריחה והנצה שיוצא תחלת הצמיחה בדרך בקיעה מן ההעלם דוקא. וכך יובן למעלה בענין הציץ דאהרן כה\"ג שענינ[ו] הי' בחי' בקיעת האור הנעלם שבעצמות א\"ס שהוא כאור הבוקע המסך כמציץ מן החרכים הנ\"ל, שהוא מה שמבואר למעלה בענין אתעדל\"ע באה\"ר העצמ[י]' ממש שמצד עצמו שלא ע\"י אתעדל\"ת כלל שהוא כמו דמיון הטל שמלחלח הארץ שמעורר תוס' כח מכח העצמו' כו',",[["5809","319","<b>נפרק</b>: א: נפרצו. כא: נפרץ."],["5810","320","<b>כהמס דונג מפני אש</b>: תהלים סח, ג."],["5811","322","<b>כ\"ע</b>: כא: העצמי'."],["5812","321","<b>בעשי\"ת. . בהיותו קרוב</b>: ישעי' נה, ו. ר\"ה יח, א. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'קל. וש\"נ."],["5813","323","<b>שנגלה עליהם כו' </b>[כא: ליתא]: הגדה של פסח פיסקא מצה זו."],["5814","324","<b>בפר\"ע</b>: א: דפרעה."],["5815","325","<b>ועברתי</b>: בא יב, ב."],["5816","326","<b>הדו\"ך רשעים תחתם</b>: איוב מ, יב [ושם: והדוך]. ראה גם מאמרי אדה\"א שמות ח\"ב ע' תקלח. דברים ח\"א ע' כז. נ\"ך ע' תקה ואילך."],["5817","327","<b>בפסוק</b>: א: בפי'. כא: ליתא."],["5818","328","<b>הם המדברים אל פרעה</b>: וארא ו, כז [בדילוג]. ראה לעיל פ' וארא פב, ב ואילך."],["5819","329","<b>דפרעה עור\"ף</b>: ראה לקו\"ת להאריז\"ל ר\"פ שמות. הנסמן לעיל פ' שמות יט, ב."],["5820","330","<b>יציץ ופרח</b>: ישעי' כז, ו."]]],[2300550585,"כך זהו כח המעורר לנש\"י באה\"ר הטבעי' ובהתעוררות התשובה האמיתי מקרב ולב עמוק (וכמו בעשי\"ת [שגם] הקל שבקלים<sup data-n=\"5821\">332</sup> מתעוררי' בתשובה שלמה בבכי'<sup data-n=\"5822\">331</sup> מקירת הלב מצד שנתקרב בחי' המאור לגבי הניצוצות<sup data-n=\"5823\">333</sup> שלמטה כמ\"ש בהיותו קרוב שממילא נמשכו הניצוצי' ונכללי' במאור [כ]ענין משכנ\"י אחריך נרוצה ממילא כו' ). וזהו ענין הפרצות וסדקים מפולשים שנעשו גם בכותל ומחיצה של ברזל הנ\"ל שהוא תוקף וגסות [ה]קליפה דעמלק בלב כאו\"א שיכנע וישבר להיות מתעורר בתשובה שלימה והיינו מצד שמציץ מן החרכים לפי שבקירוב האור דעצמות גם חשך לא יחשיך וגם הקשה כברזל נעשה רך כנ\"ל וד\"ל. וזהו ג\"כ<sup data-n=\"5824\">334</sup> ענין הבטה והסתכלות שבא בדרך בקיעה דוקא כמו חרכים קטנים שנעשים גם במחיצה ש\"ב שעי\"ז נעשי' הרהורי תשובה למטה בבחי' כח המושך מלמעלה למטה מטה כנ\"ל, ואע\"פ שהחרכים קטנים מאד יותר יוכל לראות בהן בהסתכלות חזקה בנש\"י שלמטה<sup data-n=\"5825\">335</sup> מן ההשגחה<sup data-n=\"5826\">336</sup> וראי' בחלונות הפתוחים למעלה שזהו יתרון מעלה דבע\"ת מצ\"ג שפתוחים לבם כחלונות כו' (וכמאמר פתחו לי כחודו של מחט<sup data-n=\"5827\">337</sup> ואני אפתח לכם כו'), ויהי' איך שיהי' שיהי' בחי' הבטה זאת שמביט ומסתכל גם בחרכים נק' בקיעת האור מן <span data-k=\"pg\">תקמז</span> ּ ההעלם שגדול יותר מגופו של אור המאיר גם בתו\"מ. וזהו ענין הציץ שהי' על מצח אהרן שבו הי' גילוי אור המתנוצץ בדרך בקיעה מבחי' ההעלם, והיינו כמו יציאת האור מן הסדק הקצר שנק' הצצה כמו הנץ החמה כו' דהיינו בעת שמתחלת להאיר בעובי הרקיע שבוקע הרקיע, והוא ענין א' עם הבטה והסתכלות דרך פרצה קטנה או כענין הנ\"ל בפריחה וצמיחה בתחלתה מן ההעלם לגילוי כו'. שמכ\"ז יובן למעלה שזהו רק ענין הבטה והסתכלו' שבאה מעצמות אור א\"ס בציץ זה לבקוע הארה יתירה בבחי' ההעלם דעצמ[ו]' שלפני הצמצום הראשון והיינו שמאיר בו מבחי' רעדכ\"ר (כמשי\"ת). והוא ענין הציץ שעשה משה כמו [ענין] יציץ נזרו כו', שהרי הי' הציץ מרצה ומכפר בתמידות על ישראל כמ\"ש והי' על מצחו תמיד לרצון כו' כי אין מחיצה זו מפסקת כלל בין אביהם שבשמים לבין ישראל משום דקמי' גם חושך לא יחשיך כו', ויוסר המסך מבדיל בב' אופנים הנ\"ל, א' שיאיר אור א\"ס ב\"ה בי\"ה דשם הוי' דנשמה<sup data-n=\"5828\">338</sup> ומי\"ה יומשך לו\"ה בלי העלם והסתר כלל כו' וד\"ל (והיינו כמו ענין הנ\"ל במ\"ש כי יד על כס י\"ה מלחמה לה' בעמלק לעשות השם שלם והכסא שלם כנ\"ל, כך הי' עיקר ענין הציץ הזה במצח אהרן דוקא שלא יבדיל כל מסך ומחיצה כנ\"ל, כמש\"א שהציץ הי' מכפר על עזות פנים<sup data-n=\"5829\">339</sup> דוקא שזהו בחי' קליפה דעמלק כנ\"ל).",[["5821","332","<b>הקל שבקלים</b>: נסמן לעיל שם הערה 170."],["5822","331","<b>בעשי\"ת [שגם] הקל שבקלים. . בבכי'</b>: נסמן לעיל שמח, א הערה 169."],["5823","333","<b>שנתקרב בחי' המאור לגבי הניצוצות</b>: ראה גם לעיל שמח, א. וש\"נ."],["5824","334","<b>ג\"כ</b>: כא: ליתא."],["5825","335","<b>שלמטה</b>: איגכג: כבפנים. כא: שלמעלה."],["5826","336","<b>ההשגחה</b>: אכא: ההשגה. יגכג: כבפנים."],["5827","337","<b>פתחו לי כחודו </b>[אכא: כחודה]<b> של מחט</b>: ראה ס' חרדים בהקדמה. מאמרי אדה\"ז תקס\"ח ח\"א ע' יז ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370424\" data-slug=\"torah-or\" data-id=\"3901370424\">תו\"א צד, ג</a>."],["5828","338","<b>דנשמה</b>: אכא: דנש\"י."],["5829","339","<b>שהציץ הי' מכפר על עזות פנים</b>: ערכין טז, א. ראה גם לקמן שעא, ג."]]]]});
